NAME = 'TpiKJPB: King Jems Pisin Baibel'
BOOK = 'Luke'

CHAPTERS = {
    1: {
        1: '¶ Bikos planti i bin kisim wok long han bilong ol long putim klia long lain wanpela tokaut long ol dispela samting, dispela, tru tumas, ol man i bilip namel long yumi,',
        2: 'Yes, olsem ol i givim ol long yumi, husat long stat em ol witnes i lukim long ai, na ol wokman bilong tok bilong God,',
        3: 'Em i luk olsem i gutpela long ai bilong mi tu, taim mi bin gat save i inap tru long olgeta samting i kam long pastaim tru, long raitim long yu long lain, Tiofilas i gutpela olgeta moa,',
        4: 'Inap long yu ken save long ol dispela samting i tru olgeta, we yu bin kisim skul long en.',
        5: '¶ I gat i stap long ol de bilong Herot, king bilong Judia, wanpela pris husat nem bilong em em Sakaraias, bilong lain wok bilong Abaia. Na meri bilong em em i bilong ol pikinini meri bilong Eron, na nem bilong em em Ilisabet.',
        6: 'Na tupela wantaim i stretpela long ai bilong God, na ol i wokabaut insait long olgeta tok strong na ol lo Bikpela i makim na ol i no gat asua.',
        7: 'Na ol i no gat pikinini, bikos Ilisabet i no inap long karim, na tupela wantaim i bagarap tru nau wantaim ol yia.',
        8: 'Na em i kamap olsem, long taim em i wokim wok long opis bilong pris long ai bilong God i bihainim lain bilong lain wok bilong em,',
        9: 'Bilong bihainim kastam bilong opis bilong pris, hap skel bilong em em bilong kukim insens taim em i go insait long tempel bilong Bikpela.',
        10: 'Na dispela planti manmeri tru olgeta bilong ol manmeri i beten ausait long taim bilong insens.',
        11: 'Na i gat wanpela ensel bilong Bikpela i kamap ples klia long em taim ensel i sanap long han sut sait bilong alta bilong insens.',
        12: 'Na taim Sakaraias i lukim em, em i pilim wari, na pret i pundaun antap long em.',
        13: 'Tasol ensel i tokim em, No ken pret, Sakaraias. Long wanem, God i harim pinis prea bilong yu. Na meri bilong yu Ilisabet bai karim wanpela pikinini man long yu, na yu bai kolim nem bilong em Jon.',
        14: 'Na yu bai gat amamas tru na amamas. Na planti bai wokim amamas tru taim mama i karim em.',
        15: 'Long wanem, em bai gat biknem long ai bilong Bikpela, na em bai i no inap dringim wain o strongpela dring. Na em bai pulap wantaim Holi Spirit, yes, i stat long taim em i stap long bel bilong mama bilong em.',
        16: 'Na em bai tanim planti bilong ol pikinini bilong Isrel i go long Bikpela, God bilong ol.',
        17: 'Na em bai go paslain long em long spirit na pawa bilong Ilaias, long tanim ol bel bilong ol papa i go long ol pikinini, na ol man bilong sakim tok i go long save tru bilong ol stretpela man, long redim wanpela lain manmeri i redi long Bikpela',
        18: 'Na Sakaraias i tokim ensel, Long wanem rot bai mi save long dispela? Long wanem, mi wanpela lapun man, na meri bilong mi i bagarap tru wantaim ol yia.',
        19: 'Na ensel i bekim na tokim em, Mi Gebriel, husat i sanap long pes bilong God. Na em i salim mi long toktok long yu, na long soim yu ol dispela gutpela nius.',
        20: 'Na, lukim, yu bai stap mauspas, na yu bai i no inap toktok, inap long dispela de ol dispela samting bai kamap pinis, bilong wanem, yu no bilipim ol toktok bilong mi, dispela bai kamap pinis long taim bilong ol.',
        21: 'Na ol manmeri i wetim Sakaraias, na ol i tingting planti long em i stap yet longpela taim olsem insait long tempel.',
        22: 'Na taim em i kam ausait, em i no inap long toktok long ol. Na ol i kisim save long em i bin lukim wanpela driman samting insait long tempel. Long wanem, em i wokim mak wantaim han long ol, na stap mauspas yet.',
        23: 'Na em i kamap olsem, long, long taim stret long ol de bilong wokim wok bilong em i kamap pinis, em i lusim dispela hap na go long haus bilong em yet.',
        24: 'Na bihain long ol dispela de meri bilong em Ilisabet i kisim bel, na haitim em yet faipela mun, i spik,',
        25: 'Bikpela i bin mekim olsem long mi long ol de we em i lukluk long mi long en, long tekewe sem bilong mi namel long ol man.',
        26: '¶ Na long namba sikis mun God i salim ensel Gebriel i go long wanpela biktaun bilong Galili, husat nem bilong em em Nasaret,',
        27: 'Long wanpela meri i no bin slip wantaim man i marit long kontrak long wanpela man husat nem bilong em em Josep, bilong hauslain bilong Devit. Na nem bilong dispela meri i no bin slip wantaim man em Maria.',
        28: 'Na ensel i kam long em, na tok, Gude, yu husat i gat gutpela amamas tru, Bikpela i stap wantaim yu. Blesing i stap long yu namel long ol meri.',
        29: 'Na taim meri i lukim em, em i pilim wari long toktok bilong em, na tingting nabaut insait long tingting bilong em long dispela em i ken stap wanem kain tok gude.',
        30: 'Na ensel i tokim em, No ken pret, Maria. Long wanem, yu bin painim pinis gutpela amamas wantaim God.',
        31: 'Na, lukim, yu bai kisim bel insait long bel bilong yu, na karim wanpela pikinini man, na yu bai kolim nem bilong em JISAS.',
        32: 'Em bai gat biknem, na ol bai kolim em Pikinini Man bilong Man i Antap Moa Olgeta. Na God Bikpela bai givim long em sia king bilong tumbuna papa bilong em Devit.',
        33: 'Na em bai bosim kingdom long hauslain bilong Jekop oltaim oltaim. Na long kingdom bilong em bai i no gat pinis.',
        34: 'Nau Maria i tokim ensel, Dispela bai kamap olsem wanem, taim yumi luksave long mi no save long wanpela man?',
        35: 'Na ensel i bekim na tokim em, Holi Spirit bai kam antap long yu, na pawa bilong Man i Antap Moa Olgeta bai karamapim yu. Olsem na tu dispela samting holi, dispela yu bai karim, bai ol i kolim Pikinini Man bilong God.',
        36: 'Na, lukim, kandere bilong yu Ilisabet, em tu i bin kisim bel long karim wanpela pikinini man long taim em i stap lapun. Na dispela em i namba sikis mun long em, husat ol i bin kolim meri i no inap long karim.',
        37: 'Long wanem, long God i no gat wanpela samting i no gat rot olgeta long kamap.',
        38: 'Na Maria i tok, Lukim wokmeri bilong Bikpela. Em i ken stap olsem long mi bilong bihainim tok bilong yu. Na ensel i lusim em.',
        39: '¶ Na Maria i kirap long ol dispela de, na go hariap long hap graun i gat ol liklik maunten, i go long wanpela biktaun bilong Judia.',
        40: 'Na em i go insait long haus bilong Sakaraias, na tok gude long Ilisabet.',
        41: 'Na em i kamap olsem, long, taim Ilisabet i harim tok gude bilong Maria, dispela bebi i kalap insait long bel bilong em. Na Ilisabet i pulap wantaim Holi Spirit.',
        42: 'Na em i toktok wantaim bikpela nek, na tok, Blesing i stap long yu namel long ol meri, na blesing i stap long kaikai bilong bel bilong yu.',
        43: 'Na dispela i olsem wanem long mi, long mama bilong Bikpela bilong mi i ken kam long mi?',
        44: 'Long wanem, harim, long taim stret long nek bilong tok gude bilong yu i pairap insait long tupela ia bilong mi, dispela bebi i kalap insait long bel bilong mi, long wanem, em i amamas tru.',
        45: 'Na blesing i stap long meri husat i bin bilip. Long wanem, bai i gat ol dispela samting i kamap, dispela wanpela i tokim em i kam long Bikpela.',
        46: 'Na Maria i tok, Tewel bilong mi i litimapim nem bilong Bikpela,',
        47: 'Na spirit bilong mi i bin wokim amamas tru insait long God, Man Bilong Kisim Bek bilong mi.',
        48: 'Long wanem, em i bin lukluk gut long sindaun i daunbilo bilong wokmeri bilong em. Long wanem, lukim, i stat long nau i go, olgeta lain tumbuna bai kolim mi meri i gat blesing.',
        49: 'Long wanem, em husat i strongpela i bin mekim ol bikpela samting long mi. Na nem bilong em em i holi.',
        50: 'Na sori bilong em i stap long ol husat i pret long em long lain tumbuna i go long lain tumbuna.',
        51: 'Em i bin soim strong wantaim han bilong em. Em i bin brukim nabaut ol bikhet man insait long tingting nating bilong ol bel bilong ol.',
        52: 'Em i bin putim i go daun ol strongpela man i lusim ol sia bilong ol, na litimapim ol man i gat namba daunbilo.',
        53: 'Em i bin pulimapim ol man i gat hangre wantaim ol gutpela samting. Na ol maniman em i bin salim i go emti.',
        54: 'Em i bin helpim wokboi bilong em Isrel, long taim em i tingim gen sori bilong em,',
        55: 'Olsem em i bin tokim ol tumbuna papa bilong yumi, long Ebraham, na long tumbuna pikinini bilong em oltaim oltaim.',
        56: 'Na Maria i stap wantaim em klostu olsem tripela mun, na em i go bek long haus bilong em yet.',
        57: '¶ Nau taim bilong Ilisabet i kam pulap long em i mas karim pikinini. Na em i karim wanpela pikinini man.',
        58: 'Na ol lain i stap klostu long em na ol kandere bilong em i harim long Bikpela i bin soim bikpela sori long em olsem wanem. Na ol i wokim amamas tru wantaim em.',
        59: 'Na em i kamap olsem, long namba et de ol i kam long katim skin bilong pikinini. Na ol i kolim em Sakaraias, i bihainim nem bilong papa bilong em.',
        60: 'Na mama bilong em i bekim na tok, I no olsem. Tasol yumi bai kolim em Jon.',
        61: 'Na ol i tokim em, I no gat wanpela bilong ol kandere bilong yu husat ol i kolim long dispela nem.',
        62: 'Na ol i wokim ol mak long papa bilong em, long em i gat laik long ol i kolim em olsem wanem.',
        63: 'Na em i askim long wanpela tebol bilong rait, na raitim, i tok, Nem bilong em em Jon. Na olgeta i tingting planti.',
        64: 'Na maus bilong em i op wantu, na tang bilong em i lus, na em i toktok, na litimapim nem bilong God.',
        65: 'Na pret i kam antap long olgeta husat i stap raun nabaut long ol. Na olgeta dispela toktok ol i stori ausait, long olgeta hap bilong olgeta hap graun i gat ol liklik maunten bilong Judia.',
        66: 'Na ol olgeta husat i harim ol i slipim ol insait long ol bel bilong ol, i spik, Dispela pikinini bai stap wanem kain! Na han bilong Bikpela i stap wantaim em.',
        67: '¶ Na papa bilong em Sakaraias i pulap wantaim Holi Spirit, na autim tok profet, i spik,',
        68: 'Blesing i stap long God Bikpela bilong Isrel. Long wanem, em i bin kam lukim na baim bek lain manmeri bilong em,',
        69: 'Na em i bin kirapim wanpela kom bilong kisim bek bilong helpim yumi insait long hauslain bilong wokboi bilong em Devit,',
        70: 'Olsem em i toktok long maus bilong ol profet holi bilong em, husat i bin stap inap long taim dispela graun i stat,',
        71: 'Inap long em i ken kisim bek yumi long ol birua bilong yumi, na long han bilong olgeta husat i hetim yumi,',
        72: 'Long wokim dispela sori em i bin promisim long ol tumbuna papa bilong yumi, na long holim tingting long kontrak holi bilong em,',
        73: 'Dispela promis antap em i promis antap i go long tumbuna papa bilong yumi Ebraham,',
        74: 'Long em bai givim long yumi, inap long taim em bai kisim bek yumi ausait long han bilong ol birua bilong yumi, yumi ken bihainim em taim yumi no gat pret,',
        75: 'Long pasin holi na stretpela pasin long ai bilong em, olgeta de bilong laip bilong yumi.',
        76: 'Na yu, pikinini, ol bai kolim profet bilong Man i Antap Moa Olgeta. Long wanem, yu bai go paslain long pes bilong Bikpela long redim ol rot bilong em,',
        77: 'Long givim save bilong pasin bilong kisim bek i go long ol manmeri bilong em long wok bilong pasin bilong lusim ol sin bilong ol,',
        78: 'Long wok bilong sori i isi moa bilong God bilong yumi, we long dispela rot sankamap i kam long antap tru i bin kam lukim yumi,',
        79: 'Long givim lait long ol husat i sindaun long tudak na long tewel bilong san bilong dai, long stiaim ol lek bilong yumi i go long rot bilong bel isi.',
        80: 'Na dispela pikinini i go bikpela, na wok long kamap strong insait long spirit, na em i stap long ol ples i no gat man inap long de bilong em bilong kamap ples klia long Isrel.',
    },
    2: {
        1: '¶ Na em i kamap olsem long ol dispela de, long i gat wanpela strongpela tokaut i kam long Sisa Ogastas, long olgeta dispela graun i mas baim takis.',
        2: '(Na dispela pasin bilong baim takis ol i wokim pastaim taim Sairenias em i nambawan gavman bilong Siria.)',
        3: 'Na olgeta i go long baim takis, olgeta wan wan man i go long biktaun bilong em yet.',
        4: 'Na Josep tu i go antap i lusim Galili, ausait long biktaun bilong Nasaret, i go long Judia, i go long biktaun bilong Devit, dispela ol i kolim Betlehem, (bilong wanem, em i bilong hauslain na lain tumbuna bilong Devit.)',
        5: 'Em i go long baim takis wantaim Maria, meri bilong em long kontrak, taim bel bilong meri i bikpela wantaim pikinini.',
        6: 'Na em i olsem, long, taim ol i stap long dispela hap, ol de bilong em i kamap pinis long em i mas karim pikinini.',
        7: 'Na em i karim namba wan pikinini man bilong em, na raunim em insait long ol klos bilong raunim bebi, na slipim em long bokis kaikai bilong ol bulmakau samting. Bilong wanem, i no gat spes long ol long haus pasindia.',
        8: '¶ Na i gat i stap long dispela hap graun stret ol wasman bilong sipsip i stap long ples kunai, taim ol i was long ol lain sipsip bilong ol long nait.',
        9: 'Na, harim, ensel bilong Bikpela i kam long ol, na glori bilong Bikpela i lait raun nabaut long ol. Na ol i pret tru.',
        10: 'Na ensel i tokim ol, No ken pret. Long wanem, lukim, mi bringim gutpela nius long yupela bilong bikpela amamas tru, dispela bai i stap bilong olgeta manmeri.',
        11: 'Long wanem, long yupela tude mama i karim long biktaun bilong Devit wanpela Man Bilong Kisim Bek, husat em i Kraist Bikpela.',
        12: 'Na dispela bai stap wanpela mak i go long yupela. Yupela bai lukim dispela bebi i pas raun nabaut long ol klos bilong raunim bebi, taim em i slip long bokis kaikai bilong ol bulmakau samting.',
        13: 'Na wantu i gat i stap wantaim dispela ensel wanpela bikpela lain tru bilong ami bilong heven i litimapim nem bilong God, na spik,',
        14: 'Glori i go long God i antap moa olgeta, na long dispela graun bel isi, gutpela bel i go long ol man.',
        15: 'Na em i kamap olsem, taim ol ensel i lusim ol i go long heven pinis, ol wasman bilong sipsip i tok wanpela i go long narapela, Yumi go nau, yes, long Betlehem, na lukim dispela samting, dispela i kamap olsem, dispela Bikpela i bin mekim yumi long save long en.',
        16: 'Na ol i kam hariap, na lukim Maria, na Josep, na bebi i slip long bokis kaikai bilong ol bulmakau samting.',
        17: 'Na taim ol i bin lukim dispela, ol i mekim ol lain ausait long save dispela toktok ensel i tokim ol long sait bilong dispela Pikinini.',
        18: 'Na ol olgeta husat i harim dispela i tingting planti long ol dispela samting, dispela ol wasman bilong sipsip i tokim ol.',
        19: 'Tasol Maria i holimpas olgeta dispela samting na em i tingim na skelim ol insait long bel bilong em.',
        20: 'Na ol wasman bilong sipsip i go bek, na givim glori na litimapim nem bilong God long olgeta dispela samting ol i bin harim na lukim, olsem ensel i tokim ol.',
        21: '¶ Na taim etpela de i kamap pinis bilong ol i mas katim skin bilong Pikinini, ol i kolim nem bilong em JISAS, dispela em i nem olsem em i kisim long ensel bipo mama i kisim bel na em i kam insait long bel.',
        22: 'Na taim ol de bilong kamap klin bilong meri bilong bihainim lo bilong Moses i kamap pinis, ol i bringim em long Jerusalem, bilong givim em long Bikpela,',
        23: '(Olsem rait i stap pinis long lo bilong Bikpela, Olgeta wan wan man husat i opim bel bilong mama ol bai kolim holi long Bikpela,)',
        24: 'Na long ofaim wanpela sakrifais bilong bihainim dispela samting lo bilong Bikpela i tok long en, Tupela balus turtel, o tupela yangpela balus pidgin.',
        25: '¶ Na, lukim, i gat wanpela man long Jerusalem, husat nem bilong em em Simion. Na dispela man stret em i stretpela na strong long bihainim God, taim em i wetim dispela bel isi bilong Isrel. Na Holi Spirit i stap antap long em.',
        26: 'Na em i kamap ples klia long em long wok bilong Holi Spirit, long em bai i no ken lukim dai, bipo em i bin lukim dispela Kraist bilong Bikpela.',
        27: 'Na em i kam long wok bilong Spirit insait long tempel. Na taim papamama i bringim dispela Pikinini Jisas insait, long mekim long em i bihainim kastam bilong lo,',
        28: 'Nau em i kisim em i go long tupela han bilong em, na blesim God, na tok,',
        29: 'Bikpela, nau yu ken larim wokboi bilong yu go wantaim bel isi, bilong bihainim tok bilong yu.',
        30: 'Long wanem, tupela ai bilong mi i bin lukim kisim bek bilong yu,',
        31: 'Dispela yu bin redim long ai bilong pes bilong olgeta manmeri.',
        32: 'Wanpela lait bilong givim lait long ol man i no Ju, na glori bilong lain manmeri bilong yu Isrel.',
        33: 'Na Josep na mama bilong em i tingting planti long ol dispela samting, ol dispela Simion i toktok long sait bilong em.',
        34: 'Na Simion i blesim ol, na tokim mama bilong em Maria, Lukim, dispela Pikinini i sanap bilong pundaun na kirap gen bilong planti insait long Isrel. Na bilong wanpela mak, dispela ol bai toktok birua long en.',
        35: '(Yes, wanpela bainat bai sutim namel long tewel bilong yu tu,) inap long ol tingting bilong planti bel i ken kamap ples klia.',
        36: 'Na i gat wanpela Ana, wanpela profet meri, pikinini meri bilong Fanyuel, bilong lain Aser. Em i gat planti krismas tru, na em i bin stap wantaim man bilong em sevenpela yia bihain long taim em i stap meri i no bin slip wantaim man.',
        37: 'Na em i stap meri man bilong em i dai pinis klostu olsem 84 yia, husat i no lusim tempel, tasol em i wokim wok long God wantaim ol pasin bilong tambuim kaikai na ol prea nait na san.',
        38: 'Na meri i kam long dispela taim stret na givim tok tenkyu wankain olsem i go long Bikpela, na toktok long sait bilong em long olgeta husat i lukluk long dispela baim bek insait long Jerusalem.',
        39: 'Na taim ol i bin wokim olgeta samting bilong bihainim lo bilong Bikpela, ol i go bek long Galili, long biktaun bilong ol yet Nasaret.',
        40: 'Na dispela Pikinini i go bikpela, na wok long kamap strong insait long spirit, pulap wantaim save tru. Na marimari bilong God i stap antap long em.',
        41: '¶ Nau papamama bilong em i go long Jerusalem olgeta wan wan yia long bikpela kaikai bilong pasova.',
        42: 'Na taim em i gat twelpela krismas, ol i go antap long Jerusalem i bihainim kastam bilong dispela bikpela kaikai.',
        43: 'Na taim ol i bin inapim ol de pinis, taim ol i go bek, dispela pikinini Jisas i stap bek yet long Jerusalem. Na Josep na mama bilong em i no save long dispela.',
        44: 'Tasol tupela, taim ol i ting olsem em i bin stap wantaim lain bilong ol, i go wanpela de wokabaut. Na ol i painim em namel long ol kandere bilong ol na ol man ol i save long ol.',
        45: 'Na taim tupela i no lukim em, ol i tanim i go bek gen long Jerusalem, na painim em.',
        46: 'Na em i kamap olsem, long bihain long tripela de ol i painim em pinis insait long tempel, taim em i sindaun namel long ol dokta, taim em i harim ol, na askim ol ol askim wantaim.',
        47: 'Na olgeta husat i harim em i kirap nogut long save na ol bekim bilong em.',
        48: 'Na taim ol i lukim em, ol i kirap nogut tru. Na mama bilong em i tokim em, Pikinini Man, bilong wanem yu bin mekim olsem long mipela? Lukim, papa bilong yu na mi i bin painim yu wantaim bel i pilim hevi.',
        49: 'Na em i tokim tupela, Em i olsem wanem long yutupela i bin painim mi? Ating i yes long yupela i save long mi mas stap nabaut long wok bilong Papa bilong mi?',
        50: 'Na ol i no save gut long dispela toktok em i tokim ol.',
        51: 'Na em i go daun wantaim ol, na kam long Nasaret, na stap aninit long ol. Tasol mama bilong em i holimpas olgeta dispela toktok insait long bel bilong em.',
        52: 'Na Jisas i kamap bikpela moa long save tru na longpela bilong bodi, na long gutpela amamas wantaim God na man.',
    },
    3: {
        1: '¶ Nau long namba 15 yia bilong Taibirias Sisa i bosim kingdom, taim Pontias Pailat i stap nambawan gavman bilong Judia, na taim Herot i stap namba foa hap king bilong Galili, na brata bilong em Filip i stap namba foa hap king bilong Ituria na bilong hap graun bilong Trakonaitis, na Laisenias i stap namba foa hap king bilong Abilini,',
        2: 'Taim Anas na Kaiafas i stap ol hetpris, tok bilong God i kam long Jon, pikinini man bilong Sakaraias, long ples i no gat man.',
        3: 'Na em i kam insait long olgeta hap graun nabaut long Jordan, na autim tok long baptais bilong tanim bel bilong lusim ol sin,',
        4: 'Olsem rait i stap pinis long buk bilong ol toktok bilong profet Aisea, i spik, Nek bilong wanpela i singaut long ples i no gat man, Yupela redim rot bilong Bikpela, mekim ol liklik rot bilong em stretpela.',
        5: 'Ol bai pulimapim olgeta wan wan ples daun, na ol bai bringim daunbilo olgeta wan wan maunten na liklik maunten. Na ol bai mekim stretpela ol samting i krungut, na ol bai mekim ol rot i rap i kamap rot i no rap liklik.',
        6: 'Na olgeta manmeri bai lukim kisim bek bilong God.',
        7: 'Nau em i tokim dispela bikpela lain tru husat i kam ausait long kisim baptais long em, O lain tumbuna bilong ol vaipa, husat i bin tok lukaut long yupela long ranawe long dispela belhat tru i laik kamap?',
        8: 'Olsem na karim ol kaikai i gat namba inap long soim tanim bel, na no ken stat long toktok insait long yupela yet, Mipela i gat Ebraham i stap tumbuna papa bilong mipela. Long wanem, mi tokim yupela, Long God em i inap long kirapim ol pikinini i go long Ebraham long ol dispela ston.',
        9: 'Na nau tu ol i putim akis long rop daunbilo bilong ol diwai. Olsem na olgeta wan wan diwai husat i no karim gutpela kaikai ol bai katim i go daun, na tromoi insait long paia.',
        10: 'Na ol manmeri i askim em, i spik, Mipela bai mekim wanem nau?',
        11: 'Na em i bekim na tokim ol, Em husat i gat tupela saket, larim em givim long em husat i no gat wanpela. Na em husat i gat kaikai, larim em mekim wankain olsem.',
        12: 'Nau tu ol man bilong kisim takis i kam long kisim baptais, na tokim em, Tisa, mipela bai mekim wanem?',
        13: 'Na em i tokim ol, No ken strong long kisim moa long dispela samting ol i makim bilong yupela.',
        14: 'Na ol soldia i askim strong long em wankain olsem, i spik, Na mipela bai mekim wanem? Na em i tokim ol, No ken mekim pasin pait long wanpela man, o sutim tok giaman long wanpela man. Na tok em inap long pe bilong yupela.',
        15: '¶ Na taim ol manmeri i gat strongpela hop, na olgeta man i tingting strong insait long ol bel bilong ol long Jon, long em i Kraist, o nogat,',
        16: 'Jon i bekim, i spik long ol olgeta, Em i tru mi givim baptais long yupela wantaim wara. Tasol wanpela i kam i strong moa long mi, husat string bilong ol su bilong em mi no gat namba inap long lusim. Em bai givim baptais long yupela wantaim Holi Spirit na wantaim paia.',
        17: 'Bilong husat samting bilong wokim win i stap long han bilong em, na em bai klinim olgeta hap bilong plua bilong em, na em bai bungim ol wit i go insait long bakstua bilong wit bilong em. Tasol skin bilong wit em bai kukim wantaim paia i no inap long dai.',
        18: 'Na planti arapela samting em i autim bilong strongim bel bilong ol manmeri wantaim tok bilong em.',
        19: 'Tasol namba foa hap king Herot, taim Jon i stretim em bilong tingim Herotias, meri bilong brata bilong em Filip, na long olgeta dispela pasin nogut Herot i bin mekim,',
        20: 'I skruim dispela yet antap long olgeta, long em i pasim Jon insait long kalabus.',
        21: '¶ Nau taim olgeta manmeri i kisim baptais, em i kamap olsem, long taim Jisas tu i kisim baptais, na taim em i beten, heven i op,',
        22: 'Na Holi Spirit i kam daun long wanpela lukluk bilong bodi i olsem balus antap long em, na wanpela nek i kam long heven, husat i tok, Yu stap Pikinini Man bilong mi i stap klostu tru long bel bilong mi. Long yu mi gat amamas tru.',
        23: 'Na Jisas em yet i stat long stap klostu olsem 30 krismas, taim (olsem ol i ting) em i pikinini man bilong Josep, husat i pikinini man bilong Hilai,',
        24: 'Husat i pikinini man bilong Matat, husat i pikinini man bilong Livai, husat i pikinini man Melkai, husat i pikinini man bilong Jana, husat i pikinini man bilong Josep,',
        25: 'Husat i pikinini man bilong Matataias, husat i pikinini man bilong Emos, husat i pikinini man bilong Neam, husat i pikinini man bilong Esli, husat i pikinini man bilong Nagai,',
        26: 'Husat i pikinini man bilong Meat, husat i pikinini man bilong Matataias, husat i pikinini man bilong Semei, husat i pikinini man bilong Josep, husat i pikinini man bilong Juda,',
        27: 'Husat i pikinini man bilong Joana, husat i pikinini man bilong Resa, husat i pikinini man bilong Serubabel, husat i pikinini man bilong Salatiel, husat i pikinini man bilong Nerai,',
        28: 'Husat i pikinini man bilong Melkai, husat i pikinini man bilong Edai, husat i pikinini man bilong Kosam, husat i pikinini man bilong Elmodam, husat i pikinini man bilong Er,',
        29: 'Husat i pikinini man bilong Jose, husat i pikinini man bilong Eliesar, husat i pikinini man bilong Jorim, husat i pikinini man bilong Matat, husat i pikinini man bilong Livai,',
        30: 'Husat i pikinini man bilong Simion, husat i pikinini man bilong Juda, husat i pikinini man bilong Josep, husat i pikinini man bilong Jonan, husat i pikinini man bilong Elaiakim,',
        31: 'Husat i pikinini man bilong Melia, husat i pikinini man bilong Menan, husat i pikinini man bilong Matata, husat i pikinini man bilong Netan, husat i pikinini man bilong Devit,',
        32: 'Husat i pikinini man bilong Jesi, husat i pikinini man bilong Obet, husat i pikinini man bilong Bos, husat i pikinini man bilong Salmon, husat i pikinini man bilong Neason,',
        33: 'Husat i pikinini man bilong Aminadap, husat i pikinini man bilong Aram, husat i pikinini man bilong Esrom, husat i pikinini man bilong Fares, husat i pikinini man bilong Juda,',
        34: 'Husat i pikinini man bilong Jekop, husat i pikinini man bilong Aisak, husat i pikinini man bilong Ebraham, husat i pikinini man bilong Tera, husat i pikinini man bilong Nakor,',
        35: 'Husat i pikinini man bilong Serak, husat i pikinini man bilong Regau, husat i pikinini man bilong Felek, husat i pikinini man bilong Heber, husat i pikinini man bilong Sala,',
        36: 'Husat i pikinini man bilong Kenan, husat i pikinini man bilong Arfaksat, husat i pikinini man bilong Siem, husat i pikinini man bilong Noe, husat i pikinini man bilong Lamek,',
        37: 'Husat i pikinini man bilong Metusela, husat i pikinini man bilong Inok, husat i pikinini man bilong Jeret, husat i pikinini man bilong Malalel, husat i pikinini man bilong Kenan,',
        38: 'Husat i pikinini man bilong Inos, husat i pikinini man bilong Set, husat i pikinini man bilong Adam, husat i pikinini man bilong God.',
    },
    4: {
        1: '¶ Na taim Jisas i pulap long Holi Spirit em i lusim Jordan i kam bek, na Spirit i stiaim em i go long ples i no gat man,',
        2: 'Taim Seten i traim em 40 de. Na long ol dispela de em i no bin kaikai wanpela samting. Na taim ol de i pinis, bihain long em em i hangre.',
        3: 'Na Seten i tokim em, Sapos yu stap Pikinini Man bilong God, tok strong long dispela ston long mekim em i kamap bret.',
        4: 'Na Jisas i bekim em, i spik, Rait i stap pinis, Long man bai i no inap stap laip long bret tasol, tasol long olgeta wan wan tok bilong God.',
        5: 'Na Seten, taim em i kisim em i go antap long wanpela maunten antap, i soim em olgeta kingdom bilong dispela graun long wanpela liklik hap bilong taim.',
        6: 'Na Seten i tokim em, Olgeta dispela pawa bai mi givim yu, na glori bilong ol. Long wanem, God i givim dispela long han bilong mi. Na long husat man mi gat laik mi ken givim dispela.',
        7: 'Olsem na sapos yu bai lotuim mi, olgeta bai bilong yu.',
        8: 'Na Jisas i bekim na tokim em, Yu go baksait long mi, Seten. Long wanem, rait i stap pinis, Yu bai lotuim Bikpela, God bilong yu, na em wanpela bai yu bihainim.',
        9: 'Na em i bringim em long Jerusalem, na putim em antap long wanpela ples antap tru bilong tempel, na tokim em, Sapos yu stap Pikinini Man bilong God, tromoi yu yet i go daun i lusim hia.',
        10: 'Long wanem, rait i stap pinis, Em bai givim ol ensel bilong em wok long lukautim yu, long holimpas yu.',
        11: 'Na long ol han bilong ol ol bai holim yu antap, nogut i gat wanpela taim yu bai sutim lek bilong yu long wanpela ston.',
        12: 'Na Jisas i bekim tok long em, Tok i stap pinis, Yu no ken traim Bikpela, God bilong yu.',
        13: 'Na taim Seten i bin pinisim olgeta traim, em i lusim em long wanpela liklik taim.',
        14: '¶ Na insait long pawa bilong Spirit Jisas i go bek insait long Galili. Na wanpela biknem tru bilong em i go long olgeta dispela hap graun raun nabaut.',
        15: 'Na em i skulim ol manmeri insait long ol sinagog bilong ol, taim em i kisim glori long olgeta.',
        16: 'Na em i kam long Nasaret, we ol i bin lukautim em inap long em i bikpela. Na, olsem em i kastam bilong em, em i go insait long sinagog long de sabat, na sanap bilong rit.',
        17: 'Na ol i givim em buk bilong profet Eseas. Na taim em i bin opim dispela buk, em i painim pinis dispela ples we rait i stap pinis,',
        18: 'Spirit bilong Bikpela i stap antap long mi, bilong wanem, em i bin makim mi long autim gutnius long ol rabisman. Em i bin salim mi long oraitim ol man bel bilong ol bruk, long autim pasin bilong kisim bek long ol kalabusman, na long mekim ol aipas i ken lukluk gen, long mekim i go fri ol husat i gat liklik bagarap,',
        19: 'Long autim dispela yia i orait long ai bilong Bikpela.',
        20: 'Na em i pasim dispela buk, na em i givim dispela gen i go long wokman, na em i sindaun. Na ai bilong ol olgeta husat i stap insait long sinagog i pas strong long em.',
        21: 'Na em i stat long tokim ol, Tude dispela rait bilong God i kamap pinis insait long ol ia bilong yupela.',
        22: 'Na olgeta i stap witnes long em, na tingting planti long ol dispela toktok i soim marimari i kam ausait long maus bilong em. Na ol i tok, Ating i yes long dispela em i pikinini man bilong Josep?',
        23: 'Na em i tokim ol, Tru tumas, yupela bai tokim mi long dispela provep, Dokta, oraitim sik bilong yu yet. Wanem samting mipela i bin harim yu mekim long Kaperneam, mekim hia tu long hap graun bilong yu.',
        24: 'Na em i tok, Tru tumas, Mi tokim yupela, I no gat wanpela profet i kisim orait long ol man long hap graun bilong em yet.',
        25: 'Tasol mi tokim yupela long em i tru, planti meri man bilong ol i dai pinis i stap long Isrel long ol de bilong Ilaias, taim heven i pas tripela yia na sikispela mun, taim bikpela taim hangre i stap long olgeta hap bilong dispela hap.',
        26: 'Tasol God i no salim Ilaias long wanpela arapela bilong ol, em i go Sarefta tasol, wanpela biktaun bilong Saidon, i go long wanpela meri husat man bilong em i dai pinis.',
        27: 'Na planti man i gat sik lepra i stap long Isrel long taim bilong profet Ilisias. Na i no gat wanpela arapela bilong ol i kamap klin, Neman bilong Siria tasol.',
        28: 'Na ol olgeta insait long sinagog, taim ol i harim ol dispela samting, i pulap wantaim belhat tru,',
        29: 'Na ol i kirap, na subim em i go ausait long biktaun, na stiaim em i go long arere stret bilong liklik maunten we ol i wokim biktaun bilong ol antap long en, inap long ol i ken tromoi em i go daun het i go pas.',
        30: 'Tasol em i wokabaut namel long ol na go long rot bilong em,',
        31: '¶ Na em i kam daun long Kaperneam, wanpela biktaun bilong Galili, na skulim ol long ol de sabat.',
        32: 'Na ol i kirap nogut long skul bilong em. Long wanem, tok bilong em i gat pawa.',
        33: 'Na insait long sinagog i gat wanpela man, husat i gat wanpela spirit i kam long wanpela spirit nogut i no klin, na em i singaut wantaim bikpela nek,',
        34: 'I spik, Larim mipela i stap. Mipela i gat wanem wok wantaim yu, yu Jisas bilong Nasaret? Ating yu kam bilong bagarapim mipela olgeta? Mi save long yu long yu stap husat, dispela Man Holi bilong God.',
        35: 'Na Jisas i hatim em, i spik, Pasim maus bilong yu, na kam ausait long em. Na taim dispela spirit nogut i bin tromoi em i go namel long ol, em i kam ausait long em, na em i no bagarapim em.',
        36: 'Nau ol olgeta i kirap nogut tru, na toktok namel long ol yet, i spik, Dispela em i wanem kain tok! Long wanem, wantaim namba na pawa em i tok strong long ol spirit i no klin, na ol i kam ausait.',
        37: 'Na biknem tru bilong em i go ausait long olgeta wan wan ples bilong dispela hap graun raun nabaut.',
        38: 'Na em i kirap na go ausait long sinagog, na go insait long haus bilong Saimon. Na bikpela skinhat i kisim mama bilong meri bilong Saimon. Na ol i askim em strong plis long helpim meri.',
        39: 'Na em i sanap na lindaun antap long em, na hatim dispela skinhat. Na dispela i lusim em. Na wantu meri i kirap na wokim wok long ol.',
        40: 'Nau taim san i laik go daun, ol olgeta husat i gat wanpela i sik wantaim kain kain sik nogut i bringim ol i kam long em. Na em i slipim tupela han bilong em antap long olgeta wan wan bilong ol, na oraitim ol.',
        41: 'Na ol spirit nogut tu i kam ausait long planti, taim ol i singaut, na spik, Yu stap Kraist, Pikinini Man bilong God. Na taim em i hatim ol em i no larim ol i toktok. Long wanem, ol i save long em i Kraist.',
        42: 'Na taim em i san pinis, em i lusim hap na go long wanpela ples i no gat man. Na ol manmeri i painim em, na kam long em, na pasim em, inap long em i no ken lusim ol.',
        43: 'Na em i tokim ol, Mi mas autim tok bilong kingdom bilong God long ol arapela biktaun tu. Long wanem, olsem na God i salim mi.',
        44: 'Na em i autim tok long ol sinagog bilong Galili.',
    },
    5: {
        1: '¶ Na em i kamap olsem, long, taim ol manmeri i kam pas pas tumas long em long harim tok bilong God, em i sanap klostu long raunwara bilong Genesaret,',
        2: 'Na em i lukim tupela sip i sanap klostu long raunwara. Tasol ol man bilong painim pis i bin go ausait long ol pinis, na ol i wok long wasim ol umben bilong ol.',
        3: 'Na em i go insait long wanpela bilong ol sip, dispela i bilong Saimon, na askim em plis long em i ken subim sip i go ausait liklik long nambis. Na em i sindaun, na skulim ol manmeri ausait long sip.',
        4: 'Nau taim em i bin lusim wok bilong toktok, em i tokim Saimon, Putim sip i go ausait long ples dip, na lusim ol umben bilong yupela i go daun bilong pulim wanpela lain pis.',
        5: 'Na Saimon i bekim na tokim em, Tisa, mipela i bin hatwok olgeta hap bilong nait, na mipela i no bin kisim wanpela samting. Tasol long tok bilong yu mi bai lusim umben i go daun.',
        6: 'Na taim ol i bin mekim dispela, ol i raunim wanpela traipela lain tru bilong ol pis. Na umben bilong ol i bruk.',
        7: 'Na ol i wokim mak wantaim han long ol wanwok bilong ol, husat i stap long arapela sip, long ol i ken kam na helpim ol. Na ol kam, na pulimapim tupela sip wantaim, inap long ol i stat long go daun isi isi.',
        8: 'Taim Saimon Pita i lukim dispela, em i pundaun long tupela skru bilong Jisas, i spik, Lusim mi. Long wanem, mi wanpela man i pulap long sin, O Bikpela.',
        9: 'Long wanem, em i kirap nogut, na olgeta husat i stap wantaim em, long dispela lain pis ol i bin kisim.',
        10: 'Na Jems tu i wankain olsem, na Jon, ol pikinini man bilong Sebedi, husat i ol wanwok wantaim Saimon. Na Jisas i tokim Saimon, No ken pret. I stat long nau i go yu bai kisim ol man.',
        11: 'Na taim ol i bin bringim ol sip bilong ol i go long nambis, ol i givim baksait long olgeta, na bihainim em.',
        12: '¶ Na em i kamap olsem, taim em i stap long wanpela biktaun, lukim wanpela man i pulap long sik lepra, husat taim em i lukim Jisas, em i pundaun long pes bilong em, na askim em strong plis, i spik, Bikpela, sapos yu gat laik, yu ken mekim mi klin.',
        13: 'Na em i putim han bilong em i go ausait, na tasim em, i spik, Mi gat laik. Yu stap klin. Na wantu sik lepra i lusim em.',
        14: 'Na em i givim tok long em long em i no ken tokim wanpela man. Tasol go, na soim yu yet long pris, na wokim ofa bilong klinim bilong yu, bilong bihainim olsem Moses i tok strong, bilong wanpela testimoni i go long ol.',
        15: 'Tasol hamas moa olsem wanpela biknem tru bilong em i go ausait. Na ol traipela lain tru i kam bung wantaim long harim, na long kamap orait long em long ol sik bilong ol.',
        16: 'Na em i surikim em yet i go long ples i no gat man, na beten.',
        17: '¶ Na em i kamap olsem long wanpela de, taim em i skulim ol manmeri, long i gat ol Farisi na ol dokta bilong lo i sindaun klostu, husat i kam ausait long olgeta wan wan taun bilong Galili, na Judia, na Jerusalem. Na pawa bilong Bikpela i stap long oraitim ol.',
        18: 'Na, lukim, ol man i bringim long bet wanpela man husat sik palsi i kisim em. Na ol i painim rot long bringim em insait, na long slipim em long ai bilong em.',
        19: 'Na taim ol i no inap long painim wanem rot long ol i ken bringim em insait, bilong wanem, dispela bikpela lain tru i stap, ol i go antap long antap bilong haus, na lusim em i go daun namel long ol tail bilong rup wantaim liklik bet bilong em i go namel long ol manmeri long ai bilong Jisas.',
        20: 'Na taim em i lukim bilip tru bilong ol, em i tokim em, Man, mi lusim ol sin bilong yu.',
        21: 'Na ol man bilong rait na ol Farisi i stat long stretim tok, i spik, Dispela em i husat husat i toktok long ol tok bilas? Husat i ken lusim ol sin, na i no God wanpela tasol?',
        22: 'Tasol taim Jisas i kisim save long ol tingting bilong ol, em i bekim tok long ol, Yupela i stretim tok long wanem samting insait long ol bel bilong yupela?',
        23: 'Wanem em i isi moa, long tok, Mi lusim ol sin bilong yu, o long tok, Kirap na wokabaut?',
        24: 'Tasol inap long yupela i ken save long Pikinini Man bilong man i gat pawa long dispela graun long lusim ol sin, (em i tokim man i sik long sik palsi,) Mi tokim yu, Kirap, na kisim liklik bet bilong yu i go antap, na go insait long haus bilong yu.',
        25: 'Na wantu em i kirap long ai bilong ol, na kisim i go antap dispela samting we em i slip antap long en, na lusim hap i go long haus bilong em yet, taim em i givim glori long God.',
        26: 'Na ol olgeta i kirap nogut tru, na ol i givim glori long God, na ol i pulap wantaim pret, i spik, Mipela i bin lukim ol narakain samting tude.',
        27: '¶ Na bihain long ol dispela samting em i go ausait, na lukim wanpela man bilong kisim takis, husat nem bilong em em Livai, taim em i sindaun long kisim kastam mani. Na em i tokim em, Bihainim mi.',
        28: 'Na em i lusim olgeta samting, kirap, na bihainim em.',
        29: 'Na Livai i wokim wanpela bikpela kaikai tru insait long haus bilong em yet. Na i gat wanpela bikpela lain bilong ol man bilong kisim takis na ol arapela husat i sindaun wantaim ol.',
        30: 'Tasol ol man bilong rait bilong ol na ol Farisi i tok baksait i birua long ol disaipel bilong em, i spik, Bilong wanem yupela i kaikai na dring wantaim ol man bilong kisim takis na ol sinman?',
        31: 'Na Jisas i bekim tok long ol, Ol husat i orait olgeta i no gat nid long dokta. Tasol ol husat i sik i gat nid long dokta.',
        32: 'Mi no kam long singautim ol stretpela man, tasol long singautim ol sinman long tanim bel.',
        33: 'Na ol i tokim em, Bilong wanem ol disaipel bilong Jon i tambuim kaikai planti taim, na mekim ol prea, na wankain olsem ol disaipel bilong ol Farisi, tasol ol disaipel bilong yu i kaikai na dring?',
        34: 'Na em i tokim ol, Yupela i ken mekim ol pikinini bilong rum bilong meri i laik marit long tambuim kaikai, taim man i laik marit i stap wantaim ol?',
        35: 'Tasol ol de bai kam, taim ol bai tekewe man i laik marit long ol, na nau ol bai tambuim kaikai long ol dispela de.',
        36: 'Na em i tok tu long ol long wanpela tok piksa. I no gat man i putim wanpela hap bilong nupela klos antap long olpela. Sapos i no olsem, orait nupela bai wokim wanpela bruk, na dispela hap ol i kisim ausait long nupela i no wanbel wantaim olpela wantaim.',
        37: 'Na i no gat man i putim nupela wain i go insait long ol olpela skin meme. Nogut nupela wain bai brukim ol skin meme, na kapsait, na ol skin meme bai pinis olgeta.',
        38: 'Tasol ol i mas putim nupela wain insait long ol nupela skin meme. Na tupela wantaim i ken stap gut yet.',
        39: 'I no gat man tu taim em i bin dringim olpela wain kwiktaim i gat laik long nupela. Long wanem, em i tok, Olpela i gutpela moa.',
    },
    6: {
        1: '¶ Na em i kamap olsem long namba tu sabat bihain long dispela namba wan, long em i go namel long ol bikpela gaden wit samting. Na ol disaipel bilong em i kamautim ol ia bilong wit samting, na ol i bin kaikai, taim ol i rabim ol insait long ol han bilong ol.',
        2: 'Na sampela bilong ol Farisi i tokim ol, Bilong wanem yupela i mekim dispela samting i tambu long lo long mekim long ol de sabat?',
        3: 'Na Jisas i bekim ol na tok, Ating i yes long yupela i ritim liklik olsem dispela, long Devit i bin mekim wanem, taim em yet em i hangre, na ol husat i stap wantaim em,',
        4: 'Long em i bin go insait long haus bilong God olsem wanem, na em i bin kisim na kaikai bret bilong soim, na givim tu long ol husat i stap wantaim em, dispela em i tambu long lo long man i ken kaikai, tasol em i bilong ol pris tasol?',
        5: 'Na em i tokim ol, Long Pikinini Man bilong man em i Bikpela tu bilong sabat.',
        6: 'Na em i kamap olsem tu long narapela sabat, long em i go insait long sinagog na skulim ol manmeri. Na i gat wanpela man i stap husat han sut bilong em i drai.',
        7: 'Na ol man bilong rait na ol Farisi i was long em, long em bai oraitim man long de sabat o nogat, inap long ol i ken painim rot long sutim tok i birua long em.',
        8: 'Tasol em i save long ol tingting bilong ol, na em i tokim dispela man husat i gat han i drai, Kirap, na sanap ausait long namel. Na em i kirap na sanap ausait.',
        9: 'Nau Jisas i tokim ol, Mi bai askim yupela wanpela samting. Em i orait long lo long ol de sabat long mekim gutpela, ol long mekim nogut? Long kisim bek laip, o long bagarap dispela olgeta?',
        10: 'Na taim em i lukluk raun nabaut long ol olgeta, em i tokim dispela man, Stretim han bilong yu i go ausait. Na em i mekim olsem. Na han bilong em i kamap orait gen olgeta olsem arapela.',
        11: 'Na ol i pulap wantaim longlong tingting. Na ol i stori wanpela wantaim narapela long ol i ken mekim wanem long Jisas.',
        12: '¶ Na em i kamap olsem long ol dispela de, long em i go ausait na go insait long wanpela maunten bilong beten, na em i stap yet olgeta hap long nait long prea long God.',
        13: 'Na taim em i san pinis, em i singautim ol disaipel bilong em long kam long em. Na long ol em i makim twelpela, husat tu em i givim nem aposel,',
        14: 'Saimon, (husat tu em i givim nem Pita,) na brata bilong em Andru, Jems na Jon, Filip na Bartolomyu,',
        15: 'Matyu na Tomas, Jems, pikinini man bilong Alifias, na Saimon husat ol i kolim Selotes,',
        16: 'Na Judas, brata bilong Jems, na Judas Iskariot, husat tu i man i putim Jisas long han bilong birua.',
        17: 'Na em i kam daun wantaim ol, na sanap long ples stret, na lain bilong ol disaipel bilong em, na wanpela traipela lain tru bilong ol manmeri ausait long olgeta Judia na Jerusalem, na long nambis bilong biksi bilong Tair na Saidon, husat i kam long harim em, na long kamap orait long ol sik nogut bilong ol,',
        18: 'Na ol husat i kisim hevi long ol spirit i no klin. Na ol i kamap orait.',
        19: 'Na dispela bikpela lain tru olgeta i painim rot long tasim em. Long wanem, gutpela strong i go ausait long em, na oraitim ol olgeta.',
        20: '¶ Na em i litimapim tupela ai bilong em long ol disaipel bilong em, na tok, Blesing i stap long yupela rabisman. Long wanem, Kingdom bilong God em i bilong yupela.',
        21: 'Blesing i stap long yupela husat i hangre nau. Long wanem, yupela bai stap pulap. Blesing i stap long yupela husat i krai tru nau. Long wanem, yupela bai lap.',
        22: 'Blesing i stap long yupela, taim ol man bai hetim yupela, na taim ol bai brukim yupela long ol lain bilong ol, na ol bai givim sem long yupela, na tromoi nem bilong yupela i go ausait olsem samting nogut, bilong tingim Pikinini Man bilong man.',
        23: 'Yupela i mas wokim amamas tru long dispela de, na kalap wantaim amamas tru. Long wanem, lukim, pe bilong yupela long heven em i bikpela. Long wanem, long wankain pasin ol tumbuna papa bilong ol i mekim long ol profet.',
        24: 'Tasol tok lukaut i go long yupela husat i stap maniman! Long wanem, yupela i bin kisim bel isi bilong yupela pinis.',
        25: 'Tok lukaut i go long yupela husat i pulap! Long wanem, yupela bai hangre. Tok lukaut i go long yupela husat i lap nau! Long wanem, yupela bai soim sori na krai tru.',
        26: 'Tok lukaut i go long yupela, taim olgeta man bai toktok gutpela long sait bilong yupela! Long wanem, olsem tasol ol tumbuna papa bilong ol i bin mekim long ol giaman profet.',
        27: '¶ Tasol mi tokim yupela husat i harim, Laikim tru ol birua bilong yupela, mekim gutpela long ol husat i hetim yupela,',
        28: 'Blesim ol husat i toknogutim yupela, na beten long ol husat i yusim yupela nogut tru.',
        29: 'Na long em husat i paitim yu long wanpela wasket, soim tu arapela. Na em husat i tekewe ausait saket bilong yu, yu no ken tambuim em long tekewe insait saket bilong yu tu.',
        30: 'Givim long olgeta wan wan man husat i askim long yu. Na long em husat i tekewe ol kago bilong yu i go, no ken askim long ol gen.',
        31: 'Na olsem yupela i gat laik long ol man i mas mekim long yupela, yupela i mas mekim tu long ol wankain olsem.',
        32: 'Long wanem, sapos yupela i laikim tru ol husat i laikim tru yupela, yupela i gat wanem tok tenkyu? Long wanem, ol sinman tu i laikim tru ol dispela husat i laikim tru ol.',
        33: 'Na sapos yupela i mekim gut long ol husat i mekim gut long yupela, yupela i gat wanem tok tenkyu? Long wanem, ol sinman tu, yes, i mekim wankain.',
        34: 'Na sapos yupela i givim dinau long ol bilong husat yupela i gat hop long kisim samting, yupela i gat wanem tok tenkyu? Long wanem, ol sinman tu i givim dinau long ol sinman, long kisim wankain olsem gen.',
        35: 'Tasol yupela i mas laikim tru ol birua bilong yupela, na mekim gutpela pasin, na givim dinau, taim yupela i no gat hop long kisim wanpela samting gen. Na pe bilong yupela bai stap bikpela, na yupela bai stap ol pikinini bilong Man i Antap Moa Olgeta. Long wanem, em i mekim gutpela long ol man i no tok tenkyu na long ol man nogut.',
        36: 'Olsem na yupela i mas stap pulap long sori, olsem Papa bilong yupela tu i pulap long sori.',
        37: '¶ No ken jasim, na God bai i no inap jasim yupela. No ken sutim tok, na God bai i no sutim tok long yupela. Lusim rong bilong arapela, na God bai lusim rong bilong yupela.',
        38: 'Givim, na God bai givim dispela long yupela, long gutpela skel, pas pas daun gutpela, na i seksek wantaim, na i kapsait, bai ol man i givim i go long bros bilong yupela. Long wanem, wantaim wankain skel stret long yupela i givim, wankain olsem dispela bai ol i skelim long yupela gen.',
        39: 'Na em i tokim ol long wanpela tok piksa, Aipas i ken stiaim aipas? Ating i yes long tupela wantaim bai pundaun insait long baret?',
        40: 'Disaipel i no antap moa long tisa bilong em. Tasol olgeta wan wan husat i inap tru bai stap olsem tisa bilong em.',
        41: 'Na bilong wanem yu lukim dispela liklik hap pipia i stap long ai bilong brata bilong yu, tasol yu no kisim save long dispela rigel i stap long ai bilong yu yet?',
        42: 'Na tu olsem wanem yu ken tokim brata bilong yu, Brata, larim mi pulim i kam ausait dispela liklik hap pipia i stap long ai bilong yu, taim yu yu yet i no lukim dispela rigel i stap long ai bilong yu yet? Yu man bilong tupela maus, rausim i go ausait pastaim dispela rigel i stap long ai bilong yu yet, na nau yu bai lukluk klia long pulim i kam ausait dispela liklik hap pipia i stap long ai bilong brata bilong yu.',
        43: 'Long wanem, gutpela diwai i no karim kaikai nogut. Na tu diwai nogut i no karim gutpela kaikai.',
        44: 'Long wanem, ol man bai save long olgeta wan wan diwai long kaikai bilong em yet. Long wanem, ol man i no bungim ol nil long ol fik, o ol pikinini wain long liklik bus brambel.',
        45: 'Gutpela man, ausait long gutpela samting i dia tru bilong bel bilong em, i bringim i kam ausait dispela samting i gutpela. Na man nogut, ausait long samting i dia tru nogut bilong bel bilong em, i bringim i kam ausait dispela samting i nogut. Long wanem, long samting bel i gat planti moa yet long en, maus bilong em i toktok.',
        46: 'Na bilong wanem yupela i kolim mi, Bikpela, Bikpela, na yupela i no mekim ol dispela samting mi tok?',
        47: 'Husat man i kam long mi, na harim ol toktok bilong mi, na mekim ol, mi bai soim yupela long em i olsem husat.',
        48: 'Em i olsem wanpela man husat i wokim haus, na digim i go dip, na slipim ol as ston antap long wanpela ston. Na taim tait i kam antap, dispela wara i paitim paitim strong nogut tru long dispela haus, na em i no inap long seksekim dispela. Long wanem, ol i wokim ol as ston antap long wanpela ston.',
        49: 'Tasol em husat i harim, na i no mekim, i olsem wanpela man husat i no gat ol as ston na em i wokim haus antap long graun. Dispela wara i bin paitim paitim strong nogut tru i birua long en, na wantu em i pundaun. Na bagarap bilong dispela haus i bikpela.',
    },
    7: {
        1: '¶ Nau taim em i bin pinisim olgeta toktok bilong em long ia bilong ol manmeri, em i go insait long Kaperneam.',
        2: 'Na wokboi bilong wanpela kepten bilong 100 soldia, husat i dia long em, i sik, na em i redi long dai.',
        3: 'Na taim em i harim stori long Jisas, em i salim long em ol lapun hetman bilong ol Ju, bilong askim em strong plis long em i ken kam na oraitim wokboi bilong em.',
        4: 'Na taim ol i kam long Jisas, ol i askim em strongpela strong plis, i spik, Long em i gat namba inap long husat em i ken mekim dispela samting.',
        5: 'Long wanem, em i laikim tru kantri bilong yumi, na em i bin wokim wanpela sinagog bilong yumi.',
        6: 'Nau Jisas i go wantaim ol. Na taim em i no longwe nau long haus, kepten bilong 100 soldia i salim ol pren long em, i spik long em, Bikpela, no ken givim wari long yu yet. Long wanem, mi no gat namba inap long yu ken kam aninit long rup bilong mi.',
        7: 'Olsem na tu mi no tingim mi yet i gat namba inap long kam long yu. Tasol tok long wanpela tok, na wokboi bilong mi bai orait.',
        8: 'Long wanem, mi tu mi man ol i putim aninit long man i gat namba, taim mi gat ol soldia i stap aninit long mi, na mi tokim wanpela, Go, na em i go. Na long narapela, Kam, na em i kam. Na long wokboi bilong mi, Mekim dispela, na em i mekim.',
        9: 'Taim Jisas i harim ol dispela samting, em i tingting planti long em, na tanim em yet nabaut, na tokim ol manmeri husat i bihainim em, Mi tokim yupela, mi no bin lukim bilip tru i bikpela olsem, nogat, i no olsem insait long Isrel.',
        10: 'Na ol husat em i salim, taim ol i go bek long haus, i lukim wokboi i orait olgeta husat i bin sik.',
        11: '¶ Na em i kamap olsem long de bihain, long em i go insait long wanpela biktaun ol i kolim Nain. Na planti bilong ol disaipel bilong em i go wantaim em, na planti manmeri.',
        12: 'Nau taim em i kam klostu long dua bilong banis bilong biktaun, lukim, ol i karim wanpela daiman ausait, wanpela pikinini man tasol bilong mama bilong em, na em i meri man bilong em i dai pinis. Na planti manmeri bilong dispela biktaun i stap wantaim meri.',
        13: 'Na taim Bikpela i lukim meri, em i gat pasin sori long em, na tokim em, No ken krai tru.',
        14: 'Na em i kam na tasim bet bilong karim daiman. Na ol husat i karim em i sanap i stap. Na em i tok, Yangpela man, mi tokim yu, Kirap.',
        15: 'Na em husat i dai pinis i kirap i sindaun, na stat long toktok. Na em i givim em long mama bilong em.',
        16: 'Na i gat wanpela pret i kam antap long olgeta. Na ol i givim glori long God, i spik, Long wanpela bikpela profet i kirap namel long yumi, na, Long God i bin kam lukim ol manmeri bilong em.',
        17: 'Na dispela tok win bilong em i go ausait namel long olgeta hap bilong Judia, na namel long olgeta hap bilong olgeta hap graun raun nabaut.',
        18: 'Na ol disaipel bilong Jon i soim em bilong olgeta dispela samting.',
        19: '¶ Na taim Jon i singautim i kam long em tupela bilong ol disaipel bilong em, em i salim ol i go long Jisas, i spik, Yu stap em husat bai kam? O mipela i mas painim narapela?',
        20: 'Na taim ol man i kam long em, ol i tok, Jon Baptist i bin salim mipela i kam long yu, i spik, Yu stap em husat bai kam? O mipela i mas painim narapela?',
        21: 'Na long dispela aua stret em i oraitim planti long ol sik bilong ol na ol sik nogut, na long ol spirit nogut. Na long planti husat i aipas em i givim ol strong bilong lukluk.',
        22: 'Nau Jisas i bekim tok long ol, Go long rot bilong yupela, na tokim Jon long wanem ol samting yupela i bin lukim na harim, long ol aipas i lukluk, ol lek nogut i wokabaut, ol man lepra i kamap klin, ol iapas i harim, ol daiman i kirap gen, long mi autim gutnius long ol rabisman olsem wanem.',
        23: 'Na blesing i stap long em, husat man bai i no gat bel i bagarap long mi.',
        24: 'Na taim ol mausman bilong Jon i go, em i stat long toktok long ol manmeri long sait bilong Jon, Yupela i go ausait i go long ples i no gat man bilong lukim wanem samting? Wanpela rit i seksek long win?',
        25: 'Tasol yupela i go ausait bilong lukim wanem samting? Wanpela man i werim ol klos i no rap? Lukim, ol husat i werim ol klos i naispela nogut tru, na i gat sindaun i isi tru, i stap long ol ples op bilong ol king.',
        26: 'Tasol yupela i go ausait bilong lukim wanem samting? Wanpela profet? Yes, mi tokim yupela, na planti moa long wanpela profet.',
        27: 'Dispela em em, long husat rait i stap pinis, Lukim, mi bai salim mausman bilong mi long go paslain long pes bilong yu, husat bai redim rot bilong yu i go paslain long yu.',
        28: 'Long wanem, mi tokim yupela, Namel long ol dispela husat ol mama i karim i no gat wanpela profet i winim Jon dispela Baptist. Tasol em husat i las man long kingdom bilong God i winim em.',
        29: 'Na olgeta manmeri husat i harim em, na ol man bilong kisim takis, i tok yes long God i stretpela, taim ol i kisim baptais wantaim baptais bilong Jon.',
        30: 'Tasol ol Farisi na ol masta kot i tok nogat olgeta long tok helpim bilong God i birua long ol yet, taim ol i no kisim baptais long em.',
        31: 'Na Bikpela i tok, Nau mi bai wokim piksa long ol man bilong dispela lain tumbuna long wanem samting? Na ol i wankain olsem wanem samting?',
        32: 'Ol i olsem ol pikinini i sindaun long ples maket, na singaut wanpela i go long narapela, na spik, Mipela i bin winim paip long yupela, na yupela i no bin danis. Mipela i bin soim sori long yupela, na yupela i no bin krai tru.',
        33: 'Long wanem, Jon dispela Baptist i no kam na kaikai bret o dringim wain, na yupela i tok, Em i gat wanpela spirit nogut.',
        34: 'Pikinini Man bilong man i kam na em i kaikai na dring, na yupela i tok, Lukim, wanpela man bilong kaikai planti tumas, na wanpela man bilong dringim planti wain tumas, wanpela pren bilong ol man bilong kisim takis na ol sinman!',
        35: 'Tasol save tru i kamap stretpela long olgeta pikinini bilong em.',
        36: '¶ Na wanpela bilong ol Farisi i askim long em long em i ken kaikai wantaim em. Na em i go insait long haus bilong dispela Farisi, na sindaun long kaikai.',
        37: 'Na, lukim, wanpela meri insait long biktaun, husat i wanpela sinmeri, taim em i save long Jisas i sindaun long kaikai long haus bilong Farisi, i bringim wanpela bokis alabasta bilong wel i gat marasin,',
        38: 'Na em sanap klostu long tupela fut bilong em baksait long em na krai tru, na em i stat long wasim tupela fut bilong em wantaim aiwara bilong em, na em i bin rausim wara long ol wantaim ol gras bilong het bilong em, na givim kis long tupela fut bilong em, na welim ol wantaim dispela wel i gat marasin.',
        39: 'Nau taim dispela Farisi husat i bin askim em long kaikai i lukim dispela, em i toktok insait long em yet, i spik, Dispela man, sapos em i wanpela profet, i bin save long dispela meri em i husat na em i wanem kain meri husat i tasim em. Long wanem, em i wanpela sinmeri.',
        40: 'Na Jisas i bekim na tokim em, Saimon, mi gat wanpela samting long tokim yu. Na em i tok, Tisa, yu tok.',
        41: 'I gat wanpela man bilong givim dinau husat i gat tupela man i bin kisim dinau. Wanpela i dinau long em long 500 pens, na arapela 50.',
        42: 'Na taim tupela i no gat wanpela samting long pe i go long em, wantaim trupela bel em i lusim dinau bilong tupela wantaim. Olsem na tokim mi, husat bilong tupela bai laikim em tru moa?',
        43: 'Saimon i bekim na tok, Mi ting olsem long em, long em husat em i lusim planti moa. Na em i tokim em, Yu bin jasim stret.',
        44: 'Na em i tanim long dispela meri, na tokim Saimon, Yu lukim dispela meri? Mi kam insait long haus bilong yu, na yu no givim mi wara bilong tupela fut bilong mi. Tasol em i bin wasim tupela fut bilong mi wantaim aiwara, na rausim wara long ol wantaim ol gras bilong het bilong em.',
        45: 'Yu no bin givim mi wanpela kis. Tasol dispela meri, i stat long taim mi kam insait inap long nau, i no bin lusim pasin bilong givim kis long tupela fut bilong mi.',
        46: 'Yu no bin welim het bilong mi wantaim wel. Tasol dispela meri i bin welim tupela fut bilong mi wantaim wel i gat marasin.',
        47: 'Olsem na mi tokim yu, Ol sin bilong em, dispela i planti, mi lusim. Long wanem, meri i bin laikim tru planti. Tasol long husat ol i lusim liklik, dispela stret i laikim tru liklik.',
        48: 'Na em i tokim meri, Mi lusim ol sin bilong yu.',
        49: 'Na ol husat i sindaun long kaikai wantaim em i stat long toktok insait long ol yet, Dispela em i husat husat i lusim ol sin tu?',
        50: 'Na em i tokim meri, Bilip tru bilong yu i bin kisim bek yu. Go wantaim bel isi.',
    },
    8: {
        1: '¶ Na em i kamap olsem bihain long en, long em i go namel long olgeta wan wan biktaun na vilis, na autim tok na soim gutpela nius bilong kingdom bilong God. Na dispela twelpela i stap wantaim em,',
        2: 'Na sampela meri, husat Jisas i bin oraitim long ol spirit nogut na ol sik, Maria husat ol i kolim Makdalin, ausait long husat sevenpela spirit nogut i bin go,',
        3: 'Na Joana, meri bilong Kusa, man bilong lukautim ol samting bilong Herot, na Susana, na planti arapela, husat i wokim wok long em long ol samting tru bilong ol.',
        4: '¶ Na taim planti manmeri i bung wantaim, na i kam long em ausait long olgeta wan wan biktaun, em i toktok long wanpela tok piksa.',
        5: 'Wanpela man bilong planim kaikai i go ausait long planim pikinini kaikai bilong em. Na taim em i planim, sampela i pundaun klostu long sait bilong rot. Na ol man i krungutim dispela, na ol pisin bilong skai i kaikai dispela olgeta.',
        6: 'Na sampela i pundaun antap long wanpela ston. Na long taim stret long em i kamap, em i go drai olgeta, bilong wanem, em i sot long wara.',
        7: 'Na sampela i pundaun namel long ol rop i gat nil. Na ol rop i gat nil i kamap wantaim dispela, na pasim nek bilong em.',
        8: 'Na arapela i pundaun long gutpela graun, na kamap, na karim kaikai 100 taims. Na taim em i bin toktok long ol dispela samting, em i singaut, Em husat i gat ol ia long harim, larim em harim.',
        9: 'Na ol disaipel bilong em i askim em, i spik, Dispela tok piksa em i ken stap wanem?',
        10: 'Na em i tok, Long yupela God i bin givim long save long ol samting hait bilong kingdom bilong God. Tasol long ol arapela long ol tok piksa. Inap long taim ol i lukluk ol i no ken luksave, na taim ol i harim ol i no ken kisim save.',
        11: 'Nau dispela tok piksa em i olsem, Pikinini kaikai em i tok bilong God.',
        12: 'Ol dispela klostu long sait bilong rot em ol husat i harim. Nau Seten i kam na tekewe dispela tok ausait long ol bel bilong ol, nogut ol i ken bilip na God i kisim bek ol.',
        13: 'Ol antap long ston em ol, husat, taim ol i harim, ol i kisim tok wantaim amamas tru. Na ol dispela i no gat rop daunbilo, husat long liklik taim ol i bilip, na long taim bilong traim ol i pundaun i go.',
        14: 'Na dispela samting i pundaun namel long ol rop i gat nil em ol, husat, taim ol i bin harim, i go ausait, na ol wari na ol bikpela mani samting na ol amamas bilong dispela laip i pasim nek bilong ol, na ol i no karim kaikai i kamap inap tru.',
        15: 'Tasol dispela long gutpela graun em ol, husat wantaim bel i no gat giaman na i gutpela, taim ol i bin harim tok, ol i bihainim, na karim kaikai wantaim pasin bilong sanap strong long traim.',
        16: 'I no gat man, taim em i bin laitim kandel, i karamapim dispela wantaim wanpela sospen samting, o putim dispela aninit long bet. Tasol em i putim dispela antap long wanpela stik kandel, inap long ol husat i go insait i ken lukim dispela lait.',
        17: 'Long wanem, i no gat wanpela samting i stap hait, long em bai i no inap kamap ples klia, na tu wanpela samting i hait, long ol man bai i no inap save long en na em i kam ausait.',
        18: 'Olsem na was gut long yupela i harim olsem wanem. Long wanem, husat man i gat, long em God bai givim. Na husat man i no gat, long em God bai kisim, yes, dispela samting i luk olsem em i gat.',
        19: 'Nau mama bilong em i kam long em na ol brata bilong em, na ol i no inap long kam klostu long em, long wanem, ol man i pas pas tumas.',
        20: 'Na sampela i tokim em long dispela husat i tok, Mama bilong yu na ol brata bilong yu i sanap ausait, na ol i gat laik long lukim yu.',
        21: 'Na em i bekim na tokim ol, Mama bilong mi na ol brata bilong mi em ol dispela husat i harim tok bilong God, na mekim dispela.',
        22: '¶ Na em i kamap olsem long wanpela de, long em i go insait long wanpela sip wantaim ol disaipel bilong em. Na em i tokim ol, Yumi go hapsait i go long arapela sait bilong raunwara. Na ol i putim sip i go ausait.',
        23: 'Na taim ol i ran long sip em i slip. Na i gat kam daun wanpela bikpela win nogut antap long raunwara. Na ol i pulap wantaim wara, na ol i redi long stap aninit long bikpela bagarap.',
        24: 'Na ol i kam long em, na kirapim em, i spik, Tisa, tisa, mipela i laik dai olgeta. Nau em i kirap, na hatim win na pairap bilong wara. Na ol i pinis, na win na raunwara i stap isi olgeta.',
        25: 'Na em i tokim ol, Bilip tru bilong yupela i stap we? Na taim ol i pret ol i tingting planti, i spik wanpela i go long narapela, Dispela em i wanem kain man! Long wanem, em i tok strong, yes, long ol win na wara, na ol i bihainim tok bilong em.',
        26: 'Na ol i kamap long hap graun bilong ol man Gadara, dispela i pas klostu long Galili.',
        27: 'Na taim em i go long nambis, i gat i bungim em ausait long biktaun wanpela man, husat i gat ol spirit nogut longpela taim, na em i no werim ol klos, o stap insait long wanpela haus, tasol long ol matmat.',
        28: 'Taim em i lukim Jisas, em i singaut, na pundaun long ai bilong em, na wantaim bikpela nek em i tok, Mi gat wanem wok wantaim yu, Jisas, yu Pikinini Man bilong God i antap moa olgeta? Mi askim yu strong plis, no ken givim traipela pen long mi.',
        29: '(Long wanem, em i bin tok strong long spirit i no klin long kam ausait long dispela man. Long wanem, planti taim dispela i bin kisim em. Na ol man i holimpas em pas wantaim ol sen na long ol samting bilong pasim lek. Na em i brukim ol hankap samting, na dispela spirit nogut i ranim em i go long ples i no gat man.)',
        30: 'Na Jisas i askim em, i spik, Nem bilong yu em husat? Na em i tok, Lijon. Bilong wanem, planti spirit nogut i go insait long em.',
        31: 'Na ol i askim em strong plis long em i no inap tok strong long ol long go ausait i go insait long ples dip.',
        32: 'Na i gat i stap long dispela hap wanpela lain bilong planti pik i kaikai antap long maunten. Na ol i askim em strong plis long em i ken larim ol long go insait long ol. Na em i larim ol.',
        33: 'Nau ol spirit nogut i go ausait long dispela man, na go insait long ol pik. Na dispela lain pik i ran wantaim pasin pait i go daun long ples i maunten tru i go insait long raunwara, na nek bilong ol i pas.',
        34: 'Taim ol husat i givim kaikai long ol i luksave long wanem samting i kamap, ol i ranawe, na go na tokaut long dispela insait long biktaun na long hap i no gat planti man.',
        35: 'Nau ol i go ausait bilong lukim wanem samting i bin kamap. Na ol i kam long Jisas, na lukim dispela man, ausait long husat ol spirit nogut i go pinis, taim em i sindaun long tupela lek bilong Jisas, na werim klos, na tingting bilong em i stret. Na ol i pret.',
        36: 'Ol tu husat i lukim dispela i tokim ol long wanem rot em husat ol spirit nogut i bin holimpas i kamap orait.',
        37: 'Nau dispela bikpela lain tru olgeta bilong hap graun bilong ol lain Gadara raun nabaut i askim em strong plis long lusim ol. Long wanem, bikpela pret i kisim ol. Na em i kalap i go insait long sip, na go bek gen.',
        38: 'Nau dispela man ausait long husat ol spirit nogut i go i askim em strong plis long em i ken go wantaim em. Tasol Jisas i salim em i go, i spik,',
        39: 'Go bek long haus bilong yu yet, na soim ol man long God i bin mekim ol bikpela samting moa long yu. Na em i go long rot bilong em, na mekim i kamap ples klia long dispela biktaun olgeta long Jisas i bin mekim ol bikpela samting moa long em.',
        40: '¶ Na em i kamap olsem, long, taim Jisas i go bek pinis, ol manmeri i kisim em wantaim amamas. Long wanem, olgeta i wetim em.',
        41: 'Na, lukim, i gat i kam wanpela man husat nem bilong em em Jairas, na em i wanpela hetman bilong sinagog. Na em i pundaun long tupela lek bilong Jisas, na askim em strong plis long em i ken kam insait long haus bilong em.',
        42: 'Long wanem, em i gat wanpela pikinini meri tasol, klostu olsem twelpela krismas, na em i slip long bet na wok long dai. Tasol taim em i go ol manmeri i pas klostu strong long em.',
        43: 'Na wanpela meri, taim em i gat blut i kam ausait twelpela yia, husat i bin yusim olgeta mani samting bilong em long ol dokta, na tu i no gat wanpela bilong ol husat i inap long oraitim em,',
        44: 'I kam baksait long em, na tasim hap arere bilong klos bilong em. Na wantu blut i kam ausait bilong em i pas.',
        45: 'Na Jisas i tok, Husat i tasim mi? Taim olgeta i tok nogat, Pita na ol husat i stap wantaim em i tok, Tisa, bikpela lain tru i pas klostu strong long yu na pas pas long yu, na yu tok, Husat i tasim mi?',
        46: 'Na Jisas i tok, Wanpela i bin tasim mi. Long wanem, mi kisim save long gutpela strong i bin go ausait long mi.',
        47: 'Na taim meri i luksave long em i no hait moa, em i kam wantaim guria, na taim em i pundaun long ai bilong em, em i tokaut long em long ai bilong olgeta manmeri long wanem as bilong em i bin tasim em, na olsem wanem long em i kamap orait wantu.',
        48: 'Na em i tokim em, Pikinini meri, stap wantaim gutpela bel isi. Bilip tru bilong yu i bin mekim yu orait olgeta. Go wantaim bel isi.',
        49: 'Taim em i toktok yet, i gat wanpela i kam long haus bilong hetman bilong sinagog, i spik long em, Pikinini meri bilong yu i dai pinis. No ken givim wari moa long Tisa.',
        50: 'Tasol taim Jisas i harim dispela, em i bekim tok long em, i spik, No ken pret, bilip tasol, na meri bai kamap orait olgeta.',
        51: 'Na taim em i kam insait long haus, em i no larim arapela man i go insait, Pita, na Jems, na Jon, na papa na mama bilong dispela yangpela meri tasol.',
        52: 'Na olgeta i krai tru, na krai wantaim singaut long tingim meri. Tasol em i tok, No ken krai tru. Meri i no dai pinis, em i slip tasol.',
        53: 'Na ol i lap long em inap long sem bilong tok bilas, taim ol i save long meri i dai pinis.',
        54: 'Na em i putim olgeta i go ausait, na kisim meri long han, na singaut, i spik, Yangpela meri, kirap.',
        55: 'Na spirit bilong em i kam gen, na em i kirap kwiktaim. Na em i tok strong long givim kaikai long em.',
        56: 'Na papamama bilong em i kirap nogut. Tasol em i givim tok long ol long ol i no ken tokim ol man long wanem samting em i bin mekim.',
    },
    9: {
        1: '¶ Nau em i singautim twelpela disaipel bilong em wantaim, na givim ol pawa na namba long bosim olgeta spirit nogut, na long oraitim ol sik nogut.',
        2: 'Na em i salim ol long autim kingdom bilong God, na long oraitim ol sikman.',
        3: 'Na em i tokim ol, No ken kisim wanpela samting bilong wokabaut bilong yupela, o ol stik wokabaut, o liklik bek, o bret, o mani. Na tu yupela i no ken gat tupela saket wan wan.',
        4: 'Na wanem haus yupela i go insait long en, stap long dispela hap, na lusim long dispela ples.',
        5: 'Na husat man i no gat laik long kisim yupela, taim yupela i go ausait long dispela biktaun, seksekim dispela das stret long ol fut bilong yupela bilong givim wanpela testimoni i birua long ol.',
        6: 'Na ol i lusim dispela hap, na go namel long ol taun, na autim gutnius, na oraitim ol sikman long olgeta hap.',
        7: 'Nau namba foa hap king Herot i harim stori long olgeta samting long em i mekim. Na em i paul, bilong wanem, long sampela i tok, long Jon i kirap bek long dai,',
        8: 'Na long sampela, long Ilaias i bin kamap ples klia, na long ol arapela, long wanpela bilong ol olpela profet i kirap bek gen.',
        9: 'Na Herot i tok, Mi bin rausim het bilong Jon. Tasol dispela em i husat, long husat mi harim ol kain samting? Na em i gat laik long lukim em.',
        10: '¶ Na ol aposel, taim ol i kam bek, i tokim em long olgeta samting ol i bin mekim. Na em i kisim ol, na go long sait ol yet, insait long wanpela ples i no gat man i bilong biktaun ol i kolim Betsaida.',
        11: 'Na ol manmeri, taim ol i save long en, i bihainim em. Na em i kisim ol, na toktok long ol long kingdom bilong God, na oraitim ol sik bilong ol husat i gat nid long kamap orait gen.',
        12: 'Na taim de i stat long go pinis isi isi, nau dispela twelpela i kam, na tokim em, Salim dispela bikpela lain tru i go, inap long ol i ken go insait long ol taun na hap i no gat planti man raun nabaut, na painim ples bilong stap, na kisim kaikai. Long wanem, mipela i stap hia long wanpela ples i no gat man.',
        13: 'Tasol em i tokim ol, Yupela givim ol long kaikai. Na ol i tok, Mipela i no gat moa long faipela hap bret na tupela pis tasol, sapos mipela i no ken go na baim kaikai bilong olgeta dispela lain manmeri.',
        14: 'Long wanem, ol i klostu olsem 5,000 man. Na em i tokim ol disaipel bilong em, Mekim ol i sindaun long ol 50 long wanpela lain.',
        15: 'Na ol i mekim olsem, na mekim ol olgeta i sindaun.',
        16: 'Nau em i kisim dispela faipela hap bret na tupela pis, na taim em i lukluk i go antap long heven, em i blesim ol, na brukim, na givim long ol disaipel long putim long ai bilong dispela bikpela lain tru.',
        17: 'Na ol i bin kaikai, na olgeta i pulap. Na ol i bungim bilong ol dispela hap hap kaikai i stap yet long ol twelpela basket.',
        18: '¶ Na em i kamap olsem, taim em i stap em wanpela na beten, ol disaipel bilong em i stap wantaim em. Na em i askim ol, i spik, Ol manmeri i tok long mi husat?',
        19: 'Ol i bekim na tok, Jon dispela Baptist. Tasol sampela i tok, Ilaias. Na ol arapela i tok, long wanpela bilong ol olpela profet i kirap bek gen.',
        20: 'Na em i tokim ol, Tasol yupela i tok long mi husat? Na Pita i bekim na tok, Dispela Kraist bilong God.',
        21: 'Na em i givim tok long ol stret na tok strong long ol long ol i no ken tokim wanpela man long dispela samting,',
        22: 'I spik, Pikinini Man bilong man i mas karim hevi long planti samting, na ol lapun hetman na ol bikpris na ol man bilong rait i mas tok nogat olgeta long em, na ol i mas kilim em i dai, na God i mas kirapim em long namba tri de.',
        23: 'Na em i tokim ol olgeta, Sapos wanpela man i laik kam bihainim mi, larim em tok nogat long em yet, na kisim diwai kros bilong em olgeta wan wan de, na bihainim mi.',
        24: 'Long wanem, husat man i gat laik long kisim bek laip bilong em bai lusim dispela. Tasol husat man i gat laik long lusim laip bilong em bilong tingim mi, em yet bai kisim bek dispela.',
        25: 'Long wanem, em bai helpim man olsem wanem sapos em i winim dispela graun olgeta, na lusim em yet, o God i tromoi em i go?',
        26: 'Long wanem, husat man bai sem long mi na ol toktok bilong mi, long em bai Pikinini Man bilong man i sem, taim em bai kam long glori bilong em yet, na long glori bilong Papa bilong em, na bilong ol ensel holi.',
        27: 'Tasol mi tokim yupela long em i tru, i gat sampela i sanap long hia, husat bai i no inap testim dai, inap long ol i lukim kingdom bilong God.',
        28: '¶ Na em i kamap olsem klostu olsem etpela de bihain long ol dispela toktok, em i kisim Pita na Jon na Jems, na go antap long wanpela maunten long beten.',
        29: 'Na taim em i beten, pasin bilong pes bilong em i senis, na klos bilong em i waitpela na i lait.',
        30: 'Na, lukim, i gat tupela man i toktok wantaim em, husat i Moses na Ilaias.',
        31: 'Husat i kamap ples klia wantaim glori, na toktok long dai bilong em, dispela em i mas inapim long Jerusalem.',
        32: 'Tasol Pita na ol husat i stap wantaim em i hevi wantaim slip. Na taim ol i kirap, ol i lukim glori bilong em, na dispela tupela man husat i stap wantaim em.',
        33: 'Na em i kamap olsem, taim tupela i lusim em, Pita i tokim Jisas, Tisa, em i gutpela long mipela i stap long hia. Na larim mipela wokim tripela haus holi, wanpela bilong yu, na wanpela bilong Moses, na wanpela bilong Ilaias. Na em i no save long em i tok wanem.',
        34: 'Taim em i tok olsem, i gat wanpela klaut i kam, na karamapim ol. Na ol i pret taim ol i go insait long dispela klaut.',
        35: 'Na i gat wanpela nek i kam ausait long klaut, i spik, Dispela em i Pikinini Man i stap klostu tru long bel bilong mi. Harim em.',
        36: 'Na taim dispela nek i tok pinis, ol i lukim Jisas wanpela. Na ol i holimpas dispela klostu, na ol i no tokim wanpela man long ol dispela de long wanpela bilong ol dispela samting, dispela ol i bin lukim.',
        37: '¶ Na em i kamap olsem, long de bihain, taim ol i kam daun long liklik maunten, planti manmeri i bungim em.',
        38: 'Na, lukim, wanpela man bilong dispela lain i singaut, i spik, Tisa, mi askim yu strong plis, lukluk long pikinini man bilong mi. Long wanem, em i wanpela pikinini tasol bilong mi.',
        39: 'Na, harim, wanpela spirit i kisim em, na em i singaut wantu. Na dispela i brukim em inap long maus bilong em i kapsaitim waitpela spet gen, na taim em i givim liklik bagarap long em i hat tru long em i lusim em.',
        40: 'Na mi askim ol disaipel bilong yu strong plis long rausim em i go ausait, na ol i no inap.',
        41: 'Na Jisas i bekim tok, O lain tumbuna i no gat bilip tru na i paul, inap long wanem taim mi bai stap wantaim yupela, na karim pen long yupela? Bringim pikinini man bilong yu i kam long hia.',
        42: 'Na taim em i kam yet, dispela spirit nogut i tromoi em i go daun, na brukim skin bilong em. Na Jisas i hatim dispela spirit i no klin, na oraitim pikinini, na givim em i go gen long papa bilong em.',
        43: '¶ Na ol olgeta i kirap nogut tru long strongpela pawa bilong God. Tasol taim ol i tingting planti, olgeta wan wan, long olgeta dispela samting Jisas i mekim, em i tokim ol disaipel bilong em,',
        44: 'Larim ol dispela toktok i go daun isi isi insait long ol ia bilong yupela. Long wanem, ol bai givim Pikinini Man bilong man long ol han bilong ol man.',
        45: 'Tasol ol i no kisim save long dispela toktok, na em i stap hait long ol, inap long ol i no inap kisim save long en. Na ol pret long askim em long dispela toktok.',
        46: 'Nau i gat wanpela tingting ol i tingim namel long ol, long husat bilong ol i ken stap nambawan.',
        47: 'Na Jisas, taim em i kisim save long tingting bilong bel bilong ol, i kisim wanpela pikinini, na putim em klostu long em,',
        48: 'Na em i tokim ol, Husat man bai kisim dispela pikinini long nem bilong mi i kisim mi. Na husat man bai kisim mi i kisim em husat i salim mi. Long wanem, em husat i las man namel long yupela olgeta, dispela stret bai stap bikpela.',
        49: 'Na Jon i bekim na tok, Tisa, mipela i lukim wanpela i rausim ol spirit nogut long nem bilong yu. Na mipela i tambuim em, bilong wanem, em i no bihainim yu wantaim mipela.',
        50: 'Na Jisas i tokim em, No ken tambuim em. Long wanem, em husat i no birua bilong yumi i stap long sait bilong yumi.',
        51: '¶ Na em i kamap olsem, taim taim i kam pinis long God i mas kisim em i go antap, em i putim pes bilong em i strong long go long Jerusalem,',
        52: 'Na em i salim ol mausman i go paslain long pes bilong em. Na ol i go, na go insait long wanpela vilis bilong ol lain Samaria, long redim ples long em.',
        53: 'Na ol i no bin kisim em, bilong wanem, pes bilong em i olsem em bai go long Jerusalem.',
        54: 'Na taim tupela disaipel bilong em Jems na Jon i lukim dispela, ol i tok, Bikpela, yu gat laik long mitupela i mas tok strong long paia long kam daun long heven, na kaikai ol olgeta, yes, olsem Ilaias i mekim?',
        55: 'Na em i tanim na hatim ol, na tok, Yupela i no save long yupela i bilong wanem kain spirit.',
        56: 'Long wanem, Pikinini Man bilong man i no kam long bagarapim olgeta ol laip bilong ol man, tasol long kisim bek ol. Na ol i go long narapela vilis.',
        57: '¶ Na em i kamap olsem, long, taim ol i stap long rot, wanpela man i tokim em, Bikpela, mi bai bihainim yu long wanem hap yu go.',
        58: 'Na Jisas i tokim em, Ol foks i gat ol hul, na ol pisin bilong skai i gat ol haus pisin. Tasol Pikinini Man bilong man i no gat hap we em i ken slipim het bilong em.',
        59: 'Na em i tokim narapela, Bihainim mi. Tasol em i tok, Bikpela, larim mi go pastaim na planim papa bilong mi.',
        60: 'Jisas i tokim em, Larim ol daiman planim ol daiman bilong ol. Tasol yu go na autim kingdom bilong God.',
        61: 'Na narapela tu i tok, Bikpela, mi bai bihainim yu. Tasol larim mi go pastaim na tok gutbai long ol husat i stap long ples long haus bilong mi.',
        62: 'Na Jisas i tokim em, I no gat man, taim em i bin putim han bilong em i go long samting bilong brukim graun, na em i lukluk i go bek, husat i fit long kingdom bilong God.',
    },
    10: {
        1: '¶ Bihain long ol dispela samting Bikpela i makim arapela 70 tu, na salim ol tupela tupela long ai bilong pes bilong em i go insait long olgeta wan wan biktaun na ples, we em em yet bai kam.',
        2: 'Olsem na em i tokim ol, Tru tumas, kamautim bilong kaikai i bikpela, tasol ol wokman i no planti. Olsem na yupela i mas beten long Bikpela bilong kamautim kaikai, long em bai salim i go ausait ol wokman long kamautim kaikai bilong em.',
        3: 'Go long ol rot bilong yupela. Lukim, mi salim yupela i go ausait olsem ol pikinini sipsip namel long ol wolf.',
        4: 'No ken karim paus mani, o liklik bek, o ol su. Na no ken tok gude long wanpela man long rot.',
        5: 'Na insait long wanem haus yupela i go, tok pastaim, Bel isi i stap long dispela haus.',
        6: 'Na sapos pikinini man bilong bel isi i stap long dispela hap, bel isi bilong yupela bai slip antap long en. Sapos nogat, em bai tanim gen i kam long yupela.',
        7: 'Na long dispela haus stret stap yet, na kaikai na dringim ol kain samting olsem ol i givim yupela. Long wanem, man bilong hatwok i gat namba inap long pe bilong em. No ken go haus i go long haus.',
        8: 'Na insait long wanem biktaun yupela i go, na ol i kisim yupela, kaikai ol kain samting olsem ol i putim long ai bilong yupela.',
        9: 'Na oraitim ol sikman husat i stap insait long en, na tokim ol, Kingdom bilong God i kam klostu long yupela.',
        10: 'Tasol insait long wanem biktaun yupela i go, na ol i no kisim yupela, go long ol rot bilong yupela ausait long ol rot bilong dispela stret, na tok,',
        11: 'Yes, dispela das stret bilong biktaun bilong yupela, dispela i pas strong long mipela, mipela i klinim i go i birua long yupela. Tasol yupela i mas save dispela tru, long kingdom bilong God i kam klostu long yupela.',
        12: 'Tasol mi tokim yupela, long em bai stap orait moa long Sodom long dispela de, moa long dispela biktaun.',
        13: 'Tok lukaut i go long yu, Korasin! Tok lukaut i go long yu, Betsaida! Long wanem, sapos God i bin mekim ol strongpela wok insait long Tair na Saidon, dispela God i bin mekim insait long yupela, ol i bin tanim bel longpela taim i go pinis, na sindaun long bek laplap na sit bilong paia.',
        14: 'Tasol em bai orait moa long Tair na Saidon long kot, moa long yupela.',
        15: 'Na yu, Kaperneam, husat God i litimapim i go long heven, God bai subim yu i go daun long hel.',
        16: 'Em husat i harim yupela i harim mi. Na em husat i tingim olsem yupela i samting nating i tingim olsem mi samting nating. Na em husat i tingim olsem mi samting nating i tingim olsem em husat i salim mi em i samting nating.',
        17: '¶ Na dispela 70 i kam bek gen wantaim amamas tru, i spik, Bikpela, yes, ol spirit nogut i stap aninit long mipela long nem bilong yu.',
        18: 'Na em i tokim ol, Mi lukim Seten i pundaun long heven olsem lait bilong klaut.',
        19: 'Lukim, mi givim pawa long yupela long krungutim ol snek na ol skopian, na long bosim olgeta pawa bilong birua. Na i no gat rot long wanpela samting bai bagarapim yupela.',
        20: 'Tasol no ken wokim amamas tru long dispela, long ol spirit i stap aninit long yupela. Tasol mobeta yupela i wokim amamas tru, bilong wanem, ol nem bilong yupela God i raitim long heven.',
        21: 'Long dispela aua Jisas i wokim amamas tru insait long spirit, na tok, Mi tok tenkyu long yu, O Papa, Bikpela bilong heven na dispela graun, long yu bin haitim ol dispela samting long ol saveman na man bilong yusim save, na yu bin soim ol ples klia long ol bebi. Yes olsem, Papa, long wanem, em i luk olsem i gutpela long ai bilong yu.',
        22: 'Papa bilong mi i givim olgeta samting i kam long mi. Na i no gat man i save long Pikinini Man em i husat, Papa tasol, na Papa em i husat, Pikinini Man tasol, na em long husat Pikinini Man bai soim em ples klia.',
        23: 'Na em i tanim em yet i go long ol disaipel bilong em, na tokim ol ol yet, Blesing i stap long ol ai husat i lukim ol dispela samting yupela i lukim.',
        24: 'Long wanem, mi tokim yupela, long planti profet na king i bin gat laik long lukim ol dispela samting, dispela yupela i lukim, na ol i no bin lukim ol, na long harim ol dispela samting, dispela yupela i harim, na ol i no bin harim ol.',
        25: '¶ Na, lukim, wanpela masta kot i sanap, na traim em, i spik, Tisa, mi bai mekim wanem samting long kisim laip i stap gut oltaim oltaim olsem samting papa i givim pikinini?',
        26: 'Em i tokim em, Wanem rait i stap long lo? Yu ritim olsem wanem?',
        27: 'Na em i bekim tok, Yu bai laikim tru Bikpela, God bilong yu, wantaim olgeta bel bilong yu, na wantaim olgeta tewel bilong yu, na wantaim olgeta strong bilong yu, na wantaim olgeta tingting bilong yu, na man i stap klostu long yu olsem yu yet.',
        28: 'Na em i tokim em, Yu bin bekim tok stret. Mekim dispela, na yu bai stap laip.',
        29: 'Tasol em, taim em i laik mekim em yet i kamap stretpela, i tokim Jisas, Na man i stap klostu long mi em i husat?',
        30: 'Na Jisas i bekim tok, Wanpela man i lusim Jerusalem i go daun long Jeriko, na em i pundaun namel long ol stilman, husat i rausim ol klos bilong em, na bagarapim em, na ol i go, na lusim em olsem man i laik dai.',
        31: 'Na long sans i gat i kam daun wanpela pris long dispela rot. Na taim em i lukim em, em i abrusim em long arapela sait.',
        32: 'Na wankain olsem wanpela man Livai, taim em i kam long dispela ples, i kam na lukluk long em, na abrusim em long arapela sait.',
        33: 'Tasol wanpela man Samaria, taim em i wokim wokabaut, i kam long hap we em i stap. Na taim em i lukim em, em i gat sori tru long em,',
        34: 'Na em i go long em, na pasim gut ol bagarap bilong em, na kapsaitim wel na wain long ol, na putim em antap long animal bilong em yet, na bringim em long wanpela haus pasindia, na lukautim em.',
        35: 'Na long de bihain taim em i lusim hap, em i kisim tupela pens, na givim ol long papa bilong haus pasindia, na tokim em, Lukautim em. Na wanem samting yu yusim moa, taim mi kam gen, mi bai bekim pe long yu.',
        36: 'Nau husat bilong dispela tripela, long tingting bilong yu, em i man i stap klostu long em husat i pundaun namel long ol stilman?',
        37: 'Na em i tok, Em husat i soim sori long em. Nau Jisas i tokim em, Go, na yu mekim wankain olsem.',
        38: '¶ Na em i kamap olsem, taim ol i go, long em i go insait long wanpela vilis. Na wanpela meri husat nem bilong em em Marta i kisim em i go insait long haus bilong em.',
        39: 'Na em i gat wanpela susa ol i kolim Maria, husat tu i sindaun long tupela lek bilong Jisas, na harim tok bilong em.',
        40: 'Tasol Marta i pilim hevi nabaut long wokim planti wok, na em i kam long em, na tok, Bikpela, ating i yes long yu wari long susa bilong mi i bin lusim mi long wokim wok mi wanpela? Olsem na tokim em long em i mas helpim mi.',
        41: 'Na Jisas i bekim na tokim em, Marta, Marta, yu wari na pilim wari long sait bilong planti samting.',
        42: 'Tasol i gat nid long wanpela samting. Na Maria i bin makim dispela gutpela hap, na bai mi no inap tekewe dispela long em.',
    },
    11: {
        1: '¶ Na em i kamap olsem, long, taim em i beten long wanpela ples, taim em i pinis, wanpela bilong ol disaipel bilong em i tokim em, Bikpela, skulim mipela long beten, olsem Jon tu i skulim ol disaipel bilong em.',
        2: 'Na em i tokim ol, Taim yupela i beten, tok, Papa bilong mipela husat i stap long heven, Nem bilong yu i stap holi olgeta. Kingdom bilong yu i mas kam. Laik bilong yu i mas kamap, olsem long heven, olsem tasol long dispela graun.',
        3: 'Olgeta wan wan de givim mipela bret bilong mipela inap long dispela de.',
        4: 'Na lusim ol sin bilong mipela. Long wanem, mipela tu i lusim dinau bilong olgeta wan wan man husat i gat dinau long mipela. Na no ken stiaim mipela i go insait long traim, tasol kisim bek mipela long ol pasin nogut.',
        5: 'Na em i tokim ol, Husat bilong yupela bai gat wanpela pren, na em bai go long em long belo biknait, na tokim em, Pren, dinau long mi long tripela hap bret,',
        6: 'Long wanem, wanpela pren bilong mi i kam long mi long wokabaut bilong em, na mi no gat wanpela samting long putim long ai bilong em?',
        7: 'Na man i stap insait bai bekim na tok, No ken givim wari long mi. Dua i pas pinis nau, na ol pikinini bilong mi i stap wantaim mi long bet. Mi no inap long kirap na givim long yu.',
        8: 'Mi tokim yupela, Maski em i no gat laik long kirap na givim em, bikos em i pren bilong em, tasol bikos em i askim askim planti em bai kirap na givim hamas em i gat nid long en.',
        9: 'Na mi tokim yupela, Askim, na God bai givim dispela long yupela. Painim, na yupela bai lukim. Paitim dua, na em bai op long yupela.',
        10: 'Long wanem, olgeta wan wan husat i askim i kisim. Na em husat i painim i lukim. Na long em husat i paitim dua, ol bai opim dispela.',
        11: 'Sapos wanpela pikinini man bai askim bret long wanpela bilong yupela husat i stap wanpela papa, bai em i givim em wanpela ston? O sapos em i askim long wanpela pis, bai em i givim em wanpela snek bilong kisim ples bilong pis?',
        12: 'O sapos em bai askim long wanpela kiau, bai em i tokim em long kisim wanpela skopian?',
        13: 'Nau sapos yupela, taim yupela i stap ol man nogut, i save long rot bilong givim ol gutpela presen i go long ol pikinini bilong yupela, hamas moa bai Papa bilong yupela long heven i givim Holi Spirit long ol husat i askim em?',
        14: '¶ Na em i wok long rausim wanpela spirit nogut, na em i mauspas. Na em i kamap olsem, taim dispela spirit nogut i go ausait, dispela mauspas i toktok. Na ol manmeri i tingting planti.',
        15: 'Tasol sampela bilong ol i tok, Em i rausim ol spirit nogut long wok bilong Bielsebap, nambawan hetman bilong ol spirit nogut.',
        16: 'Na ol arapela, taim ol i traim em, i painim long em wanpela mak i kam long heven.',
        17: 'Tasol em, taim em i save long ol tingting bilong ol, i tokim ol, Olgeta wan wan kingdom i bruk i birua long em yet i bagarap inap long i stap nating olgeta. Na wanpela hauslain i bruk i birua long hauslain i pundaun.',
        18: 'Sapos Seten tu i bruk i birua long em yet, kingdom bilong em bai sanap olsem wanem? Bilong wanem, yupela i tok olsem mi rausim ol spirit nogut i go long wok bilong Bielsebap.',
        19: 'Na sapos mi, long wok bilong Bielsebap, i rausim i go ol spirit nogut, long wok bilong husat ol pikinini man bilong yupela i rausim ol i go ausait? Olsem na ol bai stap ol jas bilong yupela.',
        20: 'Tasol sapos mi, wantaim pinga bilong God, i rausim ol spirit nogut i go ausait, i mas tru olgeta long kingdom bilong God i kamap long yupela.',
        21: 'Taim wanpela strongpela man i gat ol samting bilong pait i lukautim gut haus king bilong em, ol kago bilong em i stap wantaim bel isi.',
        22: 'Tasol taim wanpela man i strongpela moa long em bai kamap long em, na winim em, em i kisim long em olgeta klos pait we em i putim bilip long ol, na tilim ol kago bilong pait bilong em.',
        23: 'Em husat i no stap wantaim mi i birua long mi. Na em husat i no bungim wantaim mi i brukim nabaut.',
        24: 'Taim wanpela spirit i no klin i go ausait long wanpela man, em i wokabaut namel long ol ples i drai, na painim malolo. Na taim em i no lukim liklik, em i tok, Mi bai go bek long haus bilong mi we mi kam ausait long en.',
        25: 'Na taim em i kam, em i luksave long ol i brumim na bilasim dispela.',
        26: 'Nau em i go, na kisim long em sevenpela arapela spirit i nogut moa long em yet. Na ol i go insait, na stap long dispela hap. Na las sin daun bilong dispela man em i nogut moa long stat bilong en.',
        27: '¶ Na em i kamap olsem, taim em i toktok long ol dispela samting, wanpela meri bilong dispela lain i litimapim nek bilong em, na tokim em, Blesing i stap long bel husat i bin karim yu, na ol dispela ai bilong susu yu bin susu long ol.',
        28: 'Tasol em i tok, Yes mobeta, blesing i stap long ol husat i harim tok bilong God, na bihainim dispela.',
        29: '¶ Na taim ol manmeri i bung pas klostu wantaim, em i stat long tok, Dispela em i wanpela lain tumbuna nogut. Ol i painim wanpela mak. Na God bai i no inap givim wanpela mak long ol, mak bilong profet Jonas tasol.',
        30: 'Long wanem, olsem Jonas em i wanpela mak long ol lain Niniva, olsem tasol tu bai Pikinini Man bilong man i stap long dispela lain tumbuna.',
        31: 'Kwin bilong hap saut bai kirap long kot wantaim ol man bilong dispela lain tumbuna, na sutim tok long ol. Long wanem, em i kam long ol las hap bilong dispela graun long harim save tru bilong Solomon. Na, lukim, man i winim Solomon i stap long hia.',
        32: 'Ol man bilong Niniva bai kirap long kot wantaim dispela lain tumbuna, na ol bai sutim tok long en. Long wanem, ol i tanim bel long autim tok bilong Jonas. Na, lukim, man i winim Jonas i stap long hia.',
        33: 'I no gat man, taim em i bin laitim kandel, husat i putim dispela long ples hait, o aninit long busel basket, tasol antap long stik kandel, inap long ol husat i kam insait i ken lukim dispela lait.',
        34: 'Lait bilong bodi em i ai. Olsem na taim ai bilong yu i gutpela, bodi olgeta bilong yu tu i pulap long lait. Tasol taim ai bilong yu i nogut, bodi bilong yu tu i pulap long tudak.',
        35: 'Olsem na was gut long dispela lait i stap insait long yu i no stap tudak',
        36: 'Olsem na sapos bodi bilong yu olgeta i pulap long lait, taim em i no gat hap i tudak, bodi olgeta bai pulap long lait, olsem taim lait tru bilong wanpela kandel i givim yu lait.',
        37: '¶ Na taim em i toktok, wanpela Farisi i askim em strong plis long kam kaikai wantaim em. Na em i go insait, na sindaun long kaikai.',
        38: 'Na taim dispela Farisi i lukim dispela, em i tingting planti long em i no bin wasim han pastaim bipo long bikpela kaikai.',
        39: 'Na Bikpela i tokim em, Nau yupela ol Farisi i mekim ausait bilong kap na bikpela plet i klin. Tasol insait hap bilong yupela i pulap wantaim pasin bilong kaikai wantaim bikpela hangre na pasin nogut.',
        40: 'Yupela krankiman, ating i yes long em husat i wokim dispela samting i ausait i bin wokim dispela samting i insait tu?',
        41: 'Tasol mobeta yupela i givim sori mani bilong ol kain samting yupela i gat. Na, lukim, olgeta samting i klin long yupela.',
        42: 'Tasol tok lukaut i go long yupela, ol Farisi! Long wanem, yupela i givim namba ten hap long mint na ru na olgeta kain sayor, na abrusim kot na laikim tru bilong God. Ol dispela samting yupela i mas bin mekim, na no ken lusim arapela we yupela i no mekim.',
        43: 'Tok lukaut i go long yupela, ol Farisi! Long wanem, yupela i laikim tru ol sia i antap moa olgeta insait long ol sinagog, na ol tok gude long ol maket.',
        44: 'Tok lukaut i go long yupela, ol man bilong rait na ol Farisi, ol man bilong tupela maus! Long wanem, yupela i stap olsem ol dispela matmat i no kamap ples klia, na ol man husat i wokabaut antap long ol i no klia long ol i stap.',
        45: 'Nau wanpela bilong ol masta kot i bekim, na tokim em, Tisa, taim yu toktok olsem yu givim sem long mipela tu.',
        46: 'Na em i tok, Tok lukaut i go long yupela tu, yupela ol masta kot! Long wanem, yupela i pulapim ol man wantaim ol hevi i hevi nogut tru long karim, na yupela yupela yet i no tasim ol dispela hevi wantaim wanpela bilong ol pinga bilong yupela.',
        47: 'Tok lukaut i go long yupela! Long wanem, yupela i wokim ol matmat bilong ol profet, na ol tumbuna papa bilong yupela i bin kilim ol.',
        48: 'Tru tumas, yupela i stap witnes long yupela i orait long ol wok bilong ol tumbuna papa bilong yupela. Long wanem, em i tru long ol i kilim ol, na yupela i wokim ol matmat bilong ol.',
        49: 'Olsem na tu save tru bilong God i tok, Mi bai salim ol ol profet na ol aposel, na sampela bilong ol bai ol i kilim i dai na givim hevi,',
        50: 'Inap long blut bilong olgeta profet, dispela ol i bin kapsaitim i stat long ol as ston bilong dispela graun, mi ken strong long askim long dispela lain tumbuna,',
        51: 'I stat long blut bilong Ebel i go inap long blut bilong Sakaraias, husat i dai olgeta namel long alta na tempel. Tru tumas, mi tokim yupela, mi bai strong long askim long dispela lain tumbuna.',
        52: 'Tok lukaut i go long yupela, ol masta kot! Long wanem, yupela i bin tekewe ki bilong save. Yupela i no go insait yupela yet, na ol husat i wok long go insait yupela i pasim rot bilong ol.',
        53: 'Na taim em i tokim ol dispela samting long ol, ol man bilong rait na ol Farisi i stat long pulim em strong nogut tru, na kirapim em long toktok long planti samting,',
        54: 'Taim ol i wet hait long em, na painim rot long kisim samting ausait long maus bilong em, inap long ol i ken sutim tok long em.',
    },
    12: {
        1: '¶ Long dispela taim tu, taim ol i bung wantaim wanpela bikpela lain tru man i no inap kaunim bilong ol manmeri, inap olsem long ol i wokabaut antap long wanpela i go long narapela, em i stat long tokim ol disaipel bilong em pastaim long olgeta, Yupela lukaut gut long yis bilong ol Farisi, dispela em i pasin bilong tupela maus.',
        2: 'Long wanem, i no gat wanpela samting ol i karamapim, long em bai i no inap kamap ples klia, na tu samting ol i haitim, long ol man bai i no inap save long en.',
        3: 'Olsem na wanem samting yupela i bin toktok long tudak bai ol man i harim long lait. Na dispela samting yupela i bin toktok long ia insait long ol liklik rum bai ol i telimautim antap long ol antap bilong ol haus.',
        4: 'Na mi tokim yupela ol pren bilong mi, No ken pret long ol husat i kilim bodi, na bihain long dispela i no gat samting moa long ol i ken mekim.',
        5: 'Tasol mi bai tok lukaut long yupela long yupela bai pretim husat. Pretim em, husat bihain long em i bin kilim yupela em i gat pawa bilong tromoi yupela insait long hel. Yes, mi tokim yupela, Pretim em.',
        6: 'Ating i yes long ol i salim faipela spero long tupela fating, na i no gat wanpela bilong ol God i lusim tingting long ol?',
        7: 'Tasol, yes, ol gras stet bilong het bilong yupela God i kaunim olgeta. Olsem na no ken pret. Yupela i dia moa long planti spero.',
        8: 'Na tu mi tokim yupela, Husat man bai tok yes long mi long ai bilong ol man, Pikinini Man bilong man bai tok yes tu long em long ai bilong ol ensel bilong God.',
        9: 'Tasol em husat i tok nogat long mi long ai bilong ol man bai mi tok nogat long em long ai bilong ol ensel bilong God.',
        10: 'Na husat man bai tokim wanpela toktok i birua long Pikinini Man bilong man, God bai lusim dispela sin long em. Tasol long em husat i tok bilas i birua long Holi Spirit God bai i no inap lusim dispela.',
        11: 'Na taim ol i bringim yupela long ol sinagog, na long ol kiap, na ol man i gat pawa, yupela i no ken tingting planti long yupela bai bekim olsem wanem o wantaim wanem samting, o long yupela bai tok wanem.',
        12: 'Long wanem, Holi Spirit bai skulim yupela long dispela aua stret long yupela i mas tok wanem.',
        13: '¶ Na wanpela bilong dispela lain i tokim em, Tisa, toktok long brata bilong mi, long em i ken brukim samting papa i givim long pikinini wantaim mi.',
        14: 'Na em i tokim em, Man, husat i mekim mi wanpela jas o man bilong brukim samting long bosim yupela?',
        15: 'Na em i tokim em, Was gut, na lukaut gut long pasin mangal. Long wanem, laip bilong man i no stap gut long ol dispela planti samting moa yet em i holimpas.',
        16: 'Na em i tokim ol long wanpela tok piksa, i spik, Graun bilong wanpela maniman i karim planti kaikai moa.',
        17: 'Na em i tingting insait long em yet, i spik, Mi bai mekim wanem, bilong wanem, mi no gat spes we mi ken putim ol kaikai bilong mi?',
        18: 'Na em i tok, Mi bai mekim dispela. Mi bai pulim ol bakstua bilong mi i go daun, na wokim sampela i bikpela moa. Na long dispela hap bai mi putim olgeta kaikai bilong mi na ol kago bilong mi.',
        19: 'Na mi bai tokim tewel bilong mi, Tewel, yu gat planti kago i bung i stap bilong planti yia. Kisim malolo bilong yu, kaikai, dring, na stap amamas.',
        20: 'Tasol God i tokim em, Yu krankiman, dispela nait mi bai strong long askim long yu long tewel bilong yu. Nau ol dispela samting bai bilong husat, dispela yu bin redim?',
        21: 'Em i olsem long em husat i bungim i stap ol samting i dia tru bilong em yet, na i no pulap long samting i dia tru i go long God.',
        22: '¶ Na em i tokim ol disaipel bilong em, Olsem na mi tokim yupela, No ken tingting planti long laip bilong yupela, long yupela bai kaikai wanem. Na tu long bodi, long yupela bai werim wanem.',
        23: 'Laip em i moa long kaikai, na bodi i moa long klos.',
        24: 'Tingim na skelim ol kotkot. Long wanem, ol i no planim o kamautim, husat i no gat haus bilong putim kago o bakstua. Na God i givim kaikai long ol. Hamas moa yupela i winim ol pisin?',
        25: 'Na husat bilong yupela taim em i tingting planti i ken skruim wanpela kyubit long longpela bilong em?',
        26: 'Nau sapos yupela i no inap long wokim dispela samting i liklik olgeta, bilong wanem yupela i tingting planti long ol arapela?',
        27: 'Tingim na skelim ol lili long ol i kamap bikpela olsem wanem. Ol i no hatwok, ol i no tantanim. Na yet mi tokim yupela, long Solomon insait long olgeta glori bilong em i no putim naispela klos i olsem wanpela bilong ol dispela.',
        28: 'Nau sapos God i putim klos long gras olsem, dispela i stap tude long ples kunai, na tumora ol i tromoi insait long aven, hamas moa bai em i putim klos long yupela, O yupela bilong liklik bilip tru?',
        29: 'Na yupela i no ken painim wanem samting yupela bai kaikai, o wanem samting yupela bai dring, na tu yupela i no ken gat tingting i pulap long tupela tingting.',
        30: 'Long wanem, olgeta ol dispela samting ol kantri bilong dispela graun i painim strong. Na Papa bilong yupela i save long yupela i gat nid long ol dispela samting.',
        31: 'Tasol mobeta yupela i painim kingdom bilong God. Na God bai skruim olgeta dispela samting long yupela.',
        32: 'No ken pret, liklik lain sipsip. Long wanem, em i gutpela amamas bilong Papa bilong yupela long givim kingdom long yupela.',
        33: 'Salim long mani dispela yupela i gat, na givim sori mani. Redim long yupela yet ol dispela bek i no wok long kamap olpela, wanpela samting i dia tru insait long ol heven, dispela i no inap fel, we i no gat stilman i ken kam klostu, o bataplai bilong nait i ken bagarapim.',
        34: 'Long wanem, we samting i dia tru bilong yupela i stap, bel bilong yupela bai stap long dispela hap tu.',
        35: 'Pasim strong nabaut ol namel bilong bel bilong yupela, na larim ol lait bilong yupela i ken paia.',
        36: 'Na yupela yupela yet i ken stap olsem ol man husat i wet long bikman bilong ol, taim em bai kam bek long dispela marit. Inap long taim em i kam na paitim dua, ol i ken opim long em wantu.',
        37: 'Blesing i stap long ol dispela wokboi, husat taim bikman bilong ol i kam em bai lukim ol i was i stap. Tru tumas, mi tokim yupela, long em bai pasim strong namel bilong em yet, na mekim ol long sindaun long kaikai, na em bai kam ausait na tilim kaikai long ol.',
        38: 'Na sapos em bai kam long namba tu was, o kam long namba tri was, na lukim ol olsem, blesing bai stap long ol dispela wokboi.',
        39: 'Na save long dispela, long sapos papa bilong haus i bin save long wanem aua stilman i laik kam, em i bin was, na em i no bin larim stilman i brukim i kam namel long haus bilong em.',
        40: 'Olsem na yupela i mas stap redi tu. Long wanem, Pikinini Man bilong man i kam long wanpela aua, taim yupela i no ting.',
        41: '¶ Nau Pita i tokim em, Bikpela, yu toktok long dispela tok piksa long mipela, o, yes, long olgeta?',
        42: 'Na Bikpela i tok, Husat nau em i dispela man bilong lukautim ol samting yu inap bilip long em na i gat save tru, husat bikman bilong em bai mekim em hetman long bosim hauslain bilong em, long givim ol ol hap skel bilong kaikai bilong ol long taim stret em i makim?',
        43: 'Blesing i stap long dispela wokboi, husat taim bikman bilong em i kam em bai luksave long em i mekim olsem.',
        44: 'Em i tru, mi tokim yupela, long em bai mekim em hetman long bosim olgeta samting em i gat.',
        45: 'Tasol na sapos dispela wokboi i toktok insait long bel bilong em, Bikman bilong mi i no mekim kam bek bilong em hariap, na em bai stat long paitim ol wokman na ol yangpela meri, na long kaikai na dring, na long stap spak,',
        46: 'Bikman bilong dispela wokboi bai kam long wanpela de, taim em i no lukluk long em, na long wanpela aua, taim em i no klia long en, na em bai katim em long ol hap, na em bai makim hap skel bilong em wantaim ol man i no gat bilip.',
        47: 'Na dispela wokboi, husat i save long laik bilong bikman bilong em, na em i no redim em yet, na tu em i no mekim bilong bihainim laik bilong em, ol bai paitim wantaim planti mak bilong wip.',
        48: 'Tasol em husat i no save, na em i mekim ol samting i inap long ol mak bilong wip, ol bai paitim ol wantaim liklik namba tasol bilong ol mak bilong wip. Long wanem, long husat man em i givim planti, long em bai em i strong long askim planti. Na long husat ol man i bin putim planti long han bilong em, long em ol bai askim moa.',
        49: 'Mi kam long salim paia long dispela graun. Na mi bai mekim wanem, sapos paia i kirap pinis long dispela?',
        50: 'Tasol mi gat wanpela baptais mi bai kisim baptais long en. Na mi ken pilim bikpela wari inap long dispela i kamap pinis olsem wanem!',
        51: 'Yupela i ting olsem long mi kam long givim bel isi long dispela graun? Mi tokim yupela, Nogat, tasol mobeta long brukim.',
        52: 'Long wanem, i stat long nau i go bai i gat faipela insait long wanpela hauslain i bruk, tripela i birua long tupela, na tupela i birua long tripela.',
        53: 'Papa bai bruk i birua long pikinini man, na pikinini man i birua long papa. Mama bai birua long pikinini meri, na pikinini meri bai i birua long mama. Tambu mama bai birua long tambu pikinini meri bilong em, na tambu pikinini meri bai birua long tambu mama bilong em.',
        54: '¶ Na em i tok tu long ol manmeri, Taim yupela i lukim wanpela klaut i kirap long hap wes, kwiktaim yupela i tok, I gat ren bai kam. Na em i olsem.',
        55: 'Na taim yupela i lukim win i ran i kam long hap saut, yupela i tok, Hat bai kam. Na dispela i kamap olsem.',
        56: 'Yupela ol man bilong tupela maus, yupela i ken kamap klia tru long pes bilong skai na bilong dispela graun. Tasol olsem wanem em i stap olsem long yupela i no kamap klia tru long dispela taim?',
        57: 'Yes, na bilong wanem, yes, long yupela yet yupela i no jasim wanem samting i stretpela?',
        58: 'Taim yu go wantaim birua bilong yu long kiap, taim yu stap long rot, wok strong long samting i ken kisim bek yu long em. Nogut em i karim yu i go long jas, na jas i givim yu long ofisa, na ofisa i tromoi yu i go insait long kalabus.',
        59: 'Mi tokim yu, yu bai i no inap lusim dispela ples, inap long yu bin baim las mait tru.',
    },
    13: {
        1: '¶ I gat long dispela taim sampela i stap husat i tokim em long ol man Galili, husat Pailat i bin abusim blut bilong ol wantaim ol sakrifais bilong ol.',
        2: 'Na Jisas i bekim tok long ol, Yupela i ting olsem long ol dispela man Galili i ol sinman antap long olgeta man Galili, bikos ol i karim pen long ol kain samting?',
        3: 'Mi tokim yupela, Nogat. Tasol, sapos yupela i no tanim bel, yupela olgeta bai dai olgeta wankain olsem.',
        4: 'O dispela 18, antap long husat dispela taua long Siloam i pundaun, na kilim ol i dai, yupela i ting long ol i ol sinman antap long olgeta man husat i stap long Jerusalem?',
        5: 'Mi tokim yupela, Nogat. Tasol, sapos yupela i no tanim bel, yupela olgeta bai dai olgeta wankain olsem.',
        6: '¶ Em i toktok tu long dispela tok piksa. Wanpela man i bin planim wanpela diwai fik long gaden wain bilong em. Na em i kam na painim kaikai long en, na em i no lukim sampela liklik.',
        7: 'Nau em i tokim man bilong mekim wok long gaden wain bilong em, Lukim, dispela tripela yia mi kam painim kaikai long dispela diwai fik, na mi no lukim sampela liklik. Katim em i go daun. Bilong wanem em i ken pasim spes long graun?',
        8: 'Na em i bekim na tokim em, Bikman, larim em i stap dispela yia tu, inap long mi bai digim nabaut long en, na putim pekpek long en.',
        9: 'Na sapos em i karim kaikai, gutpela. Na sapos nogat, orait bihain long dispela yu bai katim em i go daun.',
        10: '¶ Na em i skulim ol man long wanpela bilong ol sinagog long sabat.',
        11: 'Na, lukim, i gat wanpela meri husat i gat wanpela spirit bilong sik 18 yia, na baksait i krungut wantaim, na em i no inap tru long litimapim em yet.',
        12: 'Na taim Jisas i lukim em, em i singautim em long kam long em, na em i tokim em, Meri, sik bilong yu i lusim yu nau.',
        13: 'Na em i slipim tupela han bilong em antap long em. Na wantu em i mekim em long sanap stretpela, na em i givim glori long God.',
        14: 'Na hetman bilong sinagog i bekim wantaim bel nogut, bikos Jisas i bin oraitim meri long de sabat, na em i tokim ol manmeri, I gat sikispela de, insait long dispela ol man i mas wok. Olsem na insait long ol kam na kamap orait, na i no long de sabat.',
        15: 'Nau Bikpela i bekim em, na tok, Yu man bilong tupela maus, ating i yes long olgeta wan wan bilong yupela long sabat i lusim bulmakau man bilong em o donki bilong em long rum bilong animal, na stiaim em i go long kisim wara?',
        16: 'Na ating i yes long dispela meri, taim em i stap wanpela pikinini meri bilong Ebraham, husat Seten i bin pasim, harim, dispela 18 yia, i ken go lus long dispela kalabus long de sabat?',
        17: 'Na taim em i bin tokim ol dispela samting, olgeta birua bilong em i sem. Na olgeta manmeri i wokim amamas tru long olgeta dispela samting i gat glori em i bin mekim.',
        18: '¶ Nau em i tok, Kingdom bilong God em i olsem wanem samting? Na mi bai wokim piksa long en long wanem samting?',
        19: 'Em i olsem wanpela pikinini kaikai bilong mastet, dispela wanpela man i kisim, na tromoi insait long gaden bilong em. Na em i go bikpela, na wok long kamap wanpela bikpela diwai. Na ol pisin bilong skai i stap long ol han bilong en.',
        20: 'Na gen em i tok, Mi bai wokim piksa bilong kingdom bilong God long wanem samting?',
        21: 'Em i olsem yis, dispela wanpela meri i kisim na haitim insait long tripela hap skel plaua, inap long olgeta i gat yis.',
        22: 'Na em i go namel long ol biktaun na ol vilis, na skulim ol manmeri, na wokim wokabaut i go long Jerusalem.',
        23: '¶ Nau wanpela i tokim em, Bikpela, ating i gat liklik lain tasol husat God i kisim bek pinis? Na em i tokim ol,',
        24: 'Pait strong long go insait long liklik dua bilong banis. Long wanem, planti, mi tokim yupela, bai painim rot long go insait, na ol bai i no inap.',
        25: 'Nau taim bikman bilong haus i kirap pinis, na em i bin pasim dua, na yupela i stat long sanap ausait, na long paitim dua, i spik, Bikpela, Bikpela, opim long mipela, na em bai bekim na tokim yupela, Mi no save long yupela i kam long we,',
        26: 'Orait yupela bai stat long tok, Mipela i bin kaikai na dring long pes bilong yu, na yu bin skulim mipela long ol rot bilong mipela.',
        27: 'Tasol em bai tokim yupela, Mi tokim yupela, Mi no save long yupela i kam long we. Lusim mi, olgeta yupela ol man bilong wokim sin nogut.',
        28: 'Ol krai tru bai stap na pasin bilong kaikaim ol tit, taim yupela bai lukim Ebraham, na Aisak, na Jekop, na olgeta profet, insait long kingdom bilong God, na yupela yupela yet God i subim i go ausait.',
        29: 'Na ol bai kam long hap is, na long hap wes, na long hap not, na long hap saut, na ol bai sindaun insait long kingdom bilong God.',
        30: 'Na, lukim, i gat ol lain i las husat bai stap lain i go pas, na ol lain i go pas husat bai stap las.',
        31: '¶ Dispela de stret sampela bilong ol Farisi i kam, i spik long em, Yu go ausait, na lusim long hia. Long wanem, Herot bai kilim yu.',
        32: 'Na em i tokim ol, Yupela go, na tokim dispela foks, Lukim, mi rausim ol spirit nogut i go ausait, na mi oraitim ol man tude na tumora, na long namba tri de mi bai kamap inap tru.',
        33: 'Tasol mi mas wokabaut tude, na tumora, na long de bihain. Long wanem, em i no inap long wanpela profet i ken dai olgeta long Jerusalem.',
        34: 'O Jerusalem, Jerusalem, husat i kilim ol profet, na tromoi ol ston long kilim long ol husat God i salim long yu. Hamas taim mi bin gat laik long bungim ol pikinini bilong yu wantaim, olsem wanpela mama kakaruk i bungim lain pikinini bilong em aninit long ol wing bilong em, na yupela i no laik!',
        35: 'Lukim, God i lusim haus bilong yupela long stap nating olgeta long yupela. Na tru tumas, mi tokim yupela, Yupela bai i no inap lukim mi, inap long taim i kamap, taim yupela bai tok, Blesing i stap long em husat i kam long nem bilong Bikpela.',
    },
    14: {
        1: '¶ Na em i kamap olsem, taim em i go insait long haus bilong wanpela nambawan hetman bilong ol Farisi long kaikai bret long de sabat, long ol i was long em.',
        2: 'Na, lukim, i gat wanpela man long ai bilong em husat i gat sik dropsi.',
        3: 'Na taim Jisas i bekim tok em i tokim ol masta kot na ol Farisi, i spik, Em i orait long lo long oraitim sikman long de sabat?',
        4: 'Na ol i pasim ol maus bilong ol. Na em i kisim em, na oraitim em, na larim em i go.',
        5: 'Na em i bekim tok long ol, i spik, Husat bilong yupela bai gat wanpela donki o bulmakau man i pundaun insait long bikpela hul, na em bai i no inap pulim em i kam ausait kwiktaim long de sabat?',
        6: 'Na ol i no inap long bekim tok long em gen long ol dispela samting.',
        7: '¶ Na em i putim ensel i go ausait wanpela tok piksa long ol dispela husat ol i askim long kam, taim em i luksave long ol i bin makim ol nambawan rum olsem wanem, i spik long ol,',
        8: 'Taim wanpela man i askim yu long kam long wanpela marit, no ken sindaun long rum i antap moa olgeta, nogut em i askim wanpela man i gat ona moa long yu long kam.',
        9: 'Na em husat i askim yu long kam na em i kam na tokim yu, Givim dispela man ples bilong yu. Na yu stat, wantaim sem, long go long las rum i daunbilo olgeta.',
        10: 'Tasol taim em i askim yu long kam, go na sindaun long las rum i daunbilo olgeta. Inap long taim em husat i askim yu long kam, em i ken tokim yu, Pren, go antap moa. Nau bai yu gat lotu long pes bilong ol husat i sindaun long kaikai wantaim yu.',
        11: 'Long wanem, husat man i litimapim em yet ol bai daunim. Na em husat i daunim em yet bai ol i litimapim.',
        12: 'Nau em i tokim em tu husat i askim em long kam, Taim yu wokim wanpela bikpela kaikai o apinun kaikai, no ken singautim ol pren bilong yu, o ol brata bilong yu, o ol kandere bilong yu, o ol maniman i stap klostu long yu, nogut ol tu i askim yu gen, na ol i mekim wanpela bekim long yu.',
        13: 'Tasol taim yu wokim bikpela kaikai, singautim ol rabisman, ol man hap bilong bodi bilong ol i bagarap, ol lek nogut, ol aipas man.',
        14: 'Na blesing bai stap long yu. Long wanem, ol i no inap bekim yu. Long wanem, long kirap bek bilong ol stretpela man God bai bekim yu.',
        15: '¶ Na taim wanpela bilong ol husat i sindaun wantaim em long kaikai i harim ol dispela samting, em i tokim em, Blesing i stap long em husat bai kaikai bret long kingdom bilong God.',
        16: 'Nau em i tokim em, Wanpela man i wokim wanpela bikpela apinun kaikai, na askim planti man long kam.',
        17: 'Na em i salim wokboi bilong em, long taim bilong apinun kaikai, bilong tokim ol husat em i askim long kam, Kam. Long wanem, olgeta samting i redi nau.',
        18: 'Na ol olgeta, wantaim wanpela tingting, i stat long wokim tok nating. Namba wan i tokim em, Mi bin baim wanpela hap graun, na mi mas i gat nid long go na lukim dispela. Mi askim yu plis long lusim mi long dispela singaut.',
        19: 'Na narapela i tok, Mi bin baim faipela yok bulmakau man, na mi go long traim ol. Mi askim yu plis long lusim mi long dispela singaut.',
        20: 'Na narapela i tok, Mi bin maritim wanpela meri, na olsem na mi no inap long kam.',
        21: 'Olsem tasol dispela wokboi i kam, na soim bikman bilong em ol dispela samting. Nau bikman bilong haus, taim em i belhat, i tokim wokboi bilong em, Go ausait kwiktaim long ol rot na liklik rot bilong dispela biktaun, na bringim i kam long hia ol rabisman, na ol man hap bilong bodi bilong ol i bagarap, na ol lek nogut, na ol aipas.',
        22: 'Na wokboi i tok, Bikman, em i kamap olsem yu bin tok strong, na spes i stap yet.',
        23: 'Na bikman i tokim wokboi, Go ausait long ol bikrot na ol lain banis plaua, na pulim ol strong long kam insait, inap long haus bilong mi i ken stap pulap.',
        24: 'Long wanem, mi tokim yu, Long i no gat wanpela bilong ol dispela man husat mi bin askim long kam husat bai testim bikpela apinun kaikai bilong mi.',
        25: '¶ Na i gat wanpela traipela lain tru wantaim em. Na em i tanim, na tokim ol,',
        26: 'Sapos wanpela man i kam long mi, na em i no hetim papa bilong em, na mama, na meri, na ol pikinini, na ol brata, na ol susa, yes, na laip bilong em yet tu, em i no inap stap disaipel bilong mi.',
        27: 'Na husat man i no karim diwai kros bilong em, na kam bihainim mi, em i no inap stap disaipel bilong mi.',
        28: 'Long wanem, husat bilong yupela, taim em i gat laik long wokim wanpela taua, i no sindaun pastaim, na kaunim kos bilong en, long em i gat inap mani long pinisim dispela o nogat?',
        29: 'Nogut sapos, bihain long em i bin slipim ol as ston, na em i no inap long pinisim dispela, olgeta husat i lukim dispela i stat long wokim pani long daunim em,',
        30: 'I spik, Dispela man i stat long wokim, na em i no inap long pinisim.',
        31: 'O wanem king, taim em i go wokim bikpela pait i birua long narapela king, i no sindaun pastaim, na painim tingting long em i stap inap wantaim 10,000 long bungim em husat i kam birua long em wantaim 20,000 o nogat?',
        32: 'O sapos nogat, taim arapela i stap longwe tru yet, em i salim wanpela lain bilong ol mausman bilong gavman, na askim long ol rot bilong wokim bel isi.',
        33: 'Olsem tasol, wankain olsem, husat man i stap bilong yupela husat i no givim baksait long olgeta samting em i gat, em i no inap stap disaipel bilong mi.',
        34: 'Sol em i gutpela. Tasol sapos sol i bin lusim test bilong en, ol bai givim gutpela test long en wantaim wanem samting?',
        35: 'Em i no fit long graun, o yet long hip pekpek. Tasol ol man i tromoi dispela i go ausait. Em husat i gat ol ia long harim, larim em harim.',
    },
    15: {
        1: '¶ Nau olgeta man bilong kisim takis na ol sinman i wok long go klostu long em long harim em.',
        2: 'Na ol Farisi na ol man bilong rait i tok baksait, i spik, Dispela man i kisim ol sinman, na kaikai wantaim ol.',
        3: 'Na em i tokim ol long dispela tok piksa, i spik,',
        4: 'Wanem man bilong yupela, taim em i gat 100 sipsip, sapos wanpela i go lus long em, i no lusim dispela 99 long ples i no gat man, na go bihainim dispela samting i lus, inap long em i painim dispela pinis?',
        5: 'Na taim em i bin painim dispela pinis, em i slipim dispela long ol sol bilong han bilong em, na wokim amamas tru.',
        6: 'Na taim em i kam bek long haus bilong em, em i singautim ol pren bilong em na ol man i stap klostu long em long bung wantaim, i spik long ol, Wokim amamas tru wantaim mi. Long wanem, mi bin painim sipsip bilong mi pinis, dispela i lus.',
        7: 'Mi tokim yupela, long wankain olsem amamas tru bai stap long heven antap long wanpela sinman husat i tanim bel, moa long antap long 99 stretpela man, husat i no gat nid long tanim bel.',
        8: 'Na tu wanem meri taim em i gat tenpela hap silva, sapos wanpela hap mani i lus long em, i no laitim wanpela kandel, na brumim haus, na painim strong inap long taim em i painim dispela pinis?',
        9: 'Na taim em i bin painim dispela pinis, em i singautim ol pren bilong em na ol man i stap klostu long em long bung wantaim, i spik, Wokim amamas tru wantaim mi. Long wanem, mi bin painim pinis dispela hap mani i bin lus long mi.',
        10: 'Wankain olsem, mi tokim yupela, i gat amamas tru long pes bilong ol ensel bilong God antap long wanpela sinman husat i tanim bel.',
        11: '¶ Na em i tok, Wanpela man i gat tupela pikinini man.',
        12: 'Na pikinini i yangpela moa bilong tupela i tokim papa bilong em, Papa, givim mi hap skel bilong ol dispela kago i bai pundaun long mi. Na em i brukim long tupela ol samting bilong em.',
        13: 'Na i no planti de bihain long pikinini man i yangpela moa i bungim olgeta samting wantaim, na go long wokabaut bilong em long wanpela longwe kantri, na long dispela hap em i tromoi nating olgeta samting tru bilong em wantaim laip bilong wail pasin.',
        14: 'Na taim em i bin yusim olgeta pinis, i gat wanpela strongpela bikpela taim hangre i kirap long dispela hap graun. Na em i stat long stap sot tru long olgeta samting.',
        15: 'Na em i go na bungim em yet wantaim wanpela man bilong dispela kantri. Na em i salim em i go long ol hap graun bilong em long givim kaikai long ol pik.',
        16: 'Na em i bin gat laik long pulimapim bel bilong em wantaim ol dispela skin pipia bilong wit samting ol pik i bin kaikai. Na i no gat man i givim em.',
        17: 'Na taim em i kam long em yet, em i tok, Hamas wokboi papa bilong mi i baim i gat inap bret na moa i stap yet, na mi wok long dai olgeta long hangre!',
        18: 'Mi bai kirap na go long papa bilong mi, na mi bai tokim em, Papa, mi bin mekim sin i birua long heven, na long ai bilong yu,',
        19: 'Na mi no gat namba moa inap long ol i ken kolim mi pikinini man bilong yu. Mekim mi olsem wanpela bilong ol wokboi bilong yu yu baim.',
        20: 'Na em i kirap, na kam long papa bilong em. Tasol taim em i stap longwe tru yet, papa bilong em i lukim em, na em i gat pasin sori long em, na ran, na pundaun antap long nek bilong em, na givim kis long em.',
        21: 'Na pikinini man i tokim em, Papa, mi bin mekim sin i birua long heven, na long ai bilong yu, na mi no gat namba moa inap long ol i ken kolim mi pikinini man bilong yu.',
        22: 'Tasol papa bilong em i tokim ol wokboi bilong em, Bringim i kam dispela nambawan longpela saket, na putim long em. Na putim ring long han bilong em, na ol su long tupela fut bilong em.',
        23: 'Na bringim long hia dispela pikinini bulmakau ol i mekim patpela, na kilim. Na larim yumi kaikai, na stap amamas.',
        24: 'Long wanem, dispela pikinini man bilong mi i bin stap daiman, na em i stap laip gen. Em i bin lus, na yumi painim em pinis. Na ol i stat long stap amamas.',
        25: 'Nau pikinini man bilong em i bikpela i stap long bikpela gaden. Na taim em i kam na go klostu long haus, em i harim musik na ol man i danis.',
        26: 'Na em i singautim wanpela bilong ol wokboi, na askim long dispela samting i gat wanem mining.',
        27: 'Na em i tokim em, Brata bilong yu i kam pinis. Na papa bilong yu i bin kilim dispela pikinini bulmakau ol i mekim patpela, bilong wanem, em i bin kisim em gen orait na gutpela.',
        28: 'Na em i belhat, na em i no gat laik long go insait. Olsem na papa bilong em i kam ausait, na mekim strongpela askim long em.',
        29: 'Na em i bekim tok long papa bilong em, Harim, ol dispela planti yia mi bin wokim wok long yu, na tu mi no bin kalapim tok strong bilong yu wanpela taim. Na yet yu no bin givim wanpela pikinini meme long mi, inap long mi ken wokim amamas wantaim ol pren bilong mi.',
        30: 'Tasol long taim stret long dispela pikinini man bilong yu i kam, husat i bin kaikai olgeta samting bilong yu wantaim ol pamuk meri, yu bin kilim bilong em dispela pikinini bulmakau ol i mekim patpela.',
        31: 'Na em i tokim em, Pikinini man, yu stap wantaim mi oltaim, na olgeta samting mi gat em i bilong yu.',
        32: 'Em i fit long yumi mas wokim amamas, na stap amamas. Long wanem, dispela brata bilong yu i bin stap daiman, na em i stap laip gen. Na em i bin lus, na yumi painim em pinis.',
    },
    16: {
        1: '¶ Na em i tok tu long ol disaipel bilong em, I gat wanpela maniman, husat i gat wanpela man bilong lukautim ol samting bilong em. Na ol i sutim tok long em stret long em i bin tromoi nating ol kago bilong em.',
        2: 'Na em i singautim em, na tokim em, Olsem wanem long mi harim dispela samting long yu? Givim stori gut long wok bilong yu long lukautim ol samting. Long wanem, i ken stap olsem long yu no inap stap man bilong lukautim ol samting moa.',
        3: 'Nau dispela man bilong lukautim ol samting i toktok insait long em yet, Mi bai mekim wanem? Long wanem, bikman bilong mi i tekewe long mi dispela wok bilong lukautim ol samting. Mi no inap long digim graun. Mi sem long pulim ol mani samting.',
        4: 'Mi strong long mi bai mekim wanem, long, taim em i rausim mi long wok bilong lukautim ol samting, ol man i ken kisim mi i go insait long ol haus bilong ol.',
        5: 'Olsem na em i singautim olgeta wan wan man husat i gat dinau long bikman bilong em long kam long em, na em i tokim namba wan man, Yu dinau hamas long bikman bilong mi?',
        6: 'Na em i tok, 100 hap skel wel. Na em i tokim em, Kisim pepa i soim dinau bilong yu, na sindaun kwiktaim, na raitim 50.',
        7: 'Nau em i tokim narapela, Na yu dinau hamas? Na em i tok, 100 hap skel wit. Na em i tokim em, Kisim pepa i soim dinau bilong yu, na raitim 80.',
        8: 'Na dispela bikman i litimapim nem bilong dispela man bilong lukautim ol samting i no stretpela, bilong wanem, em i bin yusim save tru. Long wanem, ol pikinini bilong dispela graun, long lain tumbuna bilong ol, i gat save tru moa long ol pikinini bilong lait.',
        9: 'Na mi tokim yupela, Kamapim ol pren bilong yupela yet long ol mani samting bilong pasin i no stretpela. Inap long, taim yupela i fel, ol i ken kisim yupela i go insait long ol ples bilong stap oltaim oltaim.',
        10: 'Em husat yu inap bilip long em long dispela samting i liklik olgeta em i man yu inap bilip long em tu long samting i bikpela. Na em husat i no stretpela long samting i liklik olgeta em i no stretpela tu long samting i bikpela.',
        11: 'Olsem na sapos yupela i no bin stap man yu inap bilip long em long ol mani samting i no stretpela, husat bai putim long han bilong yu ol mani samting tru tru?',
        12: 'Na sapos yupela i no bin stap man yu inap bilip long em long dispela samting i bilong narapela man, husat bai givim yupela dispela samting i bilong yu yet?',
        13: 'I no gat wokboi husat i ken wokim wok long tupela bikman. Long wanem, em bai hetim wanpela, na laikim tru arapela. O sapos nogat em bai holimpas toktok bilong wanpela, na tingim arapela olsem em i samting nating. Yupela i no inap bihainim God na mani samting.',
        14: 'Na ol Farisi tu, husat i ol man bilong mangal, i harim olgeta dispela samting. Na ol i lap nogut long em.',
        15: 'Na em i tokim ol, Yupela i stap ol husat i mekim yupela yet i kamap stretpela long ai bilong ol man. Tasol God i save long ol bel bilong yupela. Long wanem, dispela samting i gat bikpela ona namel long ol man em i sting samting long ai bilong God.',
        16: 'Lo na ol profet i stap inap long Jon. I stat long dispela taim i kam inap long nau mipela i autim kingdom bilong God, na olgeta wan wan man i strong long go insait long en.',
        17: 'Na em i isi moa long heven na dispela graun long pinis, long wanpela liklik hap mak bilong lo long fel.',
        18: 'Husat man i rausim meri bilong em, na maritim narapela, i bagarapim marit long pasin pamuk. Na husat man i maritim em husat man bilong em i bin rausim i go i bagarapim marit long pamuk pasin.',
        19: '¶ I gat wanpela maniman, husat i werim purpelpela klos na ol laplap i naispela tru, na em i kaikai ol samting i dia tru olgeta wan wan de.',
        20: 'Na i gat wanpela man bilong pulim mani samting husat nem bilong em em Lasaras, husat ol i slipim long dua bilong banis bilong em, pulap long ol sua,',
        21: 'Na em i gat laik long kaikai long ol dispela pipia bilong kaikai i pundaun long tebol bilong maniman. Na moa tu ol dok i kam na rabim tang long ol sua bilong em.',
        22: 'Na em i kamap olsem, long man bilong pulim ol mani samting i dai, na ol ensel i karim em i go long bros bilong Ebraham. Maniman tu i dai, na ol i planim em.',
        23: 'Na long hel em i litimapim tupela ai bilong em, taim em i pilim ol traipela pen, na em i lukim Ebraham i stap longwe, na Lasaras long bros bilong em.',
        24: 'Na em i singaut na tok, Papa Ebraham, sori long mi, na salim Lasaras, inap long em i ken putim arere bilong pinga bilong em insait long wara liklik, na kolim tang bilong mi. Long wanem, mi pilim traipela pen long dispela paia.',
        25: 'Tasol Ebraham i tok, Pikinini man, holim tingting long yu, long taim yu stap laip, i bin kisim ol gutpela samting bilong yu, na wankain olsem Lasaras ol samting nogut. Tasol nau em i kisim bel isi, na yu pilim traipela pen.',
        26: 'Na narapela long olgeta dispela, namel long mipela na yu i gat wanpela bikpela baret tru i stap, inap long ol husat i gat laik long lusim hia i go long yu i no inap. Na tu ol i no inap kam long mipela, husat i gat laik long lusim dispela ples na kam.',
        27: 'Nau em i tok, Olsem na mi askim yu plis, papa, long yu ken salim em long haus bilong papa bilong mi.',
        28: 'Long wanem, mi gat faipela brata. Inap long em i ken tokaut klia long ol, nogut ol i kam tu long dispela ples bilong pilim traipela pen.',
        29: 'Ebraham i tokim em, Ol i gat Moses na ol profet. Larim ol harim ol.',
        30: 'Na em i tok, Nogat, papa Ebraham. Tasol sapos wanpela i lusim dai na go long ol, ol bai tanim bel.',
        31: 'Na em i tokim em, Sapos ol i no harim Moses na ol profet, bai i no gat wanpela samting i ken pulim tingting bilong ol tu, maski wanpela i kirap bek long dai.',
    },
    17: {
        1: '¶ Nau em i tokim ol disaipel, Em i no gat rot olgeta long bai ol samting i no inap kamap bilong bagarapim bel. Tasol tok lukaut i go long em, long han bilong husat ol i kam!',
        2: 'Em i gutpela moa long em long ol i hangamapim wanpela ston bilong krungutim wit nabaut long nek bilong em, na tromoi em i go long biksi, long em i ken bagarapim bel bilong wanpela bilong ol dispela liklik pikinini.',
        3: 'Was gut long yupela yet. Sapos brata bilong yu i sakim lo i birua long yu, hatim em. Na sapos em i tanim bel, lusim rong bilong em.',
        4: 'Na sapos em i sakim lo i birua long yu sevenpela taim long wanpela de, na sevenpela taim long wanpela de em i tanim gen long yu, i spik, Mi tanim bel. Yu bai lusim rong bilong em.',
        5: 'Na ol aposel i tokim Bikpela, Mekim bilip tru bilong mipela i kamap bikpela moa.',
        6: 'Na Bikpela i tok, Sapos yupela i gat bilip tru olsem wanpela pikinini kaikai bilong mastet, yupela i ken tokim dispela diwai sikamain, Kamautim yu yet wantaim ol rop daunbilo bilong yu, na planim yu yet long biksi. Na em i mas bihainim tok bilong yupela.',
        7: 'Tasol husat bilong yupela, taim em i gat wanpela wokboi i brukim graun o givim kaikai long ol bulmakau samting, bai tokim em bambai, taim em i kam bek long bikpela gaden, Go na sindaun long kaikai?',
        8: 'Na ating i yes moa long em bai tokim em, Redim wantaim wanem samting mi ken kaikai, na pasim namel bilong yu yet, na tilim kaikai long mi, inap long mi bin kaikai na dring pinis. Na bihain long en yu bai kaikai na dring?',
        9: 'Ating em i tok tenkyu long dispela wokboi bikos em i bin mekim ol dispela samting em i tok strong long em long mekim? Mi no ting.',
        10: 'Olsem tasol wankain olsem yupela, taim yupela i bin mekim olgeta dispela samting, dispela Bikpela i tok strong long yupela pinis, yupela bai tok, Mipela em ol wokboi i no gutpela bilong helpim. Mipela i bin mekim dispela samting em i wok stret bilong mipela long mekim.',
        11: '¶ Na em i kamap olsem, taim em i go long Jerusalem, long em i wokabaut namel long namel bilong Samaria na Galili.',
        12: 'Na taim em i go insait long wanpela vilis, i gat tenpela man i bungim em husat i lepraman, husat i sanap longwe.',
        13: 'Na ol i litimapim ol nek bilong ol, na tok, Jisas, Tisa, sori long mipela.',
        14: 'Na taim em i lukim ol, em i tokim ol, Go soim yupela yet long ol pris. Na em i kamap olsem, long, taim ol i go, ol i kamap klin.',
        15: 'Na wanpela bilong ol, taim em i luksave long em i orait, i tanim i kam bek, na wantaim bikpela nek em i givim glori long God,',
        16: 'Na pundaun long pes bilong em long tupela lek bilong em, na givim tok tenkyu long em. Na em i wanpela man Samaria.',
        17: 'Na Jisas i bekim tok, Ating i yes long i gat tenpela i kamap klin? Tasol dispela nainpela i stap we?',
        18: 'Yumi no lukim arapela husat i kam bek long givim glori bilong God, dispela ausait man tasol.',
        19: 'Na em i tokim em, Kirap, go long rot bilong yu. Bilip tru bilong yu i bin mekim yu kamap orait olgeta.',
        20: '¶ Na taim ol Farisi i askim strong long em, long kingdom bilong God i mas kamap long wanem taim, em i bekim ol na tok, Kingdom bilong God i no kam olsem samting ai i inap long lukim.',
        21: 'Na tu ol bai i no inap tok, Harim hia! O, harim long hap! Long wanem, lukim, kingdom bilong God i stap insait long yupela.',
        22: 'Na em i tokim ol disaipel, Ol de bai kam, taim yupela bai gat laik long lukim wanpela bilong ol de bilong Pikinini Man bilong man, na yupela bai i no inap lukim dispela.',
        23: 'Na ol bai tokim yupela, Lukim hia. O, lukim long hap. No ken go bihain long ol, o bihainim ol.',
        24: 'Long wanem, olsem lait bilong klaut, dispela i lait ausait long wanpela hap aninit long heven, i lait i go long arapela hap aninit long heven, olsem tasol tu bai Pikinini Man bilong man i stap long de bilong em.',
        25: 'Tasol pastaim em i mas karim pen long planti samting, na dispela lain tumbuna i mas tok nogat olgeta long em.',
        26: 'Na olsem em i stap long ol de bilong Noe, olsem tasol em bai stap tu long ol de bilong Pikinini Man bilong man.',
        27: 'Ol i bin kaikai, ol i dring, ol i maritim ol meri, ol i givim ol meri long maritim, inap long de long Noe i go insait long sip, na tait i kam, na bagarapim ol olgeta.',
        28: 'Wankain olsem tu em i stap long ol de bilong Lot. Ol i bin kaikai, ol i dring, ol i baim, ol i salim, ol i planim, ol i wokim ol haus.',
        29: 'Tasol long de stret long Lot i go ausait long Sodom paia na ston salfa i kam daun long heven olsem ren, na bagarapim olgeta bilong ol olgeta.',
        30: 'Yes, olsem tasol em bai stap long dispela de, taim Pikinini Man bilong man i kamap ples klia.',
        31: 'Long dispela de, em husat bai i stap antap long antap bilong haus, na ol kago bilong em insait long haus, em i no ken kam daun long tekewe dispela samting. Na em husat i stap long bikpela gaden, wankain olsem em i no ken go bek.',
        32: 'Holim tingting long meri bilong Lot.',
        33: 'Husat man bai painim rot long kisim bek laip bilong em bai lusim dispela. Na husat man bai lusim laip bilong em bai mekim dispela i stap gut yet.',
        34: 'Mi tokim yupela, long dispela nait bai i gat tupela man long wanpela bet. God bai kisim wanpela, na arapela bai i stap yet.',
        35: 'Tupela meri bai krungutim wit wantaim. God bai kisim wanpela, na arapela bai i stap yet.',
        36: 'Tupela man bai stap long bikpela gaden. God bai kisim wanpela, na arapela bai i stap yet.',
        37: 'Na ol i bekim na tokim em, We, Bikpela? Na em i tokim ol, Long wanem hap olgeta dispela bodi i stap, long dispela hap ol igal bai bung wantaim.',
    },
    18: {
        1: '¶ Na em i tokim ol long wanpela tok piksa long dispela as, long ol man i mas beten olgeta taim, na ol i no ken hap i dai,',
        2: 'I spik, I gat wanpela jas i stap long wanpela biktaun, husat i no pretim God, o tingim namba bilong man.',
        3: 'Na i gat wanpela meri man bilong em i dai pinis long dispela biktaun. Na meri i kam long em, i spik, Bekim pe nogut long helpim mi long birua bilong mi.',
        4: 'Na inap long liklik taim em i no gat laik. Tasol bihain long en em i toktok insait long em yet, Maski mi no pretim God, o tingim namba bilong man,',
        5: 'Yet bikos dispela dispela meri man bilong em i dai pinis i givim wari long mi, mi bai bekim pe nogut long helpim em, nogut taim em i kam long mi olgeta taim em i mekim mi pilim les tru.',
        6: 'Na Bikpela i tok, Harim wanem samting dispela jas i no stretpela i tok.',
        7: 'Na ating i yes long God bai bekim pe nogut bilong helpim ol lain em i makim bilong em yet, husat i singaut long em san na nait, maski em i karim hevi longpela taim wantaim ol?',
        8: 'Mi tokim yupela long em bai bekim pe nogut bilong helpim ol hariap. Tasol taim Pikinini Man bilong man i kam, bai em i lukim bilip tru long dispela graun?',
        9: '¶ Na em i toktok long dispela tok piksa long sampela husat i putim bilip long ol yet long ol i stretpela, na tingim ol arapela olsem ol i samting nating.',
        10: 'Tupela man i go antap insait long tempel long beten. Wanpela em i wanpela Farisi, na arapela em i man bilong kisim takis.',
        11: 'Dispela Farisi i sanap na beten olsem wantaim em yet, God, mi tok tenkyu long yu, long mi no stap olsem ol arapela man, ol man bilong pulim samting wantaim pasin nogut, ol man i no stretpela, ol man bilong bagarapim marit long pamuk pasin, o yes, olsem dispela man bilong kisim takis.',
        12: 'Mi tambuim kaikai tupela taim long wan wan wik, mi givim namba ten hap long olgeta samting mi gat.',
        13: 'Na dispela man bilong kisim takis, taim em i sanap longwe, i no gat laik liklik long litimapim tupela ai bilong em i go long heven, tasol em i paitim bros bilong em, i spik, God, sori long mi, wanpela sinman.',
        14: 'Mi tokim yupela, dispela man i go long haus bilong em stretpela na arapela nogat. Long wanem, olgeta wan wan husat i litimapim em yet bai God i daunim. Na em husat i daunim em yet bai God i litimapim.',
        15: '¶ Na ol i bringim long em tu ol bebi, inap long em i ken tasim ol. Tasol taim ol disaipel bilong em i lukim dispela, ol i hatim ol.',
        16: 'Tasol Jisas i singautim ol long kam long em, na tok, Larim ol liklik pikinini kam long mi, na no ken tambuim ol. Long wanem, kingdom bilong God em i bilong ol kain olsem.',
        17: 'Tru tumas, mi tokim yupela, Husat man bai i no kisim kingdom bilong God olsem wanpela liklik pikinini bai i no inap tru long go insait long en.',
        18: '¶ Na wanpela hetman i askim em, i spik, Gutpela Tisa, mi bai mekim wanem long kisim laip i stap gut oltaim oltaim olsem samting papa i givim pikinini?',
        19: 'Na Jisas i tokim em, Bilong wanem yu kolim mi gutpela? I no gat wanpela arapela i gutpela, wanpela tasol, em i olsem, God.',
        20: 'Yu save long ol tok strong, No ken bagarapim marit long pamuk pasin, No ken kilim man, No ken stil, No ken stap giaman witnes, Givim ona long papa bilong yu na mama bilong yu.',
        21: 'Na em i tok, Olgeta dispela mi bin bihainim i stat long taim mi yangpela i kam antap.',
        22: 'Nau taim Jisas i harim ol dispela samting, em i tokim em, Yet yu sot long wanpela samting. Salim olgeta samting yu gat, na tilim long ol rabisman, na yu bai gat samting i dia tru long heven. Na kam, bihainim mi.',
        23: 'Na taim em i harim dispela, em i pulap tru long bel i pilim hevi. Long wanem, em i maniman tru.',
        24: 'Na taim Jisas i luksave long em i pulap tru long bel i pilim hevi, em i tok, Klostu em i no inap tru long ol man husat i gat ol mani samting i ken go insait long kingdom bilong God!',
        25: 'Long wanem, em i isi moa long wanpela kemel i ken go namel long hul bilong nil bilong samap, long wanpela maniman i ken go insait long kingdom bilong God.',
        26: 'Na ol husat i harim dispela i tok, Husat nau God i ken kisim bek?',
        27: 'Na em i tok, Ol dispela samting ol man i no gat rot olgeta long mekim, God i gat rot long mekim.',
        28: 'Nau Pita i tok, Harim, mipela i bin lusim olgeta, na bihainim yu.',
        29: 'Na em i tokim ol, Tru tumas, mi tokim yupela, I no gat man husat i bin lusim hauslain, o papamama, o ol brata, o meri, o ol pikinini, bilong tingim kingdom bilong God,',
        30: 'Husat bai i no inap kisim planti kain kain moa long dispela taim nau, na long dispela skai na graun bilong kamap bihain, laip i stap gut oltaim oltaim.',
        31: '¶ Nau em i kisim long em dispela twelpela, na tokim ol, Lukim, yumi go antap long Jerusalem, na olgeta dispela samting ol profet i rait long sait bilong Pikinini Man bilong man bai kamap pinis.',
        32: 'Long wanem, ol bai givim em long ol man i no Ju, na ol bai wokim pani long daunim em, na mekim pasin bilong bel nogut tru long em, na spetim em.',
        33: 'Na ol bai wipim em, na mekim em long dai. Na long namba tri de em bai kirap bek gen.',
        34: 'Na ol i no kisim save long wanpela bilong ol dispela samting. Na dispela toktok i stap hait long ol, na tu ol i no save long ol dispela samting Jisas i toktok.',
        35: '¶ Na em i kamap olsem, long taim em i kam klostu long Jeriko, wanpela aipas man i sindaun klostu long sait bilong rot na pulim ol mani samting.',
        36: 'Na taim em i harim bikpela lain tru i wokabaut klostu, em i askim long dispela i gat wanem mining.',
        37: 'Na ol i tokim em, long Jisas bilong Nasaret i wokabaut klostu.',
        38: 'Na em i singaut, i spik, Jisas, yu Pikinini Man bilong Devit, sori long mi.',
        39: 'Na ol husat i go paslain i hatim em, long em i mas pasim maus bilong em. Tasol em i singaut hamas moa olsem, Yu Pikinini Man bilong Devit, sori long mi.',
        40: 'Na Jisas i sanap, na tok strong long em long ol i ken bringim em long em. Na taim em i kam klostu, em i askim em,',
        41: 'I spik, Yu gat laik long mi bai mekim wanem samting long yu? Na em i tok, Bikpela, inap long mi ken kisim strong bilong lukluk.',
        42: 'Na Jisas i tokim em, Yu kisim strong bilong lukluk. Bilip tru bilong yu i bin kisim bek yu.',
        43: 'Na wantu em i kisim strong bilong lukluk, na bihainim em, na givim glori long God. Na olgeta manmeri, taim ol i lukim dispela, i givim biknem i go long God.',
    },
    19: {
        1: '¶ Na Jisas i go insait na wokabaut namel long Jeriko.',
        2: 'Na, lukim, i gat wanpela man husat nem bilong em em Sakias, husat i nambawan hetman namel long ol man bilong kisim takis, na em i maniman.',
        3: 'Na em i painim rot long lukim Jisas em i husat. Na em i no inap, long wanem, ol man i pas pas tumas, bilong wanem, em i sotpela man.',
        4: 'Na em i ran i go paslain, na kalapim wanpela diwai sikamor long lukim em. Long wanem, em bai wokabaut long dispela rot.',
        5: 'Na taim Jisas i kam long dispela ples, em i lukluk i go antap, na lukim em, na tokim em, Sakias, hariap, na kam daun. Long wanem, mi mas i go stap long haus bilong yu tude.',
        6: 'Na em i hariap, na em i kam daun, na kisim em wantaim amamas tru.',
        7: 'Na taim ol i lukim dispela, ol olgeta i tok baksait, i spik, Long em i go long stap aninit long lukaut bilong man husat i wanpela sinman.',
        8: 'Na Sakias i sanap, na tokim Bikpela, Lukim, Bikpela, namba tu hap bilong ol kago bilong mi mi givim long ol rabisman. Na sapos mi bin kisim wanpela samting long wanpela man long wok bilong sutim tok giaman, mi bai givim bekim long em fopela taim.',
        9: 'Na Jisas i tokim em, Tude pasin bilong kisim bek i kam long dispela haus, bikos em tu em i wanpela pikinini man bilong Ebraham.',
        10: 'Long wanem, Pikinini Man bilong man i kam long painim na kisim bek dispela husat i lus.',
        11: '¶ Na taim ol i harim ol dispela samting, em i skruim tok na toktok long wanpela tok piksa, bilong wanem, em i klostu long Jerusalem, na bilong wanem, ol i ting olsem kingdom bilong God i mas kamap ples klia wantu.',
        12: 'Olsem na em i tok, Wanpela bikman i go long wanpela longwe kantri long kisim wanpela kingdom bilong em yet, na long kam bek.',
        13: 'Na em i singautim tenpela wokboi bilong em, na givim long ol tenpela paun, na tokim ol, Holimpas ples inap long mi kam.',
        14: 'Tasol ol man bilong hap bilong em i hetim em, na salim wanpela toksave i bihainim em, i spik, Mipela i no gat laik long gat dispela man long bosim kingdom long mipela.',
        15: 'Na em i kamap olsem, long taim em i kam bek, taim em i bin kisim pinis dispela kingdom, nau em i tok strong long ol i ken singautim ol dispela wokboi long kam long em, long husat em i bin givim dispela mani, inap long em i ken save long hamas olgeta wan wan man i bin winim taim em i wokim bisnis long en.',
        16: 'Nau namba wan i kam, i spik, Bikman, paun bilong yu i bin winim tenpela paun.',
        17: 'Na em i tokim em, Gutpela, yu gutpela wokboi. Bikos yu bin stap man mi inap bilip long em long wanpela liklik samting tru, nau yu gat namba long bosim tenpela biktaun.',
        18: 'Na namba tu i kam, i spik, Bikman, paun bilong yu i bin winim faipela paun.',
        19: 'Na em i tokim em wankain olsem, Yu stap tu long bosim faipela biktaun.',
        20: 'Na narapela i kam, i spik, Bikman, lukim, paun bilong yu i stap hia, dispela mi bin holimpas i slip insait long wanpela liklik laplap.',
        21: 'Long wanem, mi pret long yu, bilong wanem, yu stap wanpela hatpela man. Yu kisim dispela i kam antap yu no bin slipim i go daun, na yu kamautim dispela yu no bin planim.',
        22: 'Na em i tokim em, Ausait long maus bilong yu yet mi bai jasim yu, yu wokboi nogut. Yu save long mi wanpela hatpela man, taim mi kisim dispela i kam antap mi no bin putim i go daun, na taim mi kamautim dispela mi no bin planim.',
        23: 'Olsem wanem na nau yu no givim mani bilong mi i go long beng, inap long taim mi kam mi ken strong long askim long samting bilong mi yet wantaim winmani?',
        24: 'Na em i tokim ol husat i sanap klostu, Tekewe dispela paun long em, na givim dispela long em husat i gat tenpela paun.',
        25: '(Na ol i tokim em, Bikman, em i gat tenpela paun.)',
        26: 'Long wanem, mi tokim yupela, Long olgeta wan wan husat i gat, ol bai givim long em. Na long em husat i no gat, yes, long em ol bai tekewe dispela em i gat.',
        27: 'Tasol ol dispela birua bilong mi, husat i no gat laik long mi ken bosim kingdom long ol, bringim long hia, na kilim ol i dai long ai bilong mi.',
        28: '¶ Na taim em i bin toktok olsem, em i go paslain, na go antap long Jerusalem.',
        29: 'Na em i kamap olsem, taim em i kam klostu long Betfagi na Betani, long maunten ol i kolim maunten bilong ol Oliv, em i salim tupela bilong ol disaipel bilong em,',
        30: 'I spik, Yupela go long vilis i pas klostu long yupela. Insait long dispela, taim yupela i go insait, yupela bai lukim wanpela pikinini donki ol i pasim, we yet i no gat man i bin sindaun antap long em. Lusim em, na bringim em long hia.',
        31: 'Na sapos wanpela man i askim yupela, Bilong wanem yupela i lusim em? Yupela bai tok olsem long em, Bilong wanem, Bikpela i gat nid long em.',
        32: 'Na tupela husat Jisas i salim i go long rot bilong ol, na lukim, yes, olsem em i bin tokim ol.',
        33: 'Na taim ol i lusim pikinini donki, ol papa bilong em i tokim ol, Bilong wanem yupela i lusim dispela pikinini donki?',
        34: 'Na ol i tok, Bikpela i gat nid long em.',
        35: 'Na ol i bringim em long Jisas. Na ol i tromoi ol klos bilong ol antap long dispela pikinini donki, na ol i putim Jisas antap long em.',
        36: 'Na taim em i go, ol i opim ol klos bilong ol long rot.',
        37: 'Na taim em i kam klostu, yes, nau long taim rot i go daun long maunten bilong ol Oliv, olgeta dispela bikpela lain tru bilong ol disaipel i stat long wokim amamas tru na litimapim nem bilong God wantaim wanpela bikpela nek bilong tingim olgeta dispela strongpela wok ol i bin lukim,',
        38: 'I spik, Blesing i stap long dispela King husat i kam long nem bilong Bikpela. Bel isi long heven, na glori i go antap moa olgeta.',
        39: 'Na sampela bilong ol Farisi i stap namel long dispela bikpela lain tru i tokim em, Tisa, hatim ol disaipel bilong yu.',
        40: 'Na em i bekim na tokim ol, Mi tokim yupela long, sapos ol dispela i ken pasim maus bilong ol, wantu ol ston bai singaut.',
        41: '¶ Na taim em i kam klostu, em i lukim dispela biktaun, na krai tru antap long en,',
        42: 'I spik, Sapos yu bin save, yes yu, tasol long dispela de bilong yu, ol dispela samting i bilong bel isi bilong yu! Tasol nau ol i haitim ol long ol ai bilong yu.',
        43: 'Long wanem, ol de bai kam antap long yu, long ol birua bilong yu bai tromoi wanpela baret bilong hait raun nabaut long yu, na raunim yu raun nabaut, na holimpas yu insait long olgeta wan wan sait,',
        44: 'Na ol bai slipim yu i go stret wantaim graun, na ol pikinini bilong yu insait long yu, na ol bai i no inap lusim insait long yu wanpela ston antap long narapela. Bilong wanem, yu no bin save long taim bilong ol bilong kam lukim yu.',
        45: 'Na em i go insait long tempel, na em i stat long rausim i go ausait ol husat i salim ol samting insait long en, na ol husat i baim,',
        46: 'I spik i go long ol, Rait i stap pinis, Haus bilong mi em i haus bilong prea. Tasol yupela i bin mekim dispela i kamap hul bilong ol stilman.',
        47: 'Na em i skulim ol manmeri olgeta wan wan de insait long tempel. Tasol ol bikpris na ol man bilong rait na ol nambawan bilong ol manmeri i painim rot long bagarapim em olgeta.',
        48: 'Na ol i no inap long lukim wanem samting ol i ken mekim. Long wanem, olgeta manmeri i putim ia gut tru long harim em.',
    },
    20: {
        1: '¶ Na em i kamap olsem, long wanpela bilong ol dispela de, taim em i skulim ol manmeri insait long tempel, na autim gutnius, ol bikpris na ol man bilong rait i kam long em wantaim ol lapun hetman,',
        2: 'Na tokim em, i spik, Tokim mipela, yu kisim wanem namba long mekim ol dispela samting? O em i husat husat i givim yu dispela namba?',
        3: 'Na em i bekim na tokim ol, Mi tu bai askim yupela wanpela samting. Na bekim mi.',
        4: 'Baptais bilong Jon, em i kam long heven, ol long ol man?',
        5: 'Na ol i wok long stretim tok wantaim ol yet, i spik, Sapos yumi bai tok, Long heven, em bai tok, Bilong wanem nau yupela i no bilipim em?',
        6: 'Tasol na sapos yumi tok, Bilong ol man, olgeta bilong ol manmeri bai tromoi ston long yumi. Long wanem, ol i tingting strong long Jon i bin stap wanpela profet.',
        7: 'Na ol i bekim tok, long ol i no inap tokaut long dispela i kam long we.',
        8: 'Na Jisas i tokim ol, Na tu bai mi no inap tokim yupela long mi kisim wanem namba long mekim ol dispela samting.',
        9: '¶ Nau em i stat long toktok long ol manmeri long dispela tok piksa, Wanpela man i planim wanpela gaden wain, na em i larim dispela long ol man bilong lukautim gaden long lukautim long pe, na em i go long wanpela longwe kantri longpela taim.',
        10: 'Na long taim bilong kamautim kaikai em i salim wanpela wokboi long ol man bilong lukautim gaden, inap long ol i ken givim em kaikai bilong dispela gaden wain. Tasol ol man bilong lukautim gaden i paitim em, na salim em i go emti.',
        11: 'Na gen em i salim narapela wokboi. Na ol i paitim em tu, na mekim pasin nogut long em inap long em i sem, na salim em i go emti.',
        12: 'Na gen em i salim namba tri wokboi. Na ol i bagarapim em tu, na tromoi em i go ausait.',
        13: 'Nau bikman bilong dispela gaden wain i tok, Mi bai mekim wanem? Mi bai salim pikinini man bilong mi i stap klostu tru long bel bilong mi. Em i ken stap olsem long ol bai givim biknem tru long em taim ol i lukim em.',
        14: 'Tasol taim ol man bilong lukautim gaden i lukim em, ol i wok long stretim tok namel long ol yet, i spik, Dispela em i pikinini bilong kisim samting long papa. Kam, yumi kilim em, inap long samting papa i laik givim pikinini i ken bilong yumi.',
        15: 'Olsem tasol ol i tromoi em ausait long gaden wain, na kilim em. Olsem na, bikman bilong dispela gaden wain bai mekim wanem long ol?',
        16: 'Em bai kam na bagarapim olgeta ol dispela man bilong lukautim gaden, na em bai givim gaden wain long ol arapela. Na taim ol i harim dispela, ol i tok, I no ken tru.',
        17: 'Na em i lukim ol, na tok, Dispela rait i stap pinis nau em i wanem, Dispela ston ol wokman bilong haus i bin tok nogat olgeta long en, dispela stret i kamap het bilong kona?',
        18: 'Husat man bai pundaun antap long dispela ston bai bruk. Tasol long husat man dispela ston bai pundaun long en, em bai krungutim em i kamap paura.',
        19: 'Na ol bikpris na ol man bilong rait, long dispela aua stret, i painim rot long putim ol han antap long em. Na ol i pret long ol manmeri. Long wanem, ol i kisim save long em i bin toktok long dispela tok piksa i birua long ol.',
        20: '¶ Na ol i was long em, na salim ol man bilong lukstil i go ausait, husat i ken giaman olsem ol yet i stap ol stretpela man, inap long ol i ken holimpas ol toktok bilong em, inap long olsem tasol ol i ken givim em long pawa na namba bilong nambawan gavman.',
        21: 'Na ol i askim em, i spik, Tisa, mipela save long yu toktok na skulim ol manmeri stretpela, na tu yu no orait long tingim namba bilong wanpela man, tasol yu skulim ol manmeri long rot bilong God tru tru.',
        22: 'Em i orait long lo long mipela i ken givim takis long Sisa, o nogat?',
        23: 'Tasol Jisas i kisim save long trik pasin bilong ol, na tokim ol, Bilong wanem yupela i traim mi?',
        24: 'Soim mi wanpela peni. Em i gat piksa na rait ol i sapim bilong husat? Na ol i bekim na tok, Bilong Sisa.',
        25: 'Na em i tokim ol, Olsem na bekim long Sisa ol dispela samting i bilong Sisa, na long God ol dispela samting i bilong God.',
        26: 'Na ol i no inap long holimpas ol toktok bilong em long ai bilong ol manmeri. Na ol i tingting planti long bekim bilong em, na ol i pasim ol maus bilong ol.',
        27: '¶ Nau sampela bilong ol Sadyusi i kam long em, husat i tok nogat long i gat wanpela kirap bek long dai. Na ol i askim em,',
        28: 'I spik, Tisa, Moses i raitim long mipela, Sapos brata bilong wanpela man i dai, taim em i gat meri, na em i dai taim em i no gat pikinini, long brata bilong em i mas kisim meri bilong em, na kirapim tumbuna pikinini long brata bilong em.',
        29: 'Olsem na i gat sevenpela brata. Na namba wan i kisim wanpela meri, na em i dai taim em i no gat pikinini.',
        30: 'Na namba tu i kisim meri long maritim, na em i dai na em i no gat pikinini.',
        31: 'Na namba tri i kisim em. Na long wankain pasin dispela sevenpela tu. Na ol i no gat pikinini, na ol i dai.',
        32: 'Las long olgeta dispela meri tu i dai.',
        33: 'Olsem na long kirap bek long dai dispela meri bai meri bilong husat? Long wanem, sevenpela i bin maritim em.',
        34: 'Na Jisas i bekim tok long ol, Ol pikinini bilong dispela graun i marit, na ol i givim ol long marit.',
        35: 'Tasol ol husat God bai kaunim i gat namba inap long kisim dispela arapela skai na graun bilong kamap bihain, na kirap bek long dai, ol i no marit, na tu ol i no givim ol long marit.',
        36: 'Na tu ol i no inap dai moa liklik. Long wanem, ol i wanmak olsem ol ensel. Na ol i stap ol pikinini bilong God, taim ol i stap ol pikinini bilong kirap bek long dai.',
        37: 'Nau long sait bilong ol daiman bai kirap bek, yes, Moses i soim dispela long liklik bus, taim em i kolim Bikpela God bilong Ebraham, na God bilong Aisak, na God bilong Jekop.',
        38: 'Long wanem, em i no God bilong ol daiman, tasol bilong ol husat i stap laip. Long wanem, olgeta i stap laip long em.',
        39: '¶ Nau sampela bilong ol man bilong rait i bekim tok, Tisa, yu bin mekim gutpela toktok.',
        40: 'Na bihain long dispela ol i no gat laik long askim em wanpela askim liklik.',
        41: 'Na em i tokim ol, Ol i tok long Kraist em i pikinini man bilong Devit olsem wanem?',
        42: 'Na Devit em yet i tok long buk bilong Ol Sam, BIKPELA i tokim Bikpela bilong mi, Yu sindaun long han sut bilong mi,',
        43: 'Inap long taim mi mekim ol birua bilong yu i kamap liklik sia bilong putim lek bilong yu.',
        44: 'Olsem na Devit i kolim em Bikpela, olsem wanem nau em i pikinini man bilong em?',
        45: 'Nau long ia bilong olgeta manmeri em i tokim ol disaipel bilong em,',
        46: 'Lukaut gut long ol man bilong rait, husat i gat laik long wokabaut long ol longpela saket, na husat i laikim tru ol tok gude long ol maket, na ol sia i antap moa olgeta long ol sinagog, na ol nambawan rum long ol bikpela kaikai,',
        47: 'Husat i kaikai olgeta ol haus bilong ol meri man bilong ol i dai pinis, na bilong soim ol yet ol i mekim ol longpela prea. Ol yet bai kisim pe nogut bilong kot i bikpela moa.',
    },
    21: {
        1: '¶ Na em i lukluk i go antap, na lukim ol maniman i tromoi ol presen bilong ol i go insait long bakstua bilong samting i dia tru.',
        2: 'Na em i lukim tu wanpela rabismeri man bilong em i dai pinis i tromoi tupela mait insait long dispela hap.',
        3: 'Na em i tok, Em i tru, mi tokim yupela, long dispela rabismeri man bilong em i dai pinis i bin tromoi i go insait moa long ol olgeta.',
        4: 'Long wanem, olgeta dispela i bin tromoi bilong ol planti moa yet bilong ol i go insait long ol ofa bilong God. Tasol meri, bilong pasin bilong stap rabis tru bilong em, i bin tromoi i go insait olgeta dispela mani samting em i gat.',
        5: '¶ Na taim sampela i toktok long tempel, long ol i bin bilasim wantaim ol ston na ol presen i nambawan olsem wanem, em i tok,',
        6: 'Long sait bilong ol dispela samting yupela i lukim, ol de bai kam, long insait long dispela bai i no gat wanpela ston i stap yet antap long narapela, long ol bai i no inap tromoi i go daun.',
        7: 'Na ol i askim em, i spik, Tisa, tasol wanem taim bai ol dispela samting i stap? Na bai i gat wanem mak taim ol dispela samting bai i kamap olsem?',
        8: 'Na em i tok, Was gut long yupela i no bilipim giaman. Long wanem, planti bai kam long nem bilong mi, i spik, Mi stap Kraist, na dispela taim i kam klostu. Olsem na yupela i no ken go bihainim ol.',
        9: 'Tasol taim yupela bai harim long ol bikpela pait na ol kain trabel nabaut, no ken pret nogut tru. Long wanem, ol dispela samting mas kamap olsem pastaim. Tasol pinis i no bambai.',
        10: 'Nau em i tokim ol, Kantri bai kirap i birua long kantri, na kingdom i birua long kingdom.',
        11: 'Na ol bikpela guria bai stap long ol kain kain ples, na ol bikpela taim hangre, na ol sik nogut. Na bai i gat ol samting ai i lukim bilong mekim man i pulap long pret na ol bikpela mak i kam long heven.',
        12: 'Tasol bipo long olgeta dispela, ol bai putim ol han bilong ol antap long yupela, na givim hevi long yupela, na givim yupela i go long ol sinagog, na long ol kalabus, taim ol i bringim yupela long ai bilong ol king na ol hetman bilong tingim nem bilong mi.',
        13: 'Na em bai tanim i kam long yupela bilong wanpela testimoni.',
        14: 'Olsem na putim dispela insait long ol bel bilong yupela, long yupela i no inap tingting strong bipotaim long yupela bai bekim wanem.',
        15: 'Long wanem, mi bai givim yupela wanpela maus na save tru, dispela olgeta birua bilong yupela bai i no inap long tok birua long tok bilong yupela yet o sanap na birua long en.',
        16: 'Na ol papamama, na ol brata, na ol kandere, na ol pren wantaim bai putim yupela long han bilong birua. Na sampela bilong yupela bai ol i mekim long dai.',
        17: 'Na olgeta man bai hetim yupela bilong tingim nem bilong mi.',
        18: 'Tasol i no gat wanpela gras bilong het bilong yupela bai i pinis olgeta.',
        19: 'Long pasin bilong sanap strong long traim bilong yupela, holimpas ol tewel bilong yupela.',
        20: '¶ Na taim yupela bai lukim Jerusalem i pas raun nabaut wantaim ol ami, nau yupela i ken save long taim bilong stap nating olgeta bilong en i klostu.',
        21: 'Nau larim ol husat i stap long Judia ranawe i go long ol maunten. Na larim ol husat i stap insait long namel bilong en i go ausait. Na no ken larim ol husat i stap long ol kantri i go insait long en.',
        22: 'Long wanem, ol dispela i stap ol de bilong bekim pe nogut, inap long olgeta dispela samting ol i raitim i ken kamap pinis.',
        23: 'Tasol tok lukaut i go long ol husat i gat bel, na long ol husat i givim susu, long ol dispela de! Long wanem, bai i gat bikpela wari long dispela hap graun, na belhat tru antap long dispela lain manmeri.',
        24: 'Na ol bai pundaun long sap bilong bainat, na ol bai stiaim ol i go kalabus insait long olgeta kantri. Na ol man i no Ju bai krungutim Jerusalem i go daun, inap long ol taim bilong ol man i no Ju i ken kamap inap pinis.',
        25: 'Na bai i gat ol mak long san, na long mun, na long ol sta. Na antap long dispela graun ol kantri bai pilim bikpela wari, wantaim paul. Biksi na ol sibruk bai krai bikpela.',
        26: 'Ol bel bilong ol man bai fel, long wanem, ol i pret, na long wanem, ol i lukluk i bihainim ol dispela samting, dispela i laik kam antap long dispela graun. Long wanem, ol pawa bilong heven bai seksek.',
        27: 'Na nau ol bai lukim Pikinini Man bilong man i kam long wanpela klaut wantaim pawa na bikpela glori.',
        28: 'Na taim ol dispela samting i stat long kamap olsem, nau lukluk i go antap, na litimapim ol het bilong yupela. Long wanem, baim bek bilong yupela i kam klostu.',
        29: '¶ Na em i tokim ol long wanpela tok piksa. Lukim diwai fik, na olgeta diwai.',
        30: 'Taim nau ol i sutim kru i go ausait, yupela i lukim na save long yupela yet long taim bilong biksan i kam klostu nau.',
        31: 'Olsem tasol wankain olsem yupela, taim yupela i lukim ol dispela samting i kamap olsem, i ken save long kingdom bilong God i klostu i stap.',
        32: 'Tru tumas, mi tokim yupela, Dispela lain tumbuna bai i no inap pinis olgeta, inap long olgeta i ken kamap pinis.',
        33: 'Heven na dispela graun bai pinis olgeta. Tasol ol tok bilong mi bai i no inap pinis olgeta.',
        34: 'Na was gut long yupela yet, nogut long wanpela taim ol bel bilong yupela i pilim hevi tumas wantaim pasin bilong pulap olgeta, na spak pasin, na ol wari bilong dispela laip, na inap long dispela de i no inap kam antap long yupela hait.',
        35: 'Long wanem, olsem wanpela trap dispela bai kam antap long olgeta husat i stap long pes bilong dispela graun olgeta.',
        36: 'Olsem na yupela i mas was, na beten olgeta taim, inap long God i ken kaunim yupela i gat namba inap long ranawe long olgeta dispela samting, dispela i bai kamap olsem, na long sanap long ai bilong Pikinini Man bilong man.',
        37: 'Na long taim bilong san em i skulim ol manmeri insait long tempel. Na long nait em i go ausait, na stap long dispela maunten ol i kolim maunten bilong ol Oliv.',
        38: 'Na olgeta manmeri i kam long moningtaim tru long em insait long tempel, bilong harim em.',
    },
    22: {
        1: '¶ Nau bikpela kaikai bilong bret i no gat yis i kam klostu, dispela ol i kolim Pasova.',
        2: 'Na ol bikpris na ol man bilong rait i painim rot long ol i ken kilim em olsem wanem. Long wanem, ol i pret long ol manmeri.',
        3: 'Nau Seten i go insait long Judas i gat narapela nem Iskariot, na em i stap bilong namba bilong dispela twelpela.',
        4: 'Na em i go long rot bilong em, na stori wantaim ol bikpris na ol kepten, long em i ken putim em long han bilong ol olsem wanem.',
        5: 'Na ol i amamas, na wokim kontrak long givim em mani.',
        6: 'Na em i promis, na painim sans long putim em long han bilong ol long taim bikpela lain tru i no stap.',
        7: '¶ Nau de bilong bret i no gat yis i kam, taim ol i mas kilim pasova.',
        8: 'Na em i salim Pita na Jon, i spik, Go na redim pasova long yumi, inap long yumi ken kaikai.',
        9: 'Na tupela i tokim em, Yu gat laik long mipela i ken redim we?',
        10: 'Na em i tokim ol, Lukim, taim yutupela i go insait long biktaun, wanpela man bai bungim yutupela, taim em i karim wanpela jak wara. Bihainim em i go long haus we em i go insait long en.',
        11: 'Na yutupela bai tokim papa bilong dispela haus, Tisa i tokim yu, Rum bilong stap aninit long lukaut bilong yu i stap we, we mi bai kaikai dispela pasova wantaim ol disaipel bilong mi?',
        12: 'Na em bai soim yupela wanpela traipela rum antap i gat ol samting pinis. Long dispela hap, redim ol samting.',
        13: 'Na tupela i go, na lukim olsem em i bin tokim ol. Na tupela i redim pasova.',
        14: 'Na taim dispela aua i kam pinis, em i sindaun, na dispela twelpela aposel wantaim em.',
        15: 'Na em i tokim ol, Wantaim laik mi gat laik long kaikai dispela pasova wantaim yupela bipo mi karim pen.',
        16: 'Long wanem, mi tokim yupela, Mi bai i no inap kaikai moa liklik long en, inap long dispela i kamap pinis insait long kingdom bilong God.',
        17: 'Na em i kisim kap, na givim tok tenkyu, na tok, Kisim dispela, na brukim dispela namel long yupela yet.',
        18: 'Long wanem, mi tokim yupela, Mi bai i no inap dringim kaikai bilong diwai wain, inap long kingdom bilong God bai kam pinis.',
        19: 'Na em i kisim bret, na givim tok tenkyu, na brukim dispela, na givim long ol, i spik, Dispela em i bodi bilong mi, dispela mi givim bilong helpim yupela. Mekim dispela long holim tingting long mi.',
        20: 'Wankain olsem tu dispela kap bihain long apinun kaikai, i spik, Dispela kap em i nupela testamen long blut bilong mi, dispela mi kapsaitim bilong helpim yupela.',
        21: '¶ Tasol, lukim, han bilong em husat i putim mi long han bilong birua i stap wantaim mi long dispela tebol.',
        22: 'Na tru tumas, Pikinini Man bilong man i go, olsem God i pasim tok long em yet. Tasol tok lukaut i go long dispela man husat i putim em long han bilong birua!',
        23: 'Na ol i stat long askim namel long ol yet, long em i husat bilong ol husat i ken mekim dispela samting.',
        24: 'Na long dispela hap tu i gat strongpela pait namel long ol, husat bilong ol ol i ken kaunim nambawan moa.',
        25: 'Na em i tokim ol, Ol king bilong ol man i no Ju i hatwok long yusim namba long bosim ol. Na ol husat i hatwok long yusim namba antap long ol ol i kolim ol man bilong givim helpim.',
        26: 'Tasol yupela bai i no inap stap olsem. Tasol em husat i nambawan namel long yupela, larim em stap olsem man i yangpela moa. Na em husat i nambawan, olsem em husat i tilim kaikai.',
        27: 'Long wanem, husat i nambawan moa, em husat i sindaun long kaikai, o em husat i tilim kaikai? Ating i yes long em i em husat i sindaun long kaikai? Tasol mi sindaun namel long yupela olsem em husat i tilim kaikai.',
        28: 'Yupela em ol husat i bin stap yet wantaim mi long ol traim bilong mi.',
        29: 'Na mi makim bilong yupela wanpela kingdom, olsem Papa bilong mi i bin makim bilong mi.',
        30: 'Inap long yupela i ken kaikai na dring long tebol bilong mi long kingdom bilong mi, na sindaun antap long ol sia king na jasim dispela twelpela lain bilong Isrel.',
        31: 'Na Bikpela i tok, Saimon, Saimon, lukim, Seten i gat laik long kisim yu, inap long em i ken brukbrukim yu liklik tru olsem wit.',
        32: 'Tasol mi bin beten long yu, inap long bilip tru bilong yu i no ken fel. Na taim yu senisim bilip pinis, strongim ol brata bilong yu.',
        33: 'Na em i tokim em, Bikpela, mi stap redi long go wantaim yu, long kalabus, na long dai wantaim.',
        34: 'Na em i tok, Mi tokim yu, Pita, kakaruk man bai i no inap singaut dispela de, bipo long tripela taim yu bai tok nogat long yu save long mi.',
        35: 'Na em i tokim ol, Taim mi salim yupela na yupela i no karim paus mani, na liklik bek, na ol su, yupela i bin sot long wanpela samting? Na ol i tok, I no wanpela samting.',
        36: 'Nau em i tokim ol, Tasol nau, em husat i gat wanpela paus mani, larim em kisim dispela, na wankain olsem liklik bek bilong em. Na em husat i no gat bainat, larim em salim klos bilong em, na baim wanpela.',
        37: 'Long wanem, mi tokim yupela, long dispela samting ol i raitim pinis i mas kamap pinis yet insait long mi, Na ol i kaunim em namel long ol man bilong kalapim lo. Long wanem, ol samting long sait bilong mi i gat wanpela pinis.',
        38: 'Na ol i tok, Bikpela, lukim, tupela bainat i stap hia. Na em i tokim ol, Em inap.',
        39: '¶ Na em i kam ausait, na go, olsem em i save laikim, long maunten bilong ol Oliv. Na ol disaipel bilong em tu i bihainim em.',
        40: 'Na taim em i stap long dispela ples, em i tokim ol, Beten long yupela i no ken go insait long traim.',
        41: 'Na em i surik long ol klostu olsem man i ken tromoi ston, na em i brukim skru, na beten,',
        42: 'I spik, Papa, sapos em i laik bilong yu, rausim dispela kap long mi. Tasol i no laik bilong mi, tasol laik bilong yu, i mas kamap.',
        43: 'Na i gat i kamap ples klia long em wanpela ensel i kam long heven, na strongim em.',
        44: 'Na taim em i pilim traipela hevi em i beten strongpela moa. Na tuhat bilong em i samting olsem ol bikpela drop bilong blut i pundaun long graun.',
        45: 'Na taim em i kirap long prea, na kam long ol disaipel bilong em, em i lukim ol i slip, long wanem, ol i bel hevi,',
        46: 'Na em i tokim ol, Bilong wanem yupela i slip? Kirap na beten, nogut yupela i go insait long traim.',
        47: '¶ Na taim em i toktok yet, lukim wanpela bikpela lain tru, na em husat ol i kolim Judas, wanpela bilong dispela twelpela, i go paslain long ol, na em i go klostu long Jisas long givim kis long em.',
        48: 'Tasol Jisas i tokim em, Judas, yu putim Pikinini Man bilong man long han bilong birua wantaim wanpela kis?',
        49: 'Taim ol husat stap nabaut long em i luksave long wanem samting bai kamap bihain, ol i tokim em, Bikpela, bai mipela paitim ol wantaim bainat?',
        50: 'Na wanpela bilong ol i paitim wokboi bilong hetpris, na rausim han sut ia bilong em olgeta.',
        51: 'Na Jisas i bekim na tok, Yupela larim ol inap olsem. Na em i tasim ia bilong em, na oraitim em.',
        52: 'Nau Jisas i tokim ol bikpris, na ol kepten bilong tempel, na ol lapun hetman, husat i kam long em, Yupela i kam ausait, olsem yupela i birua long wanpela stilman, wantaim ol bainat na ol stik bilong pait?',
        53: 'Taim mi stap wantaim yupela olgeta wan wan de insait long tempel, yupela i no stretim ol han i go ausait i birua long mi. Tasol dispela em i aua bilong yupela, na pawa bilong tudak.',
        54: '¶ Nau ol i kisim em, na stiaim em, na bringim em i go insait long haus bilong hetpris. Na Pita i bihainim ol longwe.',
        55: 'Na taim ol i bin kirapim wanpela paia insait long namel bilong dispela bikpela rum, na sindaun pinis wantaim, Pita i sindaun namel long ol.',
        56: 'Tasol wanpela yangpela meri i lukim em taim em i sindaun klostu long paia, na em i lukluk strong long em, na tok, Dispela man tu i stap wantaim em.',
        57: 'Na em i tok nogat, i spik, Meri, mi no save long em.',
        58: 'Na bihain long liklik taim, narapela i lukim em, na tok, Yu tu i stap wanpela bilong ol. Na Pita i tok, Man, mi nogat.',
        59: 'Na klostu olsem taim bilong wanpela aua bihain narapela i tok yes wantaim strongpela bilip, i spik, Em i tru dispela man tu i bin stap wantaim em. Long wanem, em i man Galili.',
        60: 'Na Pita i tok, Man, mi no save long yu tok wanem. Na wantu, taim em i toktok yet, dispela kakaruk man i singaut.',
        61: 'Na Bikpela i tanim, na lukluk long Pita. Na Pita i holim tingting long dispela tok bilong Bikpela, long em i bin tokim em olsem wanem, Bipo long kakaruk man i singaut, yu bai tok nogat long mi tripela taim.',
        62: 'Na Pita i go ausait, na krai tru wantaim bel i bagarap tru.',
        63: '¶ Na ol man husat i holimpas Jisas i wokim pani long daunim em, na paitim em.',
        64: 'Na taim ol i bin pasim tupela ai bilong em wantaim laplap, ol i paitim em long pes, na askim em, i spik, Autim tok profet, em i husat husat i paitim yu?',
        65: 'Na planti arapela samting ol i tok birua long em wantaim ol tok bilas.',
        66: 'Na long taim stret long san i kamap pinis, ol lapun hetman bilong ol manmeri na ol bikpris na ol man bilong rait i kam bung wantaim, na stiaim em i go long kaunsil bilong ol, i spik,',
        67: 'Yu stap dispela Kraist? Tokim mipela. Na em i tokim ol, Sapos mi tokim yupela, yupela bai i no inap bilip.',
        68: 'Na sapos mi askim yupela tu, yupela bai i no inap bekim tok long mi, o larim mi go.',
        69: 'Bihain long nau bai Pikinini Man bilong man i sindaun long han sut bilong pawa bilong God.',
        70: 'Nau ol olgeta i tok, Yu stap nau dispela Pikinini Man bilong God? Na em i tokim ol, Yupela i tok olsem long mi.',
        71: 'Na ol i tok, Yumi gat wanem nid long sampela witnes moa? Long wanem, yumi yumi yet i bin harim long maus bilong em yet.',
    },
    23: {
        1: '¶ Na bikpela lain tru bilong ol olgeta i kirap, na stiaim em i go long Pailat.',
        2: 'Na ol i stat long sutim tok long em, i spik, Mipela i lukim dispela man i paulim dispela kantri, na em i tambuim ol man long givim takis long Sisa, taim em i tok long em em yet em i Kraist, wanpela King.',
        3: 'Na Pailat i askim em, i spik, Yu stap King bilong ol Ju? Na em i bekim em na tok, Yu tok olsem.',
        4: 'Nau Pailat i tokim ol bikpris na ol manmeri, Mi no lukim wanpela asua long dispela man.',
        5: 'Na ol i strong tru moa, i spik, Em i kirapim ol manmeri, taim em i skulim ol manmeri namel long olgeta hap bilong ol Ju, i stat long Galili i kam inap long dispela ples.',
        6: 'Taim Pailat i harim long Galili, em i askim long man em i man Galili o nogat.',
        7: 'Na long taim stret long em i save long em i bilong hap Herot i bosim, em i salim em long Herot, husat em yet tu i stap long Jerusalem long dispela taim.',
        8: 'Na taim Herot i lukim Jisas, em i amamas planti moa yet. Long wanem, em i gat laik long lukim em longpela taim, bilong wanem, em i bin harim ol planti samting long em. Na em i gat hop long lukim em wokim wanpela mirakel.',
        9: 'Nau em i mekim askim long em long planti toktok. Tasol em i no bekim em long wanpela samting.',
        10: 'Na ol bikpris na ol man bilong rait i sanap na sutim tok long em strong nogut tru.',
        11: 'Na Herot wantaim ol man bilong bikpela pait bilong em i mekim olsem em i samting nating, na wokim pani long daunim em, na putim wanpela longpela saket i naispela nogut tru long em, na salim em gen long Pailat.',
        12: 'Na dispela de stret Pailat na Herot i kamap ol poroman wantaim. Long wanem, bipo ol gat pasin birua namel long ol yet.',
        13: '¶ Na Pailat, taim em i bin singautim ol bikpris na ol hetman na ol manmeri long bung wantaim,',
        14: 'Em i tokim ol, Yupela i bin bringim dispela man long mi, olsem wanpela husat i paulim ol manmeri. Na, lukim, mi, taim mi bin skelim em gut long ai bilong yupela, i no bin painim wanpela asua long dispela man long sait bilong ol dispela samting we yupela i sutim tok long em long en.',
        15: 'Nogat, o yet Herot. Long wanem, mi salim yupela long em. Na, harim, i no gat wanpela samting inap long em i ken dai ol i mekim long em.',
        16: 'Olsem na mi bai stikim em, na lusim em.',
        17: '(Long wanem, i gat nid long em i mas lusim wanpela long ol long dispela bikpela kaikai.)',
        18: 'Na ol olgeta wantaim i singaut long wanpela taim, i spik, Rausim dispela man i go, na lusim Barabas long mipela,',
        19: '(Husat long wanpela pasin bilong bikhet long gavman em i wokim insait long biktaun, na long pasin bilong kilim man, ol i tromoi em long kalabus.)',
        20: 'Olsem na Pailat, taim em i gat laik long lusim Jisas, i toktok gen long ol.',
        21: 'Tasol ol i singaut, i spik, Nilim em long diwai kros, nilim em long diwai kros.',
        22: 'Na em i tokim ol namba tri taim, Bilong wanem, em i bin mekim wanem pasin nogut? Mi no bin lukim insait long em wanpela as bilong em i ken dai. Olsem na mi bai stikim em, na larim em i go.',
        23: 'Na ol i strongpela wantaim ol bikpela nek, taim ol i strong long askim long em i ken nilim em long diwai kros. Na ol nek bilong ol na bilong ol bikpris i win.',
        24: 'Na Pailat i givim mekim save long em i ken stap olsem ol i strong long askim.',
        25: 'Na em i lusim i go long ol em husat long pasin bilong bikhet long gavman na pasin bilong kilim man ol i bin tromoi long kalabus, husat ol i bin gat laik long kisim. Tasol em i givim Jisas i go long laik bilong ol.',
        26: '¶ Na taim ol i stiaim em i go, ol i holimpas wanpela Saimon, wanpela man Sairini, taim em i kam ausait long dispela hap, na antap long em ol slipim diwai kros, inap long em i ken karim dispela bihain long Jisas.',
        27: 'Na i gat wanpela bikpela lain bilong ol manmeri i bihainim em, na bilong ol meri, husat tu i krai wantaim singaut na krai sori long em.',
        28: 'Tasol Jisas, taim em i tanim long ol, i tok, Ol pikinini meri bilong Jerusalem, no ken krai tru long mi, tasol krai tru long yupela yet, na long ol pikinini bilong yupela.',
        29: 'Long wanem, lukim, ol de i wok long kam, insait long dispela ol bai tok, Blesing i stap long meri i no inap long karim, na long ol bel husat i no bin karim, na dispela ol ai bilong susu i no bin givim susu.',
        30: 'Nau ol bai stat long toktok long ol maunten, Pundaun antap long mipela. Na long ol liklik maunten, Karamapim mipela.',
        31: 'Long wanem, sapos ol i mekim ol dispela samting taim diwai i grinpela, ol bai mekim wanem long taim diwai i drai?',
        32: '¶ Na i gat tu tupela arapela, ol raskol, ol i stiaim ol wantaim em long mekim ol i dai.',
        33: 'Na taim ol i kam long dispela ples, dispela ol i kolim Kalvari, ol i nilim em long diwai kros long dispela hap, na tupela raskol, wanpela long han sut sait, na arapela long han kais sait.',
        34: 'Nau Jisas i tok, Papa, lusim sin bilong ol. Long wanem, ol i no save long ol i mekim wanem. Na ol i tilim ol klos bilong em, na tromoi ol satu.',
        35: 'Na ol manmeri i sanap na lukluk i stap. Na ol hetman tu wantaim ol i lap nogut long em, i spik, Em i kisim bek ol arapela. Larim em kisim bek em yet, sapos em i Kraist, man God i makim.',
        36: 'Na ol soldia tu i wokim pani long daunim em, taim ol i kam long em, na tokim em long kisim vinega,',
        37: 'Na spik, Sapos yu stap king bilong ol Ju, kisim bek yu yet.',
        38: 'Na ol i raitim tu wanpela rait ol i sapim antap long em long ol leta bilong tok ples bilong Grik, na Latin, na Hibru, DISPELA EM I KING BILONG OL JU.',
        39: 'Na wanpela bilong dispela tupela raskol ol i hangamapim i toktok bilong daunim em tru, i spik, Sapos yu stap Kraist, kisim bek yu yet na mitupela.',
        40: 'Tasol arapela i bekim tok na hatim em, i spik, Ating i yes long yu pret long God, taim yu luksave olsem yu stap long dispela wankain pe nogut bilong kot?',
        41: 'Na em i stretpela tru tru long yumitupela. Long wanem, yumitupela i kisim pe stret long ol wok bilong yumi. Tasol dispela man i no bin wokim wanpela samting i rong.',
        42: 'Na em i tokim Jisas, Bikpela, holim tingting long mi taim yu kam long kingdom bilong yu.',
        43: 'Na Jisas i tokim em, Tru tumas, mi tokim yu, Tude bai yu stap wantaim mi long paradais.',
        44: '¶ Na em i klostu olsem long namba sikis aua, na i gat wanpela tudak i karamapim olgeta dispela graun i go inap long namba nain aua.',
        45: 'Na san i go tudak, na laplap bilong tempel i bruk long namel bilong en.',
        46: 'Na taim Jisas i bin singaut wantaim bikpela nek, em i tok, Papa, mi givim spirit bilong mi i go long tupela han bilong yu. Na taim em i bin tok olsem, em i lusim spirit bilong em.',
        47: 'Nau taim dispela kepten bilong 100 soldia i lukim wanem samting i kamap, em i givim glori long God, i spik, Tru olgeta, dispela em i wanpela stretpela man.',
        48: 'Na olgeta manmeri husat i kam bung wantaim long dispela samting ai i ken lukim, taim ol i lukim ol dispela samting i kamap, i paitim ol bros bilong ol, na go bek.',
        49: 'Na olgeta man em i save long ol, na ol meri husat i bihainim em long Galili, i sanap longwe, na lukim ol dispela samting.',
        50: '¶ Na, lukim, i gat wanpela man i stap husat nem bilong em em Josep, wanpela man bilong givim tok helpim. Na em i gutpela man, na stretpela.',
        51: '(Em yet i no bin tok yes long tok helpim na wok ol i mekim.) Em i bilong Arimatia, wanpela biktaun bilong ol Ju. Husat em yet tu i wetim kingdom bilong God.',
        52: 'Dispela man i go long Pailat, na askim long pulim bodi bilong Jisas.',
        53: 'Na em i kisim dispela i go daun, na tantanim insait long naispela laplap, na slipim dispela long wanpela matmat, dispela ol i katim long ston, we ol i no bin slipim man insait long en bipo.',
        54: 'Na dispela de em i de bilong redim, na sabat i wok long kam klostu.',
        55: 'Na ol meri tu, husat i kam wantaim em long Galili, i kam bihain, na lukim matmat, na ol mam i slipim bodi bilong em olsem wanem.',
        56: 'Na ol i go bek na redim ol spais na ol wel i gat marasin. Na ol i malolo long de sabat bilong bihainim tok strong.',
    },
    24: {
        1: '¶ Nau long namba wan de bilong wik, long moningtaim tru tru, ol i kam long matmat, na bringim ol dispela spais ol i bin redim, na sampela arapela i kam wantaim ol.',
        2: 'Na ol i luksave long ol i bin tantanim ston i lusim matmat.',
        3: 'Na ol i go insait, na ol i no lukim bodi bilong Bikpela Jisas.',
        4: 'Na em i kamap olsem, taim ol i paul planti long dispela hap nabaut, lukim, tupela man i sanap klostu long ol long ol klos i lait tru.',
        5: 'Na taim ol i pret, na lindaunim ol pes bilong ol long graun, ol i tokim ol, Bilong wanem yupela i painim man i stap laip namel long ol daiman?',
        6: 'Em i no stap hia, tasol em i kirap bek. Tingim gen long em i bin tokim yupela olsem wanem taim em i stap yet long Galili,',
        7: 'I spik, Ol i mas givim Pikinini Man bilong man i go long ol han bilong ol man i pulap long sin, na nilim em long diwai kros, na namba tri de em i mas kirap bek gen.',
        8: 'Na ol i tingim gen ol toktok bilong em,',
        9: 'Na ol i go bek i lusim matmat, na tokim olgeta dispela samting long dispela elevenpela, na long olgeta arapela.',
        10: 'Em i Maria Makdalin, na Joana, na Maria mama bilong Jems, na ol arapela meri husat i stap wantaim ol, husat i tokim ol dispela samting i go long ol aposel.',
        11: 'Na ol toktok bilong ol i luk olsem long ol olsem ol stori nating, na ol i no bilipim ol.',
        12: 'Nau Pita i kirap, na ran i go long matmat. Na taim em i lindaun, em i lukim ol klos bilong naispela laplap i slip ol yet, na em i lusim hap, na tingting planti insait long em yet long dispela samting i kamap olsem.',
        13: '¶ Na, lukim, tupela bilong ol i go long dispela de stret long wanpela vilis ol i kolim Emeas, dispela i stap long Jerusalem klostu olsem 60 furlong.',
        14: 'Na tupela i toktok wantaim long olgeta dispela samting, dispela i bin kamap.',
        15: 'Na em i kamap olsem, long, taim tupela i stori wantaim na wok long stretim tok, Jisas em yet i kam klostu, na go wantaim ol.',
        16: 'Tasol ol ai bilong ol i pas inap long ol i no ken save long em.',
        17: 'Na em i tokim ol, Ol dispela em ol wanem kain toktok, dispela yupela i gat wanpela i go long narapela, taim yupela i wokabaut, na yupela i pilim hevi?',
        18: 'Na wanpela bilong tupela, husat nem bilong em em Kliopas, i bekim tok long em, Ating yu wanpela ausait man tasol long Jerusalem, na yu no bin save long ol dispela samting i kamap olsem long dispela hap long ol dispela de?',
        19: 'Na em i tokim tupela, Wanem ol samting? Na ol i tokim em, Long sait bilong Jisas bilong Nasaret, husat i wanpela strongpela profet long wok na tok long ai bilong God na olgeta manmeri.',
        20: 'Na long ol bikpris na ol hetman bilong mipela i bin givim em olsem wanem long mekim em lus long kot i go long dai, na long ol i bin nilim em long diwai kros.',
        21: 'Tasol mipela i putim bilip long em i bin stap em husat i mas baim bek Isrel. Na narapela long olgeta dispela, tude em i namba tri de bihain long ol i bin mekim ol dispela samting.',
        22: 'Yes, na sampela meri tu bilong lain bilong mipela i bin mekim mipela kirap nogut, husat i stap long moning tru long matmat.',
        23: 'Na taim ol i no lukim bodi bilong em, ol i kam, na spik, long ol i bin lukim tu wanpela driman samting bilong ol ensel, husat i tok long em i stap laip.',
        24: 'Na sampela bilong ol husat i stap wantaim mipela i go long matmat, na lukim dispela, yes, olsem ol meri i bin toktok. Tasol ol i no lukim em.',
        25: 'Nau em i tokim ol, O ol krankiman, na ol man bel i no hariap long bilipim olgeta samting ol profet i bin toktok.',
        26: 'Ating i yes long Kraist i mas pilim pen long ol dispela samting, na long go insait long glori bilong em?',
        27: 'Na i stat long Moses na olgeta profet, em i kolim gut long ol, long olgeta rait bilong God, ol samting long sait bilong em yet.',
        28: 'Na ol i kam klostu long dispela vilis, we ol i go. Na em i mekim olsem em i gat laik long go moa.',
        29: 'Tasol ol i pulim em strong, i spik, Stap wantaim mipela. Long wanem, em i go long apinun tru, na klostu de em i lus pinis. Na em i go insait long stap yet wantaim ol.',
        30: 'Na em i kamap olsem, taim em i sindaun wantaim ol long kaikai, em i kisim bret, na blesim dispela, na brukim, na givim long tupela.',
        31: 'Na ol ai bilong tupela i op, na ol i save long em. Na em i go pinis olgeta i lusim hap ai bilong ol i ken lukim.',
        32: 'Na tupela i tok wanpela i go long narapela, Ating i yes long bel bilong yumitupela i bin kuk insait long yumitupela, taim em i toktok wantaim yumitupela long rot, na taim em i opim ol rait bilong God long yumitupela?',
        33: 'Na ol i kirap long dispela aua stret, na go bek long Jerusalem, na lukim dispela elevenpela i bung wantaim, na ol husat i stap wantaim ol,',
        34: 'I spik, Bikpela i bin kirap bek tru tru, na em i bin kamap ples klia long Saimon.',
        35: 'Na ol i tokaut long wanem ol samting i kamap long rot, na long ol i save long em long taim em i brukim bret olsem wanem.',
        36: '¶ Na taim ol i toktok olsem, Jisas em yet i sanap namel long ol, na tokim ol, Bel isi i ken stap long yupela.',
        37: 'Tasol ol i pret nogut tru na pret, na ol i ting olsem long ol i bin lukim wanpela spirit.',
        38: 'Na em i tokim ol, Bilong wanem yupela i pilim wari? Na bilong wanem ol tingting bilong yupela i kirap insait long ol bel bilong yupela?',
        39: 'Lukim tupela han bilong mi na tupela fut bilong mi, long dispela em mi mi yet. Putim han long mi, na luksave. Long wanem, wanpela spirit i no gat bodi na ol bun, olsem yupela i luksave long mi gat.',
        40: 'Na taim em i bin toktok olsem, em i soim ol tupela han bilong em na tupela fut bilong em.',
        41: 'Na taim ol i no bilip yet, long wanem, ol i amamas tru, na tingting planti, em i tokim ol, Yupela i gat sampela kaikai long hia?',
        42: 'Na ol i givim em wanpela hap bilong wanpela pis ol i kukim long paia, na bilong wanpela kom bilong hani.',
        43: 'Na em i kisim dispela, na em i bin kaikai long ai bilong ol.',
        44: 'Na em i tokim ol, Ol dispela em ol toktok, dispela mi tokim yupela, taim mi stap yet wantaim yupela, long olgeta samting i mas kamap pinis, dispela ol i raitim long lo bilong Moses, na long ol profet, na long ol sam, long sait bilong mi.',
        45: 'Nau em i opim save bilong ol, inap long ol i ken kisim save long ol rait bilong God,',
        46: 'Na em i tokim ol, Rait i stap pinis olsem, na em i gutpela olsem long Kraist long pilim pen, na long kirap bek long dai namba tri de.',
        47: 'Na long nem bilong em ol i ken autim tok long tanim bel na pasin bilong lusim ol sin namel long olgeta kantri, i stat long Jerusalem.',
        48: 'Na yupela i stap ol witnes bilong ol dispela samting.',
        49: 'Na, lukim, mi salim promis bilong Papa bilong mi antap long yupela. Tasol yupela i mas stap yet long biktaun bilong Jerusalem, inap long yupela i pulap wantaim pawa i kam long antap.',
        50: '¶ Na em i stiaim ol i go ausait i go inap long Betani, na em i litimapim tupela han bilong em, na blesim ol.',
        51: 'Na em i kamap olsem, taim em i blesim ol, em i lusim ol, na God i karim em i go antap long heven.',
        52: 'Na ol i lotuim em, na go bek long Jerusalem wantaim bikpela amamas tru.',
        53: 'Na ol i stap olgeta taim long tempel, na litimapim nem na blesim God. Amen.',
    },
}
